// Generated by scripts/sync-rule-pages.mjs from the Example, Why, How to fix, When to ignore,
// and Quirks sections of each rule page. Do not edit by hand: edit the page under rules/ and
// rerun the script.
import type { RuleHelp } from "@pbiplint/core";

/** SARIF help per rule id: the page's Example, Why, How to fix, When to ignore, and Quirks sections, plus a link to the page. */
export const RULE_HELP: Readonly<Record<string, RuleHelp>> = {
  ADD_DATA_CATEGORY_FOR_COLUMNS: {
    text: "Example\n\nFires the rule\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer ID\n\n\tcolumn City\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: City\n\nAfter the fix\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer ID\n\n\tcolumn City\n\t\tdataType: string\n\t\tdataCategory: City\n\t\tsummarizeBy: none\n\t\tsourceColumn: City\n\nWhy it matters\n\nMap visuals bind a field by its data category, not by its name. Without one, a City column is geocoded by guesswork and can land in the wrong country when names repeat, and Latitude and Longitude are treated as ordinary numbers, so they are summed by default and the map draws a single point in the ocean. The category lives on the model, so every report inherits it once it is set, and it costs nothing at refresh or query time.\n\nHow to fix it\n\nIn Power BI Desktop, select the column in the Data pane, open Column tools, and pick the Data category. In the TMDL file, add the property under the column: dataCategory: City, dataCategory: Country, dataCategory: Continent, dataCategory: Latitude, or dataCategory: Longitude. The property is metadata only, so setting it changes nothing about what the refresh loads or how the column compresses.\n\nWhen to ignore it\n\nA column the name test catches that holds no geography is the case to look for first: Country Manager is a person, City Code is an internal code nobody plots, and giving either a data category would be wrong rather than merely unnecessary. A latitude and longitude pair that only ever feeds a distance calculation is in the same position, since nothing binds it to a map. Where the column really is a place name and a report shows it on a map, there is no reason to leave the category off.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = ADD_DATA_CATEGORY_FOR_COLUMNS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"ADD_DATA_CATEGORY_FOR_COLUMNS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The country, continent, and city tests are substrings, matched without regard to letter case, so a text column called City Code or Country Manager is reported. Latitude and longitude must be the whole name, also without regard to case.\n- The type gate goes with the name. A Country column stored as a whole number is not reported, and neither is a Latitude column stored as text, because the rule wants text for the first group and decimal or double for the second.\n- Only the presence of a category is tested, not which one it is, so any value clears the finding. A City column given a Web URL category passes.\n\nRead more: https://pbiplint.com/rules/add-data-category-for-columns",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer ID\n\n\tcolumn City\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: City\n```\n\n**After the fix**\n\n```tmdl\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer ID\n\n\tcolumn City\n\t\tdataType: string\n\t\tdataCategory: City\n\t\tsummarizeBy: none\n\t\tsourceColumn: City\n```\n\n### Why it matters\n\nMap visuals bind a field by its data category, not by its name. Without one, a City column is geocoded by guesswork and can land in the wrong country when names repeat, and Latitude and Longitude are treated as ordinary numbers, so they are summed by default and the map draws a single point in the ocean. The category lives on the model, so every report inherits it once it is set, and it costs nothing at refresh or query time.\n\n### How to fix it\n\nIn Power BI Desktop, select the column in the Data pane, open Column tools, and pick the Data category. In the TMDL file, add the property under the column: `dataCategory: City`, `dataCategory: Country`, `dataCategory: Continent`, `dataCategory: Latitude`, or `dataCategory: Longitude`. The property is metadata only, so setting it changes nothing about what the refresh loads or how the column compresses.\n\n### When to ignore it\n\nA column the name test catches that holds no geography is the case to look for first: Country Manager is a person, City Code is an internal code nobody plots, and giving either a data category would be wrong rather than merely unnecessary. A latitude and longitude pair that only ever feeds a distance calculation is in the same position, since nothing binds it to a map. Where the column really is a place name and a report shows it on a map, there is no reason to leave the category off.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = ADD_DATA_CATEGORY_FOR_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"ADD_DATA_CATEGORY_FOR_COLUMNS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The country, continent, and city tests are substrings, matched without regard to letter case, so a text column called City Code or Country Manager is reported. Latitude and longitude must be the whole name, also without regard to case.\n- The type gate goes with the name. A Country column stored as a whole number is not reported, and neither is a Latitude column stored as text, because the rule wants text for the first group and decimal or double for the second.\n- Only the presence of a category is tested, not which one it is, so any value clears the finding. A City column given a Web URL category passes.\n\nRead more: https://pbiplint.com/rules/add-data-category-for-columns",
  },
  "AVOID_BI-DIRECTIONAL_RELATIONSHIPS_AGAINST_HIGH-CARDINALITY_COLUMNS": {
    text: "Why it matters\n\nA bi-directional relationship makes the engine propagate filters both ways on every query that touches either table. On a key with a few hundred values that is cheap. On a key with hundreds of thousands of values, the expanded filter list is built and applied on every evaluation, and the cost shows up as slow visuals that look innocent in the model view.\n\nHow to fix it\n\nFind the cardinality first. In Power BI Desktop's DAX query view, run a query such as EVALUATE ROW(\"n\", DISTINCTCOUNT('Sales'[Order ID])) for each column in a bi-directional relationship. Then set the relationship back to single direction in the model view, or remove crossFilteringBehavior: bothDirections from it in the TMDL file, and where one report needs the reverse filter, get it from a measure with CROSSFILTER or TREATAS. DAX Studio's VertiPaq Analyzer shows every column's cardinality at once, and if you already use Tabular Editor, the walkthrough under Links loads the same statistics into its Best Practice Analyzer, which can then run this rule directly.\n\nRead more: https://pbiplint.com/rules/avoid-bi-directional-relationships-against-high-cardinality-columns",
    markdown:
      "### Why it matters\n\nA bi-directional relationship makes the engine propagate filters both ways on every query that touches either table. On a key with a few hundred values that is cheap. On a key with hundreds of thousands of values, the expanded filter list is built and applied on every evaluation, and the cost shows up as slow visuals that look innocent in the model view.\n\n### How to fix it\n\nFind the cardinality first. In Power BI Desktop's DAX query view, run a query such as `EVALUATE ROW(\"n\", DISTINCTCOUNT('Sales'[Order ID]))` for each column in a bi-directional relationship. Then set the relationship back to single direction in the model view, or remove `crossFilteringBehavior: bothDirections` from it in the TMDL file, and where one report needs the reverse filter, get it from a measure with CROSSFILTER or TREATAS. DAX Studio's VertiPaq Analyzer shows every column's cardinality at once, and if you already use Tabular Editor, the walkthrough under Links loads the same statistics into its Best Practice Analyzer, which can then run this rule directly.\n\nRead more: https://pbiplint.com/rules/avoid-bi-directional-relationships-against-high-cardinality-columns",
  },
  AVOID_DUPLICATE_MEASURES: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Sales Amount' = SUM( Sales[Amount] )\n\t\tformatString: #,0\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nTwo names for one calculation split the reader's trust: nobody can tell which is the real one, reports end up using both, and the next change gets made to one copy only. When both appear in the same visual the engine also evaluates them separately, so the duplicate costs query time as well as confusion.\n\nHow to fix it\n\nDecide which name stays, repoint the visuals that use the other one, and delete it. In Power BI Desktop, right-click the measure in the Data pane and choose Delete from model. In the TMDL file, remove its measure block from the table.\n\nWhere published reports still bind to the second name, the interim step is to make it a plain reference to the survivor:\n\nSales Amount = [Total Sales]\n\nThat leaves one definition, so this rule stops reporting the pair, and it moves the finding to MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES until the reports are moved and the alias goes.\n\nWhen to ignore it\n\nTwo measures that are identical only by accident of timing are worth keeping apart: Freight Cost and Handling Cost both reading the same column because the split in the source has not landed yet will diverge the week it does, and merging them now only means writing one of them again. Check whether the two names mean different things to the business before you delete either. Where they mean the same thing, there is nothing to weigh.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = AVOID_DUPLICATE_MEASURES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"AVOID_DUPLICATE_MEASURES\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The comparison is exact apart from whitespace: spaces, tabs, carriage returns, and line breaks are removed from both expressions before they are compared. An expression laid out over several lines matches the same expression written on one.\n- The comparison is case sensitive, so SUM(Sales[Amount]) and sum(Sales[Amount]) are not duplicates here even though DAX treats them as the same expression.\n- A comment on either copy makes them differ, so the same calculation with a note on one of them is not reported.\n- Only the measure expression is read. Two measures with the same expression are a duplicate pair whatever their format strings say, and a difference in a dynamic format string does not separate them either.\n- Measures only. Two calculated columns or two calculation items with the same expression are not compared.\n\nRead more: https://pbiplint.com/rules/avoid-duplicate-measures",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Sales Amount' = SUM( Sales[Amount] )\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nTwo names for one calculation split the reader's trust: nobody can tell which is the real one, reports end up using both, and the next change gets made to one copy only. When both appear in the same visual the engine also evaluates them separately, so the duplicate costs query time as well as confusion.\n\n### How to fix it\n\nDecide which name stays, repoint the visuals that use the other one, and delete it. In Power BI Desktop, right-click the measure in the Data pane and choose Delete from model. In the TMDL file, remove its `measure` block from the table.\n\nWhere published reports still bind to the second name, the interim step is to make it a plain reference to the survivor:\n\n```\nSales Amount = [Total Sales]\n```\n\nThat leaves one definition, so this rule stops reporting the pair, and it moves the finding to `MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES` until the reports are moved and the alias goes.\n\n### When to ignore it\n\nTwo measures that are identical only by accident of timing are worth keeping apart: Freight Cost and Handling Cost both reading the same column because the split in the source has not landed yet will diverge the week it does, and merging them now only means writing one of them again. Check whether the two names mean different things to the business before you delete either. Where they mean the same thing, there is nothing to weigh.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_DUPLICATE_MEASURES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"AVOID_DUPLICATE_MEASURES\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The comparison is exact apart from whitespace: spaces, tabs, carriage returns, and line breaks are removed from both expressions before they are compared. An expression laid out over several lines matches the same expression written on one.\n- The comparison is case sensitive, so `SUM(Sales[Amount])` and `sum(Sales[Amount])` are not duplicates here even though DAX treats them as the same expression.\n- A comment on either copy makes them differ, so the same calculation with a note on one of them is not reported.\n- Only the measure expression is read. Two measures with the same expression are a duplicate pair whatever their format strings say, and a difference in a dynamic format string does not separate them either.\n- Measures only. Two calculated columns or two calculation items with the same expression are not compared.\n\nRead more: https://pbiplint.com/rules/avoid-duplicate-measures",
  },
  "AVOID_EXCESSIVE_BI-DIRECTIONAL_OR_MANY-TO-MANY_RELATIONSHIPS": {
    text: "Example\n\nOne bi-directional relationship out of two is half the model, well past the threshold.\n\nFires the rule\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: CustomerID\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nrelationship Sales_Customer\n\tcrossFilteringBehavior: bothDirections\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: CustomerID\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n\nWhy it matters\n\nEach bi-directional or many-to-many relationship adds a filter path the engine has to consider on every query. A few in the right places are fine. When they are a third of the model, most queries pay for filter propagation they do not need, and the model starts to show ambiguity: two routes between the same tables, the engine picking one, and totals that stop adding up.\n\nHow to fix it\n\nTake the direction off the relationships that do not need it. In Power BI Desktop, open the model view, double-click a relationship, and set Cross filter direction to Single in the Edit relationship dialog; in the TMDL file the same change is the crossFilteringBehavior: bothDirections line, deleted, since single direction is the default. Where one report genuinely needs the reverse filter, leave the relationship single and ask for the filter inside the measure that needs it, as in Products Sold = CALCULATE(DISTINCTCOUNT('Product'[Product ID]), CROSSFILTER('Sales'[Product ID], 'Product'[Product ID], BOTH)), so the cost falls on one visual instead of every query. For a many-to-many relationship, load a bridge table holding the distinct key values and relate both tables to it, which makes each hop many-to-one: in the dialog that is the Cardinality dropdown, and in the file it is fromCardinality and toCardinality on each relationship. The dialog and the properties read the same on an import model and a DirectQuery one.\n\nWhen to ignore it\n\nA small model is the usual false alarm. Three relationships with one deliberate bi-directional relationship among them is 33 percent and fires, and there is nothing excessive about one. Count the relationships before you read the finding as a verdict: the rule is a ratio, and a ratio over four relationships says almost nothing. A model built on a bridge table by design is the other case, for example one that maps accounts to account groups or budgets to regions, where the many-to-many relationships are the architecture rather than an accident. What is not a legitimate exception is a large model whose bi-directional relationships nobody can account for one by one; that is the finding doing its job.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = AVOID_EXCESSIVE_BI-DIRECTIONAL_OR_MANY-TO-MANY_RELATIONSHIPS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"AVOID_EXCESSIVE_BI-DIRECTIONAL_OR_MANY-TO-MANY_RELATIONSHIPS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- A relationship that is both bi-directional and many-to-many counts twice, once in each tally, so the ratio can exceed 1. A model of nothing but such relationships scores 2.0.\n- The denominator is every relationship in the model, and a model with no relationships at all is never reported.\n- Inactive relationships are counted on both sides of the ratio. A bi-directional relationship that no measure ever activates still pushes the model over the threshold.\n\nRead more: https://pbiplint.com/rules/avoid-excessive-bi-directional-or-many-to-many-relationships",
    markdown:
      "### Example\n\nOne bi-directional relationship out of two is half the model, well past the threshold.\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: CustomerID\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nrelationship Sales_Customer\n\tcrossFilteringBehavior: bothDirections\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: CustomerID\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n```\n\n### Why it matters\n\nEach bi-directional or many-to-many relationship adds a filter path the engine has to consider on every query. A few in the right places are fine. When they are a third of the model, most queries pay for filter propagation they do not need, and the model starts to show ambiguity: two routes between the same tables, the engine picking one, and totals that stop adding up.\n\n### How to fix it\n\nTake the direction off the relationships that do not need it. In Power BI Desktop, open the model view, double-click a relationship, and set Cross filter direction to Single in the Edit relationship dialog; in the TMDL file the same change is the `crossFilteringBehavior: bothDirections` line, deleted, since single direction is the default. Where one report genuinely needs the reverse filter, leave the relationship single and ask for the filter inside the measure that needs it, as in `Products Sold = CALCULATE(DISTINCTCOUNT('Product'[Product ID]), CROSSFILTER('Sales'[Product ID], 'Product'[Product ID], BOTH))`, so the cost falls on one visual instead of every query. For a many-to-many relationship, load a bridge table holding the distinct key values and relate both tables to it, which makes each hop many-to-one: in the dialog that is the Cardinality dropdown, and in the file it is `fromCardinality` and `toCardinality` on each relationship. The dialog and the properties read the same on an import model and a DirectQuery one.\n\n### When to ignore it\n\nA small model is the usual false alarm. Three relationships with one deliberate bi-directional relationship among them is 33 percent and fires, and there is nothing excessive about one. Count the relationships before you read the finding as a verdict: the rule is a ratio, and a ratio over four relationships says almost nothing. A model built on a bridge table by design is the other case, for example one that maps accounts to account groups or budgets to regions, where the many-to-many relationships are the architecture rather than an accident. What is not a legitimate exception is a large model whose bi-directional relationships nobody can account for one by one; that is the finding doing its job.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_EXCESSIVE_BI-DIRECTIONAL_OR_MANY-TO-MANY_RELATIONSHIPS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"AVOID_EXCESSIVE_BI-DIRECTIONAL_OR_MANY-TO-MANY_RELATIONSHIPS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- A relationship that is both bi-directional and many-to-many counts twice, once in each tally, so the ratio can exceed 1. A model of nothing but such relationships scores 2.0.\n- The denominator is every relationship in the model, and a model with no relationships at all is never reported.\n- Inactive relationships are counted on both sides of the ratio. A bi-directional relationship that no measure ever activates still pushes the model over the threshold.\n\nRead more: https://pbiplint.com/rules/avoid-excessive-bi-directional-or-many-to-many-relationships",
  },
  AVOID_FLOATING_POINT_DATA_TYPES: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: double\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\nWhy it matters\n\nDouble is binary floating point, so values like 0.1 have no exact representation and sums drift in the last digits. Two totals that should match can differ by a fraction of a cent, and a money column stored as Double compresses worse than the same values as Fixed Decimal Number, so it costs memory as well. Fixed Decimal Number stores four decimal places exactly, and Whole Number compresses best of all.\n\nHow to fix it\n\nChange the type where the data is loaded. In Power BI Desktop, choose Transform data, select the column, and pick Fixed decimal number or Whole number from Data Type on the Transform tab; on an import table that converts the values before they reach the model, and on a DirectQuery table the step folds into the query the source runs. On an import table, Column tools in the report view has the same Data type dropdown and changes the property on a loaded column without touching the query. In the TMDL file the property is dataType: decimal for Fixed Decimal Number and dataType: int64 for Whole Number. For a calculated column the type follows the expression, so convert it there: Unit Price = CURRENCY(DIVIDE('Sales'[Amount], 'Sales'[Quantity])) returns a fixed decimal whatever the division produced on its own. Best of all, fix the type in the view or the table the query reads, so every model that loads the column starts right.\n\nWhen to ignore it\n\nA value that genuinely needs more than four decimal places has to stay Double, and the rule has no way to know which those are. Latitude and longitude are the everyday case: four decimal places is about eleven metres, which is fine for a country map and wrong for a site plan, so a geography column is usually left alone. Scientific readings, unit conversion factors, and exchange rates quoted to six places are the same. Values above the Fixed Decimal Number range are the other case, since it tops out at about 922 trillion. Money is never the exception: if the column holds an amount someone will add up and reconcile, the rounding errors the rule warns about are exactly the ones that end up in a support ticket.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = AVOID_FLOATING_POINT_DATA_TYPES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"AVOID_FLOATING_POINT_DATA_TYPES\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The type name is compared in lower case, so dataType: Double and dataType: double are both reported.\n- Every kind of column is in scope, including calculated columns and the columns of a calculated table, whose type comes from the expression rather than from a load step.\n- Only the declared type is read. A column whose values happen to be whole numbers is reported all the same while the type says Double.\n\nRead more: https://pbiplint.com/rules/avoid-floating-point-data-types",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: double\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n```\n\n### Why it matters\n\nDouble is binary floating point, so values like 0.1 have no exact representation and sums drift in the last digits. Two totals that should match can differ by a fraction of a cent, and a money column stored as Double compresses worse than the same values as Fixed Decimal Number, so it costs memory as well. Fixed Decimal Number stores four decimal places exactly, and Whole Number compresses best of all.\n\n### How to fix it\n\nChange the type where the data is loaded. In Power BI Desktop, choose Transform data, select the column, and pick Fixed decimal number or Whole number from Data Type on the Transform tab; on an import table that converts the values before they reach the model, and on a DirectQuery table the step folds into the query the source runs. On an import table, Column tools in the report view has the same Data type dropdown and changes the property on a loaded column without touching the query. In the TMDL file the property is `dataType: decimal` for Fixed Decimal Number and `dataType: int64` for Whole Number. For a calculated column the type follows the expression, so convert it there: `Unit Price = CURRENCY(DIVIDE('Sales'[Amount], 'Sales'[Quantity]))` returns a fixed decimal whatever the division produced on its own. Best of all, fix the type in the view or the table the query reads, so every model that loads the column starts right.\n\n### When to ignore it\n\nA value that genuinely needs more than four decimal places has to stay Double, and the rule has no way to know which those are. Latitude and longitude are the everyday case: four decimal places is about eleven metres, which is fine for a country map and wrong for a site plan, so a geography column is usually left alone. Scientific readings, unit conversion factors, and exchange rates quoted to six places are the same. Values above the Fixed Decimal Number range are the other case, since it tops out at about 922 trillion. Money is never the exception: if the column holds an amount someone will add up and reconcile, the rounding errors the rule warns about are exactly the ones that end up in a support ticket.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_FLOATING_POINT_DATA_TYPES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"AVOID_FLOATING_POINT_DATA_TYPES\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The type name is compared in lower case, so `dataType: Double` and `dataType: double` are both reported.\n- Every kind of column is in scope, including calculated columns and the columns of a calculated table, whose type comes from the expression rather than from a load step.\n- Only the declared type is read. A column whose values happen to be whole numbers is reported all the same while the type says Double.\n\nRead more: https://pbiplint.com/rules/avoid-floating-point-data-types",
  },
  AVOID_INVALID_DESCRIPTION_CHARACTERS: {
    text: "Example\n\nThe description in the first snippet has a start of heading character, U+0001, between sales and after where the second has a space.\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\t/// Net sales\u0001after returns and discounts.\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\t/// Net sales after returns and discounts.\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nA control character in a description is invisible in Power BI Desktop and fails the deployment: the service rejects the metadata and the publish stops with an error that names no object. Finding the character by eye is close to impossible.\n\nHow to fix it\n\nIn Power BI Desktop, select the object in the Data pane or in model view and retype Description in the Properties pane, rather than editing around the character you cannot see. In the TMDL file the description is the run of /// lines directly above the declaration, so retype those lines; an editor that shows control characters, or a search by code point, finds where the character is. Descriptions usually arrive pasted from a data dictionary, a ticket, or a spreadsheet cell, so if the same text is about to be pasted onto twenty more objects, clean it at the source first.\n\nWhen to ignore it\n\nThere is no case for it. A control character in a description tells a reader nothing, and it stops the model from deploying at all.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = AVOID_INVALID_DESCRIPTION_CHARACTERS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"AVOID_INVALID_DESCRIPTION_CHARACTERS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- A /// line carries whatever that line holds. pbiplint takes each /// line above a declaration as one line of the object's description, so a control character on one of those lines reaches the model and the rule reports it. Only the line feed and the carriage return cannot arrive inside one of those lines; a description built from several /// lines carries a line feed between them, which the rule does not test for either.\n- The test follows .NET's definition of a control character that is not whitespace, so a tab, a vertical tab, a form feed, or a next line character in a description is not reported. No rule reads a description for those: SPECIAL_CHARS_IN_OBJECT_NAMES reads names only.\n- The /// lines have to sit directly above the declaration they describe. A run of them followed by a blank line describes nothing, and pbiplint reports that as a PARSE_ISSUE instead of carrying the text into the model, so a character in a stranded comment never reaches this rule.\n- The scope covers hierarchy levels and roles, and leaves out the model itself, named expressions, and data sources, so a control character in one of those descriptions is not reported.\n\nRead more: https://pbiplint.com/rules/avoid-invalid-description-characters",
    markdown:
      "### Example\n\nThe description in the first snippet has a start of heading character, U+0001, between `sales` and `after` where the second has a space.\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\t/// Net sales\u0001after returns and discounts.\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\t/// Net sales after returns and discounts.\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nA control character in a description is invisible in Power BI Desktop and fails the deployment: the service rejects the metadata and the publish stops with an error that names no object. Finding the character by eye is close to impossible.\n\n### How to fix it\n\nIn Power BI Desktop, select the object in the Data pane or in model view and retype Description in the Properties pane, rather than editing around the character you cannot see. In the TMDL file the description is the run of `///` lines directly above the declaration, so retype those lines; an editor that shows control characters, or a search by code point, finds where the character is. Descriptions usually arrive pasted from a data dictionary, a ticket, or a spreadsheet cell, so if the same text is about to be pasted onto twenty more objects, clean it at the source first.\n\n### When to ignore it\n\nThere is no case for it. A control character in a description tells a reader nothing, and it stops the model from deploying at all.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_INVALID_DESCRIPTION_CHARACTERS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"AVOID_INVALID_DESCRIPTION_CHARACTERS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- A `///` line carries whatever that line holds. pbiplint takes each `///` line above a declaration as one line of the object's description, so a control character on one of those lines reaches the model and the rule reports it. Only the line feed and the carriage return cannot arrive inside one of those lines; a description built from several `///` lines carries a line feed between them, which the rule does not test for either.\n- The test follows .NET's definition of a control character that is not whitespace, so a tab, a vertical tab, a form feed, or a next line character in a description is not reported. No rule reads a description for those: `SPECIAL_CHARS_IN_OBJECT_NAMES` reads names only.\n- The `///` lines have to sit directly above the declaration they describe. A run of them followed by a blank line describes nothing, and pbiplint reports that as a `PARSE_ISSUE` instead of carrying the text into the model, so a character in a stranded comment never reaches this rule.\n- The scope covers hierarchy levels and roles, and leaves out the model itself, named expressions, and data sources, so a control character in one of those descriptions is not reported.\n\nRead more: https://pbiplint.com/rules/avoid-invalid-description-characters",
  },
  AVOID_INVALID_NAME_CHARACTERS: {
    text: "Example\n\nThe column in the first snippet has a start of heading character, U+0001, between Order and ID where the second has a space, which is why the two look almost the same.\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order\u0001ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\nWhy it matters\n\nA control character in a name is invisible in Power BI Desktop and fails the deployment: the service rejects the metadata and the publish stops with an error that names no object. Every DAX reference and report binding also has to reproduce the hidden character exactly, so the object is fragile even before it is deployed.\n\nHow to fix it\n\nIn Power BI Desktop, double-click the field in the Data pane and retype the whole name rather than trying to select the character, or select the object and retype Name in the Properties pane. In the TMDL file the name is on the declaration line between single quotes, so column 'Order ID' is what the line should read once the character is gone; an editor that shows control characters, or a search by code point, finds where it was. Renaming in Desktop updates the visuals bound to the field; a hand edit in the TMDL file does not, so open the report and check its visuals after one. Where the character arrives with a source column name, rename the column in Power Query as well, so the next column you add from that query comes in clean.\n\nWhen to ignore it\n\nThere is no case for it. The character shows a reader nothing, nobody can type it to reach the object, and it stops the model from deploying at all.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = AVOID_INVALID_NAME_CHARACTERS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"AVOID_INVALID_NAME_CHARACTERS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Every character this rule tests for reaches a name through a TMDL file. pbiplint splits a file into lines before it reads any declaration, so a line feed or a carriage return could never land inside a name, and the rule leaves those two out of its test; any other control character inside a quoted name survives the parse and is reported.\n- The test follows .NET's definition of a control character that is not whitespace, so it passes over the tab, the line feed, the vertical tab, the form feed, the carriage return, and the next line character. SPECIAL_CHARS_IN_OBJECT_NAMES picks up the tab, the line feed, and the carriage return. A vertical tab, a form feed, or a next line character inside a name is reported by neither rule.\n- The scope covers hierarchy levels and roles, which SPECIAL_CHARS_IN_OBJECT_NAMES leaves out, and leaves out the model itself, named expressions, and data sources, so a control character in one of those names is not reported here.\n\nRead more: https://pbiplint.com/rules/avoid-invalid-name-characters",
    markdown:
      "### Example\n\nThe column in the first snippet has a start of heading character, U+0001, between `Order` and `ID` where the second has a space, which is why the two look almost the same.\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order\u0001ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n```\n\n### Why it matters\n\nA control character in a name is invisible in Power BI Desktop and fails the deployment: the service rejects the metadata and the publish stops with an error that names no object. Every DAX reference and report binding also has to reproduce the hidden character exactly, so the object is fragile even before it is deployed.\n\n### How to fix it\n\nIn Power BI Desktop, double-click the field in the Data pane and retype the whole name rather than trying to select the character, or select the object and retype Name in the Properties pane. In the TMDL file the name is on the declaration line between single quotes, so `column 'Order ID'` is what the line should read once the character is gone; an editor that shows control characters, or a search by code point, finds where it was. Renaming in Desktop updates the visuals bound to the field; a hand edit in the TMDL file does not, so open the report and check its visuals after one. Where the character arrives with a source column name, rename the column in Power Query as well, so the next column you add from that query comes in clean.\n\n### When to ignore it\n\nThere is no case for it. The character shows a reader nothing, nobody can type it to reach the object, and it stops the model from deploying at all.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_INVALID_NAME_CHARACTERS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"AVOID_INVALID_NAME_CHARACTERS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Every character this rule tests for reaches a name through a TMDL file. pbiplint splits a file into lines before it reads any declaration, so a line feed or a carriage return could never land inside a name, and the rule leaves those two out of its test; any other control character inside a quoted name survives the parse and is reported.\n- The test follows .NET's definition of a control character that is not whitespace, so it passes over the tab, the line feed, the vertical tab, the form feed, the carriage return, and the next line character. `SPECIAL_CHARS_IN_OBJECT_NAMES` picks up the tab, the line feed, and the carriage return. A vertical tab, a form feed, or a next line character inside a name is reported by neither rule.\n- The scope covers hierarchy levels and roles, which `SPECIAL_CHARS_IN_OBJECT_NAMES` leaves out, and leaves out the model itself, named expressions, and data sources, so a control character in one of those names is not reported here.\n\nRead more: https://pbiplint.com/rules/avoid-invalid-name-characters",
  },
  AVOID_STRUCTURED_DATA_SOURCES_WITH_PROVIDER_PARTITIONS: {
    text: 'Example\n\nFires the rule\n\ndataSource SQL/localhost;Sales\n\tconnectionDetails =\n\t\t\t\t{\n\t\t\t\t  "protocol": "tds",\n\t\t\t\t  "address": {\n\t\t\t\t    "server": "localhost",\n\t\t\t\t    "database": "Sales"\n\t\t\t\t  }\n\t\t\t\t}\n\t\tauthenticationKind: ServiceAccount\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tpartition Sales = query\n\t\tmode: import\n\t\tsource\n\t\t\tquery = SELECT Amount FROM dbo.Sales\n\t\t\tdataSource: SQL/localhost;Sales\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource =\n\t\t\t\tlet\n\t\t\t\t\tSource = Sql.Database("localhost", "Sales"),\n\t\t\t\t\tSales = Source{[Schema="dbo",Item="Sales"]}[Data]\n\t\t\t\tin\n\t\t\t\t\tSales\n\nThe data source goes with the partition: a Power Query partition carries its connection in the M expression, so once the last provider partition is rewritten there is nothing left for the dataSource declaration to serve.\n\nWhy it matters\n\nPower BI supports two combinations: a Power Query partition against any data source, or a legacy provider partition against a legacy provider data source. A provider partition against a structured data source is a mix the service refuses, so the model fails to deploy or refresh. Power BI Desktop never produces the combination; it appears in models migrated from Analysis Services or assembled by hand.\n\nHow to fix it\n\nRewrite the partition as Power Query, which is what Power BI Desktop writes. In Desktop, choose Transform data, build the query against the source, and load it; Desktop writes an m partition every time and has no way to write a provider one. In the TMDL file, change partition Sales = query to partition Sales = m, replace the source block and its query and dataSource lines with a source = block holding the M expression, and delete the dataSource declaration from the file that holds it once no partition names it.\n\nThe other route keeps the provider partition and changes the data source instead, so both halves are legacy: replace the structured declaration with one that reads dataSource \'Sales SQL\' = provider and carries a connectionString. The walkthrough in the links does that conversion with Tabular Editor.\n\nWhen to ignore it\n\nThere is no case for keeping the pairing. Power BI rejects it, so the finding is the deployment failure arriving before the deployment. What is worth deciding first is which half to change: if the rest of the model\'s partitions are Power Query, the provider partition is the leftover and rewriting it is the smaller change; if the model came over from Analysis Services and every partition is a provider one, converting the single data source touches one object instead of many.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = AVOID_STRUCTURED_DATA_SOURCES_WITH_PROVIDER_PARTITIONS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set "AVOID_STRUCTURED_DATA_SOURCES_WITH_PROVIDER_PARTITIONS": "off" under rules in pbiplint.config.json.\n\nQuirks\n\n- The partition has to name the data source on its dataSource line for the rule to see the pairing. A provider partition that names no data source, or names one the model does not declare, is not reported.\n- A data source counts as structured unless its declaration says provider, so dataSource \'Sales SQL\' with nothing after the name is read as structured, the same as one with a connectionDetails block.\n- The finding is on the partition, not on the data source, so one structured data source shared by five provider partitions gives five findings and one edit clears them all.\n\nRead more: https://pbiplint.com/rules/avoid-structured-data-sources-with-provider-partitions',
    markdown:
      '### Example\n\n**Fires the rule**\n\n```tmdl\ndataSource SQL/localhost;Sales\n\tconnectionDetails =\n\t\t\t\t{\n\t\t\t\t  "protocol": "tds",\n\t\t\t\t  "address": {\n\t\t\t\t    "server": "localhost",\n\t\t\t\t    "database": "Sales"\n\t\t\t\t  }\n\t\t\t\t}\n\t\tauthenticationKind: ServiceAccount\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tpartition Sales = query\n\t\tmode: import\n\t\tsource\n\t\t\tquery = SELECT Amount FROM dbo.Sales\n\t\t\tdataSource: SQL/localhost;Sales\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource =\n\t\t\t\tlet\n\t\t\t\t\tSource = Sql.Database("localhost", "Sales"),\n\t\t\t\t\tSales = Source{[Schema="dbo",Item="Sales"]}[Data]\n\t\t\t\tin\n\t\t\t\t\tSales\n```\n\nThe data source goes with the partition: a Power Query partition carries its connection in the M expression, so once the last provider partition is rewritten there is nothing left for the `dataSource` declaration to serve.\n\n### Why it matters\n\nPower BI supports two combinations: a Power Query partition against any data source, or a legacy provider partition against a legacy provider data source. A provider partition against a structured data source is a mix the service refuses, so the model fails to deploy or refresh. Power BI Desktop never produces the combination; it appears in models migrated from Analysis Services or assembled by hand.\n\n### How to fix it\n\nRewrite the partition as Power Query, which is what Power BI Desktop writes. In Desktop, choose Transform data, build the query against the source, and load it; Desktop writes an `m` partition every time and has no way to write a provider one. In the TMDL file, change `partition Sales = query` to `partition Sales = m`, replace the `source` block and its `query` and `dataSource` lines with a `source =` block holding the M expression, and delete the `dataSource` declaration from the file that holds it once no partition names it.\n\nThe other route keeps the provider partition and changes the data source instead, so both halves are legacy: replace the structured declaration with one that reads `dataSource \'Sales SQL\' = provider` and carries a `connectionString`. The walkthrough in the links does that conversion with Tabular Editor.\n\n### When to ignore it\n\nThere is no case for keeping the pairing. Power BI rejects it, so the finding is the deployment failure arriving before the deployment. What is worth deciding first is which half to change: if the rest of the model\'s partitions are Power Query, the provider partition is the leftover and rewriting it is the smaller change; if the model came over from Analysis Services and every partition is a provider one, converting the single data source touches one object instead of many.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_STRUCTURED_DATA_SOURCES_WITH_PROVIDER_PARTITIONS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_STRUCTURED_DATA_SOURCES_WITH_PROVIDER_PARTITIONS": "off"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The partition has to name the data source on its `dataSource` line for the rule to see the pairing. A provider partition that names no data source, or names one the model does not declare, is not reported.\n- A data source counts as structured unless its declaration says `provider`, so `dataSource \'Sales SQL\'` with nothing after the name is read as structured, the same as one with a `connectionDetails` block.\n- The finding is on the partition, not on the data source, so one structured data source shared by five provider partitions gives five findings and one edit clears them all.\n\nRead more: https://pbiplint.com/rules/avoid-structured-data-sources-with-provider-partitions',
  },
  AVOID_THE_USERELATIONSHIP_FUNCTION_AND_RLS_AGAINST_THE_SAME_TABLE: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: CustomerID\n\n\tcolumn 'Ship To Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: ShipToCustomerID\n\n\tmeasure 'Shipped Amount' = CALCULATE(SUM(Sales[Amount]), USERELATIONSHIP(Sales[Ship To Customer ID], Customer[Customer ID]))\n\t\tformatString: #,0\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n\nrelationship Sales_ShipToCustomer\n\tisActive: false\n\tfromColumn: Sales.'Ship To Customer ID'\n\ttoColumn: Customer.'Customer ID'\n\nrole 'West Region'\n\tmodelPermission: read\n\n\ttablePermission Customer = 'Customer'[Region] = \"West\"\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: CustomerID\n\n\tcolumn 'Ship To Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: ShipToCustomerID\n\n\tmeasure 'Shipped Amount' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\ntable 'Ship To Customer'\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n\nrelationship Sales_ShipToCustomer\n\tfromColumn: Sales.'Ship To Customer ID'\n\ttoColumn: 'Ship To Customer'.'Customer ID'\n\nrole 'West Region'\n\tmodelPermission: read\n\n\ttablePermission Customer = 'Customer'[Region] = \"West\"\n\n\ttablePermission 'Ship To Customer' = 'Ship To Customer'[Region] = \"West\"\n\nThe second snippet gives the ship-to relationship a table of its own, so the relationship is active, the measure is the plain aggregation again, and the copy carries the same filter the original does.\n\nWhy it matters\n\nWhen a role filters a table, the engine has to apply that filter through the active relationship, and USERELATIONSHIP asks it to swap in an inactive one. The two instructions conflict, so the measure fails for every user in the role while it works for the model owner, who tests without roles. That is a bug you find after publishing.\n\nHow to fix it\n\nGive the second relationship a table of its own, so no measure needs USERELATIONSHIP. In Power BI Desktop, choose Transform data, right-click the dimension's query, choose Reference, name the copy for the part it plays, Ship To Customer beside Customer, and load it. In model view, drag the fact table's second key onto the copy's key, which creates an active relationship, and delete the inactive one. Edit the measure in the formula bar so it is the plain aggregation again, and give the copy the same filter the original has, under Modeling, Manage roles. In the TMDL file that is a new table block with its own ref table line in model.tmdl, a relationship block with no isActive: false line, the expression after measure 'Shipped Amount' =, and a second tablePermission under the role.\n\nThe other route leaves the relationships alone and moves the row-level security instead: put the filter on a table that no measure re-points, and the pairing is gone. Work out what that changes for the reader before you do it, because filtering a dimension and filtering the fact table are not the same restriction.\n\nWhen to ignore it\n\nA role nobody is assigned to still counts. The rule pairs any role's filter with any measure, so on a Power BI semantic model, where membership lives in the service and never in the files, an abandoned role produces the finding although no reader ever meets the error. Check the workspace's security settings for the role before you restructure anything. Where the role is real and the measure is one a reader will use, the finding is the error they will see, and there is nothing here to ignore.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = AVOID_THE_USERELATIONSHIP_FUNCTION_AND_RLS_AGAINST_THE_SAME_TABLE under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"AVOID_THE_USERELATIONSHIP_FUNCTION_AND_RLS_AGAINST_THE_SAME_TABLE\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Only the second argument of USERELATIONSHIP is compared, and only measures are scanned. A calculation item that calls USERELATIONSHIP is not checked, and a measure that names the secured table as the first argument passes.\n- The comparison is made on the text of the expression, so a USERELATIONSHIP inside a comment or a quoted string counts the same as one the engine will run.\n- Only the presence of a filter on the table is tested, never what the filter says. A role whose filter is TRUE() puts the table in scope exactly as a real restriction does.\n- pbiplint escapes the table name before it builds the pattern, so a table called Date (Order) is matched literally. The source rule builds its pattern from the raw name, where the parentheses would be read as a group.\n\nRead more: https://pbiplint.com/rules/avoid-the-userelationship-function-and-rls-against-the-same-table",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: CustomerID\n\n\tcolumn 'Ship To Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: ShipToCustomerID\n\n\tmeasure 'Shipped Amount' = CALCULATE(SUM(Sales[Amount]), USERELATIONSHIP(Sales[Ship To Customer ID], Customer[Customer ID]))\n\t\tformatString: #,0\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n\nrelationship Sales_ShipToCustomer\n\tisActive: false\n\tfromColumn: Sales.'Ship To Customer ID'\n\ttoColumn: Customer.'Customer ID'\n\nrole 'West Region'\n\tmodelPermission: read\n\n\ttablePermission Customer = 'Customer'[Region] = \"West\"\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: CustomerID\n\n\tcolumn 'Ship To Customer ID'\n\t\tdataType: int64\n\t\tsourceColumn: ShipToCustomerID\n\n\tmeasure 'Shipped Amount' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\ntable 'Ship To Customer'\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n\nrelationship Sales_ShipToCustomer\n\tfromColumn: Sales.'Ship To Customer ID'\n\ttoColumn: 'Ship To Customer'.'Customer ID'\n\nrole 'West Region'\n\tmodelPermission: read\n\n\ttablePermission Customer = 'Customer'[Region] = \"West\"\n\n\ttablePermission 'Ship To Customer' = 'Ship To Customer'[Region] = \"West\"\n```\n\nThe second snippet gives the ship-to relationship a table of its own, so the relationship is active, the measure is the plain aggregation again, and the copy carries the same filter the original does.\n\n### Why it matters\n\nWhen a role filters a table, the engine has to apply that filter through the active relationship, and USERELATIONSHIP asks it to swap in an inactive one. The two instructions conflict, so the measure fails for every user in the role while it works for the model owner, who tests without roles. That is a bug you find after publishing.\n\n### How to fix it\n\nGive the second relationship a table of its own, so no measure needs USERELATIONSHIP. In Power BI Desktop, choose Transform data, right-click the dimension's query, choose Reference, name the copy for the part it plays, Ship To Customer beside Customer, and load it. In model view, drag the fact table's second key onto the copy's key, which creates an active relationship, and delete the inactive one. Edit the measure in the formula bar so it is the plain aggregation again, and give the copy the same filter the original has, under Modeling, Manage roles. In the TMDL file that is a new `table` block with its own `ref table` line in `model.tmdl`, a `relationship` block with no `isActive: false` line, the expression after `measure 'Shipped Amount' =`, and a second `tablePermission` under the role.\n\nThe other route leaves the relationships alone and moves the row-level security instead: put the filter on a table that no measure re-points, and the pairing is gone. Work out what that changes for the reader before you do it, because filtering a dimension and filtering the fact table are not the same restriction.\n\n### When to ignore it\n\nA role nobody is assigned to still counts. The rule pairs any role's filter with any measure, so on a Power BI semantic model, where membership lives in the service and never in the files, an abandoned role produces the finding although no reader ever meets the error. Check the workspace's security settings for the role before you restructure anything. Where the role is real and the measure is one a reader will use, the finding is the error they will see, and there is nothing here to ignore.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_THE_USERELATIONSHIP_FUNCTION_AND_RLS_AGAINST_THE_SAME_TABLE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"AVOID_THE_USERELATIONSHIP_FUNCTION_AND_RLS_AGAINST_THE_SAME_TABLE\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Only the second argument of USERELATIONSHIP is compared, and only measures are scanned. A calculation item that calls USERELATIONSHIP is not checked, and a measure that names the secured table as the first argument passes.\n- The comparison is made on the text of the expression, so a USERELATIONSHIP inside a comment or a quoted string counts the same as one the engine will run.\n- Only the presence of a filter on the table is tested, never what the filter says. A role whose filter is `TRUE()` puts the table in scope exactly as a real restriction does.\n- pbiplint escapes the table name before it builds the pattern, so a table called `Date (Order)` is matched literally. The source rule builds its pattern from the raw name, where the parentheses would be read as a group.\n\nRead more: https://pbiplint.com/rules/avoid-the-userelationship-function-and-rls-against-the-same-table",
  },
  "AVOID_USING_'1-(X/Y)'_SYNTAX": {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tsourceColumn: Cost\n\tmeasure 'Margin %' = 1 - SUM(Sales[Cost]) / SUM(Sales[Amount])\n\t\tformatString: 0.0%\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tsourceColumn: Cost\n\tmeasure 'Margin %' = DIVIDE(SUM(Sales[Amount]) - SUM(Sales[Cost]), SUM(Sales[Amount]))\n\t\tformatString: 0.0%\n\nWhy it matters\n\nWritten that way the measure always returns a value. When there are no rows, the division is blank, one minus blank is one, and every empty cell in the matrix shows 100 percent. The visual fills with rows that should not be there, and the query does extra work to produce them. Written as a single DIVIDE over the difference, the measure is blank when the data is blank and the engine skips those rows.\n\nHow to fix it\n\nRewrite 1 - x / y as DIVIDE(y - x, y), and hold the shared denominator in a variable when it is used twice:\n\nMargin % =\nVAR TotalAmount = SUM ( Sales[Amount] )\nRETURN DIVIDE ( TotalAmount - SUM ( Sales[Cost] ), TotalAmount )\n\nIn Power BI Desktop, select the measure and edit it in the formula bar. In the TMDL file, edit the expression after measure 'Margin %' =.\n\nWhen to ignore it\n\nThere is no case where the original shape is the better one. If a visual relies on the measure showing 100 percent where there is no data, that is a display decision, and it belongs in a measure that returns the value on purpose, not in a subtraction that happens to produce it.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = AVOID_USING_'1-(X/Y)'_SYNTAX under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"AVOID_USING_'1-(X/Y)'_SYNTAX\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The pattern needs SUM as the numerator, or DIVIDE right after the number. 1 - [Cost] / [Sales] and 1 - AVERAGE(...) / ... are not matched.\n- Table and column names must contain only letters, digits, spaces, and underscores for the SUM form to match.\n\nRead more: https://pbiplint.com/rules/avoid-using-1-x-y-syntax",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tsourceColumn: Cost\n\tmeasure 'Margin %' = 1 - SUM(Sales[Cost]) / SUM(Sales[Amount])\n\t\tformatString: 0.0%\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tsourceColumn: Cost\n\tmeasure 'Margin %' = DIVIDE(SUM(Sales[Amount]) - SUM(Sales[Cost]), SUM(Sales[Amount]))\n\t\tformatString: 0.0%\n```\n\n### Why it matters\n\nWritten that way the measure always returns a value. When there are no rows, the division is blank, one minus blank is one, and every empty cell in the matrix shows 100 percent. The visual fills with rows that should not be there, and the query does extra work to produce them. Written as a single DIVIDE over the difference, the measure is blank when the data is blank and the engine skips those rows.\n\n### How to fix it\n\nRewrite `1 - x / y` as `DIVIDE(y - x, y)`, and hold the shared denominator in a variable when it is used twice:\n\n```\nMargin % =\nVAR TotalAmount = SUM ( Sales[Amount] )\nRETURN DIVIDE ( TotalAmount - SUM ( Sales[Cost] ), TotalAmount )\n```\n\nIn Power BI Desktop, select the measure and edit it in the formula bar. In the TMDL file, edit the expression after `measure 'Margin %' =`.\n\n### When to ignore it\n\nThere is no case where the original shape is the better one. If a visual relies on the measure showing 100 percent where there is no data, that is a display decision, and it belongs in a measure that returns the value on purpose, not in a subtraction that happens to produce it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_USING_'1-(X/Y)'_SYNTAX` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"AVOID_USING_'1-(X/Y)'_SYNTAX\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The pattern needs SUM as the numerator, or DIVIDE right after the number. `1 - [Cost] / [Sales]` and `1 - AVERAGE(...) / ...` are not matched.\n- Table and column names must contain only letters, digits, spaces, and underscores for the SUM form to match.\n\nRead more: https://pbiplint.com/rules/avoid-using-1-x-y-syntax",
  },
  "AVOID_USING_MANY-TO-MANY_RELATIONSHIPS_ON_TABLES_USED_FOR_DYNAMIC_ROW_LEVEL_SECURITY": {
    text: "Example\n\nFires the rule\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\ntable 'User Region'\n\tcolumn 'User Email'\n\t\tdataType: string\n\t\tsourceColumn: UserEmail\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship UserRegion_Customer\n\tfromCardinality: many\n\ttoCardinality: many\n\tcrossFilteringBehavior: bothDirections\n\tfromColumn: 'User Region'.Region\n\ttoColumn: Customer.Region\n\nrole 'Regional Users'\n\tmodelPermission: read\n\n\ttablePermission 'User Region' = 'User Region'[User Email] = USERPRINCIPALNAME()\n\nAfter the fix\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\ntable Region\n\tcolumn Region\n\t\tdataType: string\n\t\tisKey\n\t\tsourceColumn: Region\n\ntable 'User Region'\n\tcolumn 'User Email'\n\t\tdataType: string\n\t\tsourceColumn: UserEmail\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship UserRegion_Region\n\tcrossFilteringBehavior: bothDirections\n\tfromColumn: 'User Region'.Region\n\ttoColumn: Region.Region\n\nrelationship Customer_Region\n\tfromColumn: Customer.Region\n\ttoColumn: Region.Region\n\nrole 'Regional Users'\n\tmodelPermission: read\n\n\ttablePermission 'User Region' = 'User Region'[User Email] = USERPRINCIPALNAME()\n\nWhy it matters\n\nA security filter is pushed through every relationship leading away from the secured table, on every query, for every user in the role. Through a many-to-many relationship that push is an expansion over the distinct values on both sides rather than a lookup, and it runs before the query proper. The slowdown grows with every such hop, and the model owner never sees it, because Desktop tests without roles.\n\nHow to fix it\n\nGive the two tables a dimension to meet on, so every hop is many-to-one. Load a small table of the distinct key values, one row per region in the example above, and in Power BI Desktop's model view drag both the security table's key and the fact or dimension key onto it; each new relationship is many-to-one because the new table's key is unique. In the TMDL file that is fromCardinality: many with toCardinality: one, which is what a relationship block with neither line already means, and marking the new table's key column with isKey. The security filter itself does not move: it stays where Modeling, Manage roles wrote it, as a tablePermission line under the role. Leave one bi-directional hop, from the security table up to the shared dimension, so the filter still reaches the facts, and make it that one hop rather than a many-to-many expansion. The patterns under Links set out the variants in full.\n\nWhen to ignore it\n\nThe filter is the thing to look at first. This rule counts any row-level security filter, so a table filtered by a static expression such as [Region] = \"East\" is reported exactly like one filtered by a lookup on the signed-in user. A static filter resolves to the same rows for everyone in the role, so the expansion is cached and shared instead of repeated per user. The direction of the relationship is the second check: the finding only asks whether a many-to-many relationship touches the table, not whether the security filter travels through it, so a many-to-many relationship pointing away from the secured path costs nothing here. Size is the third: a security table of a few hundred rows expands cheaply, and the trade the rule assumes is one worth measuring in the service with the role applied before you rebuild anything. A large secured table reached through more than one many-to-many hop is the case the rule was written for, and there ignoring it is not defensible.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = AVOID_USING_MANY-TO-MANY_RELATIONSHIPS_ON_TABLES_USED_FOR_DYNAMIC_ROW_LEVEL_SECURITY under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"AVOID_USING_MANY-TO-MANY_RELATIONSHIPS_ON_TABLES_USED_FOR_DYNAMIC_ROW_LEVEL_SECURITY\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Any row-level security filter counts, not only dynamic filters that call USERNAME or USERPRINCIPALNAME.\n- Calculated tables are out of scope, and so are calculation groups. Only a plain table is reported, even where a calculated table carries the filter.\n- The relationship only has to touch the table. Direction is not tested, so a many-to-many relationship the security filter never travels through is reported the same as one it does.\n- A table permission with no filter expression does not count. An entry that only sets metadataPermission or a column permission, which is object-level security rather than row-level, leaves the table out of this rule.\n\nRead more: https://pbiplint.com/rules/avoid-using-many-to-many-relationships-on-tables-used-for-dynamic-row-level-security",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\ntable 'User Region'\n\tcolumn 'User Email'\n\t\tdataType: string\n\t\tsourceColumn: UserEmail\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship UserRegion_Customer\n\tfromCardinality: many\n\ttoCardinality: many\n\tcrossFilteringBehavior: bothDirections\n\tfromColumn: 'User Region'.Region\n\ttoColumn: Customer.Region\n\nrole 'Regional Users'\n\tmodelPermission: read\n\n\ttablePermission 'User Region' = 'User Region'[User Email] = USERPRINCIPALNAME()\n```\n\n**After the fix**\n\n```tmdl\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\ntable Region\n\tcolumn Region\n\t\tdataType: string\n\t\tisKey\n\t\tsourceColumn: Region\n\ntable 'User Region'\n\tcolumn 'User Email'\n\t\tdataType: string\n\t\tsourceColumn: UserEmail\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship UserRegion_Region\n\tcrossFilteringBehavior: bothDirections\n\tfromColumn: 'User Region'.Region\n\ttoColumn: Region.Region\n\nrelationship Customer_Region\n\tfromColumn: Customer.Region\n\ttoColumn: Region.Region\n\nrole 'Regional Users'\n\tmodelPermission: read\n\n\ttablePermission 'User Region' = 'User Region'[User Email] = USERPRINCIPALNAME()\n```\n\n### Why it matters\n\nA security filter is pushed through every relationship leading away from the secured table, on every query, for every user in the role. Through a many-to-many relationship that push is an expansion over the distinct values on both sides rather than a lookup, and it runs before the query proper. The slowdown grows with every such hop, and the model owner never sees it, because Desktop tests without roles.\n\n### How to fix it\n\nGive the two tables a dimension to meet on, so every hop is many-to-one. Load a small table of the distinct key values, one row per region in the example above, and in Power BI Desktop's model view drag both the security table's key and the fact or dimension key onto it; each new relationship is many-to-one because the new table's key is unique. In the TMDL file that is `fromCardinality: many` with `toCardinality: one`, which is what a relationship block with neither line already means, and marking the new table's key column with `isKey`. The security filter itself does not move: it stays where Modeling, Manage roles wrote it, as a `tablePermission` line under the role. Leave one bi-directional hop, from the security table up to the shared dimension, so the filter still reaches the facts, and make it that one hop rather than a many-to-many expansion. The patterns under Links set out the variants in full.\n\n### When to ignore it\n\nThe filter is the thing to look at first. This rule counts any row-level security filter, so a table filtered by a static expression such as `[Region] = \"East\"` is reported exactly like one filtered by a lookup on the signed-in user. A static filter resolves to the same rows for everyone in the role, so the expansion is cached and shared instead of repeated per user. The direction of the relationship is the second check: the finding only asks whether a many-to-many relationship touches the table, not whether the security filter travels through it, so a many-to-many relationship pointing away from the secured path costs nothing here. Size is the third: a security table of a few hundred rows expands cheaply, and the trade the rule assumes is one worth measuring in the service with the role applied before you rebuild anything. A large secured table reached through more than one many-to-many hop is the case the rule was written for, and there ignoring it is not defensible.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_USING_MANY-TO-MANY_RELATIONSHIPS_ON_TABLES_USED_FOR_DYNAMIC_ROW_LEVEL_SECURITY` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"AVOID_USING_MANY-TO-MANY_RELATIONSHIPS_ON_TABLES_USED_FOR_DYNAMIC_ROW_LEVEL_SECURITY\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Any row-level security filter counts, not only dynamic filters that call USERNAME or USERPRINCIPALNAME.\n- Calculated tables are out of scope, and so are calculation groups. Only a plain table is reported, even where a calculated table carries the filter.\n- The relationship only has to touch the table. Direction is not tested, so a many-to-many relationship the security filter never travels through is reported the same as one it does.\n- A table permission with no filter expression does not count. An entry that only sets `metadataPermission` or a column permission, which is object-level security rather than row-level, leaves the table out of this rule.\n\nRead more: https://pbiplint.com/rules/avoid-using-many-to-many-relationships-on-tables-used-for-dynamic-row-level-security",
  },
  AVOID_USING_THE_IFERROR_FUNCTION: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = IFERROR(SUM(Sales[Amount]) / SUM(Sales[Quantity]), 0)\n\t\tformatString: #,0.00\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = DIVIDE(SUM(Sales[Amount]), SUM(Sales[Quantity]), 0)\n\t\tformatString: #,0.00\n\nWhy it matters\n\nIFERROR makes the engine evaluate the expression row by row so it can catch a failure, which switches off the bulk evaluation that makes DAX fast. Most uses guard a division, and DIVIDE handles that case without the penalty. The rest usually hide a data problem, such as text in a numeric column, that is better fixed in Power Query where the failure cannot happen.\n\nHow to fix it\n\nWhere IFERROR guards a division, DIVIDE does the same job with the same fallback, and its third argument is what IFERROR was returning:\n\nAverage Price = DIVIDE ( SUM ( Sales[Amount] ), SUM ( Sales[Quantity] ), 0 )\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column is edited the same way with the column selected. In the TMDL file, edit the expression after measure 'Average Price' =, or after column Name = for a calculated column. Where the call is guarding a type conversion rather than a division, change the column's type in Power Query so the conversion cannot fail, and drop the guard. Where a guard is genuinely needed, test the condition with IF, which leaves the engine free to evaluate in bulk.\n\nWhen to ignore it\n\nA calculated column on an imported table is materialized once per refresh and never again at query time, so the cost of the guard is paid by the refresh, not by every visual. IFERROR in a calculated column over a small table is a fair trade while the underlying data problem is being sorted out upstream. A measure is the opposite case: it runs on every query, so the guard is worth removing even when the model is small today.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = AVOID_USING_THE_IFERROR_FUNCTION under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"AVOID_USING_THE_IFERROR_FUNCTION\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The test is for the text IFERROR(, in any letter case and with any spacing before the parenthesis, anywhere in the expression. A mention inside a string literal or a comment counts.\n- Calculation items are out of scope, so an IFERROR inside a calculation item is not reported even though it costs the same.\n- Only the object's own expression is read. A call inside a measure's dynamic format string is not reported.\n\nRead more: https://pbiplint.com/rules/avoid-using-the-iferror-function",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = IFERROR(SUM(Sales[Amount]) / SUM(Sales[Quantity]), 0)\n\t\tformatString: #,0.00\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = DIVIDE(SUM(Sales[Amount]), SUM(Sales[Quantity]), 0)\n\t\tformatString: #,0.00\n```\n\n### Why it matters\n\nIFERROR makes the engine evaluate the expression row by row so it can catch a failure, which switches off the bulk evaluation that makes DAX fast. Most uses guard a division, and DIVIDE handles that case without the penalty. The rest usually hide a data problem, such as text in a numeric column, that is better fixed in Power Query where the failure cannot happen.\n\n### How to fix it\n\nWhere IFERROR guards a division, DIVIDE does the same job with the same fallback, and its third argument is what IFERROR was returning:\n\n```\nAverage Price = DIVIDE ( SUM ( Sales[Amount] ), SUM ( Sales[Quantity] ), 0 )\n```\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column is edited the same way with the column selected. In the TMDL file, edit the expression after `measure 'Average Price' =`, or after `column Name =` for a calculated column. Where the call is guarding a type conversion rather than a division, change the column's type in Power Query so the conversion cannot fail, and drop the guard. Where a guard is genuinely needed, test the condition with IF, which leaves the engine free to evaluate in bulk.\n\n### When to ignore it\n\nA calculated column on an imported table is materialized once per refresh and never again at query time, so the cost of the guard is paid by the refresh, not by every visual. IFERROR in a calculated column over a small table is a fair trade while the underlying data problem is being sorted out upstream. A measure is the opposite case: it runs on every query, so the guard is worth removing even when the model is small today.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_USING_THE_IFERROR_FUNCTION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"AVOID_USING_THE_IFERROR_FUNCTION\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The test is for the text `IFERROR(`, in any letter case and with any spacing before the parenthesis, anywhere in the expression. A mention inside a string literal or a comment counts.\n- Calculation items are out of scope, so an IFERROR inside a calculation item is not reported even though it costs the same.\n- Only the object's own expression is read. A call inside a measure's dynamic format string is not reported.\n\nRead more: https://pbiplint.com/rules/avoid-using-the-iferror-function",
  },
  CALCULATION_GROUPS_WITH_NO_CALCULATION_ITEMS: {
    text: "Example\n\nFires the rule\n\ntable 'Time Intelligence'\n\n\tcalculationGroup\n\n\tcolumn 'Time Calculation'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Name\n\n\tpartition 'Time Intelligence' = calculationGroup\n\t\tmode: import\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tsourceColumn: Date\n\nAfter the fix\n\ntable 'Time Intelligence'\n\n\tcalculationGroup\n\n\t\tcalculationItem YTD = CALCULATE(SELECTEDMEASURE(), DATESYTD('Date'[Date]))\n\n\tcolumn 'Time Calculation'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Name\n\n\tpartition 'Time Intelligence' = calculationGroup\n\t\tmode: import\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tsourceColumn: Date\n\nWhy it matters\n\nA calculation group with no items still appears in the field list as a table with one column, and dropping that column on a visual does nothing. It is usually a group that was started and abandoned, and it puzzles whoever finds it later.\n\nHow to fix it\n\nIn Power BI Desktop, open Model view, find the group under Calculation groups in the Model explorer pane, choose New calculation item, and write its DAX in the formula bar. In the TMDL file the group is a calculationGroup block under the table, and each item is a calculationItem inside it with its DAX after the =. If the group is not wanted, delete the table: in Desktop, right-click it in the Data pane and choose Delete from model; in the project, remove its file from the tables folder and its ref table line from model.tmdl.\n\nWhen to ignore it\n\nThe one moment the finding is noise is while you are building the group, between creating it and writing the first item, when it tells you something you already know. There is no reason to ship one: an empty group is a field in the list that does nothing when a report author uses it.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = CALCULATION_GROUPS_WITH_NO_CALCULATION_ITEMS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"CALCULATION_GROUPS_WITH_NO_CALCULATION_ITEMS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The rule counts items, not what they do. A group with one item whose expression is empty leaves this rule's condition, and EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION picks it up instead.\n- pbiplint reads a table as a calculation group when the table carries a calculationGroup block, whatever its partition says, and rules scoped to tables or calculated tables then pass over it.\n\nRead more: https://pbiplint.com/rules/calculation-groups-with-no-calculation-items",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable 'Time Intelligence'\n\n\tcalculationGroup\n\n\tcolumn 'Time Calculation'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Name\n\n\tpartition 'Time Intelligence' = calculationGroup\n\t\tmode: import\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tsourceColumn: Date\n```\n\n**After the fix**\n\n```tmdl\ntable 'Time Intelligence'\n\n\tcalculationGroup\n\n\t\tcalculationItem YTD = CALCULATE(SELECTEDMEASURE(), DATESYTD('Date'[Date]))\n\n\tcolumn 'Time Calculation'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Name\n\n\tpartition 'Time Intelligence' = calculationGroup\n\t\tmode: import\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tsourceColumn: Date\n```\n\n### Why it matters\n\nA calculation group with no items still appears in the field list as a table with one column, and dropping that column on a visual does nothing. It is usually a group that was started and abandoned, and it puzzles whoever finds it later.\n\n### How to fix it\n\nIn Power BI Desktop, open Model view, find the group under Calculation groups in the Model explorer pane, choose New calculation item, and write its DAX in the formula bar. In the TMDL file the group is a `calculationGroup` block under the table, and each item is a `calculationItem` inside it with its DAX after the `=`. If the group is not wanted, delete the table: in Desktop, right-click it in the Data pane and choose Delete from model; in the project, remove its file from the `tables` folder and its `ref table` line from `model.tmdl`.\n\n### When to ignore it\n\nThe one moment the finding is noise is while you are building the group, between creating it and writing the first item, when it tells you something you already know. There is no reason to ship one: an empty group is a field in the list that does nothing when a report author uses it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = CALCULATION_GROUPS_WITH_NO_CALCULATION_ITEMS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"CALCULATION_GROUPS_WITH_NO_CALCULATION_ITEMS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The rule counts items, not what they do. A group with one item whose expression is empty leaves this rule's condition, and `EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION` picks it up instead.\n- pbiplint reads a table as a calculation group when the table carries a `calculationGroup` block, whatever its partition says, and rules scoped to tables or calculated tables then pass over it.\n\nRead more: https://pbiplint.com/rules/calculation-groups-with-no-calculation-items",
  },
  "CHECK_IF_BI-DIRECTIONAL_AND_MANY-TO-MANY_RELATIONSHIPS_ARE_VALID": {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: CustomerID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship Sales_Customer\n\tcrossFilteringBehavior: bothDirections\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: CustomerID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n\nWhy it matters\n\nBoth kinds have real uses, and both are easy to create by accident: Desktop offers bi-directional filtering as a dropdown, and it falls back to many-to-many when it finds duplicates on both sides of a key. An accidental one costs query time on every visual that touches the tables and can open a second filter path, which is where totals stop adding up without any error.\n\nHow to fix it\n\nLook at each one and decide whether it was meant. In Power BI Desktop, open the model view, double-click the relationship, and read the Cardinality and Cross filter direction dropdowns in the Edit relationship dialog; in the TMDL file the same three facts are fromCardinality, toCardinality, and crossFilteringBehavior under the relationship. Where the direction is not wanted, set Cross filter direction to Single, which is the crossFilteringBehavior: bothDirections line deleted, and move the reverse filter into the measures that need it with CROSSFILTER. Where the cardinality is many-to-many because the key column has duplicates, that is a data problem: remove the duplicates in Power Query with Remove Duplicates, or in the source view the query reads, then set Cardinality back to Many to one. Both dropdowns behave the same on an import model and a DirectQuery one.\n\nWhen to ignore it\n\nIgnoring is the ordinary outcome for a relationship you meant to create, and this rule exists to make you say so once. A bridge table between two dimensions, a security table that has to filter upward, a slicer that has to narrow to the values a fact table actually holds: each is a deliberate design and each stays. The check worth making before you ignore one is for a second filter path between the same two tables, which the model view shows as two routes; one route is a design, two is where the totals start disagreeing. Review the list again whenever relationships are added, because a path that was unique when you approved it may not be now.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = CHECK_IF_BI-DIRECTIONAL_AND_MANY-TO-MANY_RELATIONSHIPS_ARE_VALID under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"CHECK_IF_BI-DIRECTIONAL_AND_MANY-TO-MANY_RELATIONSHIPS_ARE_VALID\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- A relationship counts if it is bi-directional or many-to-many, so a many-to-one relationship that filters both ways is listed and so is a many-to-many relationship that filters one way.\n- Inactive relationships are listed. A relationship that only ever comes alive inside USERELATIONSHIP is reported the same as an active one.\n- A relationship that names no cardinality is many-to-one, which is Power BI's default, and one that names no cross filter direction is single, so a plain block with only fromColumn and toColumn is never listed.\n\nRead more: https://pbiplint.com/rules/check-if-bi-directional-and-many-to-many-relationships-are-valid",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: CustomerID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship Sales_Customer\n\tcrossFilteringBehavior: bothDirections\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: CustomerID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Customer\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer ID'\n\ttoColumn: Customer.'Customer ID'\n```\n\n### Why it matters\n\nBoth kinds have real uses, and both are easy to create by accident: Desktop offers bi-directional filtering as a dropdown, and it falls back to many-to-many when it finds duplicates on both sides of a key. An accidental one costs query time on every visual that touches the tables and can open a second filter path, which is where totals stop adding up without any error.\n\n### How to fix it\n\nLook at each one and decide whether it was meant. In Power BI Desktop, open the model view, double-click the relationship, and read the Cardinality and Cross filter direction dropdowns in the Edit relationship dialog; in the TMDL file the same three facts are `fromCardinality`, `toCardinality`, and `crossFilteringBehavior` under the relationship. Where the direction is not wanted, set Cross filter direction to Single, which is the `crossFilteringBehavior: bothDirections` line deleted, and move the reverse filter into the measures that need it with CROSSFILTER. Where the cardinality is many-to-many because the key column has duplicates, that is a data problem: remove the duplicates in Power Query with Remove Duplicates, or in the source view the query reads, then set Cardinality back to Many to one. Both dropdowns behave the same on an import model and a DirectQuery one.\n\n### When to ignore it\n\nIgnoring is the ordinary outcome for a relationship you meant to create, and this rule exists to make you say so once. A bridge table between two dimensions, a security table that has to filter upward, a slicer that has to narrow to the values a fact table actually holds: each is a deliberate design and each stays. The check worth making before you ignore one is for a second filter path between the same two tables, which the model view shows as two routes; one route is a design, two is where the totals start disagreeing. Review the list again whenever relationships are added, because a path that was unique when you approved it may not be now.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = CHECK_IF_BI-DIRECTIONAL_AND_MANY-TO-MANY_RELATIONSHIPS_ARE_VALID` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"CHECK_IF_BI-DIRECTIONAL_AND_MANY-TO-MANY_RELATIONSHIPS_ARE_VALID\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- A relationship counts if it is bi-directional or many-to-many, so a many-to-one relationship that filters both ways is listed and so is a many-to-many relationship that filters one way.\n- Inactive relationships are listed. A relationship that only ever comes alive inside USERELATIONSHIP is reported the same as an active one.\n- A relationship that names no cardinality is many-to-one, which is Power BI's default, and one that names no cross filter direction is single, so a plain block with only `fromColumn` and `toColumn` is never listed.\n\nRead more: https://pbiplint.com/rules/check-if-bi-directional-and-many-to-many-relationships-are-valid",
  },
  "CHECK_IF_DYNAMIC_ROW_LEVEL_SECURITY_(RLS)_IS_NECESSARY": {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable 'User Region'\n\tcolumn 'User Email'\n\t\tdataType: string\n\t\tsourceColumn: UserEmail\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrole 'Regional Users'\n\tmodelPermission: read\n\n\ttablePermission 'User Region' = 'User Region'[User Email] = USERPRINCIPALNAME()\n\nAfter the fix\n\ntable Sales\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\nrole East\n\tmodelPermission: read\n\n\ttablePermission Sales = 'Sales'[Region] = \"East\"\n\nrole West\n\tmodelPermission: read\n\n\ttablePermission Sales = 'Sales'[Region] = \"West\"\n\nWhy it matters\n\nA dynamic filter is evaluated for each user separately, so the engine cannot share a cached result between two people with the same access, and every query carries the lookup that maps the user to their rows. That is the right trade when the audience is large or changes often. When a handful of fixed groups each see a fixed slice, static roles with a plain filter are faster and simpler to audit.\n\nHow to fix it\n\nDecide whether the mapping has to be dynamic, then act on the decision. Keep the dynamic filter where the user-to-rows mapping lives in a table that changes without a redeploy, or where there are more audiences than anyone would maintain by hand. Otherwise replace it: in Power BI Desktop, under Modeling, Manage roles, create one role per audience with a plain filter such as [Region] = \"East\", then delete the dynamic role in the same dialog. In the TMDL file each role is a role block in the roles folder, and each filter is the expression after the = on a tablePermission line under it, so a static filter is the same line with the USERPRINCIPALNAME call gone. Members are assigned after publishing, in the workspace under Security on the semantic model; Power BI Desktop writes roles but never members. Where the dynamic filter stays, the thing worth shortening is the lookup behind it: hold the user-to-key mapping in a small table with the key already computed, so the filter is one comparison instead of a search.\n\nWhen to ignore it\n\nDynamic row-level security is a design, not a defect, and this rule is a prompt to confirm the design once rather than a queue to clear. Ignore it wherever the mapping table is the point: a model whose audience is every salesperson in the company, a hierarchy where a manager sees their reports' rows, anything where a new user should get access by appearing in a table rather than by someone editing the model. The finding is worth a second look in two places. One is a model with two or three fixed audiences, where static roles are simpler to explain to whoever audits access. The other is a dynamic filter over a large secured table, where the per-user lookup runs on every query and the fix is to precompute the key rather than to drop the pattern.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = CHECK_IF_DYNAMIC_ROW_LEVEL_SECURITY_(RLS)_IS_NECESSARY under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"CHECK_IF_DYNAMIC_ROW_LEVEL_SECURITY_(RLS)_IS_NECESSARY\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The two names are matched case-insensitively and as plain substrings ending in an opening parenthesis, so a call inside a comment or a string literal counts, and so does a function whose name ends in USERNAME(.\n- A space before the parenthesis, as some DAX formatters write, is not matched: USERPRINCIPALNAME () passes.\n- The finding is per table permission, so a role that filters three tables with the same call produces three findings, and two roles that filter the same table produce two.\n\nRead more: https://pbiplint.com/rules/check-if-dynamic-row-level-security-rls-is-necessary",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable 'User Region'\n\tcolumn 'User Email'\n\t\tdataType: string\n\t\tsourceColumn: UserEmail\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrole 'Regional Users'\n\tmodelPermission: read\n\n\ttablePermission 'User Region' = 'User Region'[User Email] = USERPRINCIPALNAME()\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\nrole East\n\tmodelPermission: read\n\n\ttablePermission Sales = 'Sales'[Region] = \"East\"\n\nrole West\n\tmodelPermission: read\n\n\ttablePermission Sales = 'Sales'[Region] = \"West\"\n```\n\n### Why it matters\n\nA dynamic filter is evaluated for each user separately, so the engine cannot share a cached result between two people with the same access, and every query carries the lookup that maps the user to their rows. That is the right trade when the audience is large or changes often. When a handful of fixed groups each see a fixed slice, static roles with a plain filter are faster and simpler to audit.\n\n### How to fix it\n\nDecide whether the mapping has to be dynamic, then act on the decision. Keep the dynamic filter where the user-to-rows mapping lives in a table that changes without a redeploy, or where there are more audiences than anyone would maintain by hand. Otherwise replace it: in Power BI Desktop, under Modeling, Manage roles, create one role per audience with a plain filter such as `[Region] = \"East\"`, then delete the dynamic role in the same dialog. In the TMDL file each role is a `role` block in the roles folder, and each filter is the expression after the `=` on a `tablePermission` line under it, so a static filter is the same line with the USERPRINCIPALNAME call gone. Members are assigned after publishing, in the workspace under Security on the semantic model; Power BI Desktop writes roles but never members. Where the dynamic filter stays, the thing worth shortening is the lookup behind it: hold the user-to-key mapping in a small table with the key already computed, so the filter is one comparison instead of a search.\n\n### When to ignore it\n\nDynamic row-level security is a design, not a defect, and this rule is a prompt to confirm the design once rather than a queue to clear. Ignore it wherever the mapping table is the point: a model whose audience is every salesperson in the company, a hierarchy where a manager sees their reports' rows, anything where a new user should get access by appearing in a table rather than by someone editing the model. The finding is worth a second look in two places. One is a model with two or three fixed audiences, where static roles are simpler to explain to whoever audits access. The other is a dynamic filter over a large secured table, where the per-user lookup runs on every query and the fix is to precompute the key rather than to drop the pattern.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = CHECK_IF_DYNAMIC_ROW_LEVEL_SECURITY_(RLS)_IS_NECESSARY` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"CHECK_IF_DYNAMIC_ROW_LEVEL_SECURITY_(RLS)_IS_NECESSARY\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The two names are matched case-insensitively and as plain substrings ending in an opening parenthesis, so a call inside a comment or a string literal counts, and so does a function whose name ends in `USERNAME(`.\n- A space before the parenthesis, as some DAX formatters write, is not matched: `USERPRINCIPALNAME ()` passes.\n- The finding is per table permission, so a role that filters three tables with the same call produces three findings, and two roles that filter the same table produce two.\n\nRead more: https://pbiplint.com/rules/check-if-dynamic-row-level-security-rls-is-necessary",
  },
  DATA_COLUMNS_MUST_HAVE_A_SOURCE_COLUMN: {
    text: 'Example\n\nFires the rule\n\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource =\n\t\t\t\tlet\n\t\t\t\t\tSource = Sql.Database("localhost", "Sales"),\n\t\t\t\t\tSales = Source{[Schema="dbo",Item="Sales"]}[Data]\n\t\t\t\tin\n\t\t\t\t\tSales\n\nAfter the fix\n\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource =\n\t\t\t\tlet\n\t\t\t\t\tSource = Sql.Database("localhost", "Sales"),\n\t\t\t\t\tSales = Source{[Schema="dbo",Item="Sales"]}[Data]\n\t\t\t\tin\n\t\t\t\t\tSales\n\nWhy it matters\n\nA data column is filled from a column in the partition query, and the source column name is how the engine finds it. Without it, processing fails for the whole table, with an error that names the column but not the cause.\n\nHow to fix it\n\nPower BI Desktop writes sourceColumn whenever it adds a column to a table, so a finding here means the column was written or edited by hand, or arrived in a migration. In the TMDL file, add a sourceColumn: line under the column, naming the field the partition\'s query produces and spelling it the way the query spells it. Where the query no longer produces it, the fix runs the other way: add the column back in Power Query, under Transform data, so the next refresh delivers it, or take the column out of the model, in Desktop by right-clicking it in the Data pane and choosing Delete from model, or by removing its column block from the table\'s TMDL file.\n\nWhen to ignore it\n\nThere is none. A data column with no source column stops the whole table from loading, so the finding is a refresh failure reported before the refresh. The one thing worth checking is whether the column was meant to be a calculated column: if it was, give it a DAX expression instead, and the column leaves this rule for EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION, which asks the same question of the expression.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = DATA_COLUMNS_MUST_HAVE_A_SOURCE_COLUMN under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set "DATA_COLUMNS_MUST_HAVE_A_SOURCE_COLUMN": "off" under rules in pbiplint.config.json.\n\nQuirks\n\n- Only data columns are read. pbiplint treats a column as calculated when its declaration carries an expression, and as a calculated table column when the table\'s partition is a calculated one, so neither is reported here.\n- Only the presence of the property is tested, never what it names. A sourceColumn that names a column the query does not produce passes the rule and fails the refresh.\n- A sourceColumn: line with nothing after it counts as missing, the same as no line at all.\n\nRead more: https://pbiplint.com/rules/data-columns-must-have-a-source-column',
    markdown:
      '### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource =\n\t\t\t\tlet\n\t\t\t\t\tSource = Sql.Database("localhost", "Sales"),\n\t\t\t\t\tSales = Source{[Schema="dbo",Item="Sales"]}[Data]\n\t\t\t\tin\n\t\t\t\t\tSales\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource =\n\t\t\t\tlet\n\t\t\t\t\tSource = Sql.Database("localhost", "Sales"),\n\t\t\t\t\tSales = Source{[Schema="dbo",Item="Sales"]}[Data]\n\t\t\t\tin\n\t\t\t\t\tSales\n```\n\n### Why it matters\n\nA data column is filled from a column in the partition query, and the source column name is how the engine finds it. Without it, processing fails for the whole table, with an error that names the column but not the cause.\n\n### How to fix it\n\nPower BI Desktop writes `sourceColumn` whenever it adds a column to a table, so a finding here means the column was written or edited by hand, or arrived in a migration. In the TMDL file, add a `sourceColumn:` line under the column, naming the field the partition\'s query produces and spelling it the way the query spells it. Where the query no longer produces it, the fix runs the other way: add the column back in Power Query, under Transform data, so the next refresh delivers it, or take the column out of the model, in Desktop by right-clicking it in the Data pane and choosing Delete from model, or by removing its `column` block from the table\'s TMDL file.\n\n### When to ignore it\n\nThere is none. A data column with no source column stops the whole table from loading, so the finding is a refresh failure reported before the refresh. The one thing worth checking is whether the column was meant to be a calculated column: if it was, give it a DAX expression instead, and the column leaves this rule for `EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION`, which asks the same question of the expression.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DATA_COLUMNS_MUST_HAVE_A_SOURCE_COLUMN` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"DATA_COLUMNS_MUST_HAVE_A_SOURCE_COLUMN": "off"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Only data columns are read. pbiplint treats a column as calculated when its declaration carries an expression, and as a calculated table column when the table\'s partition is a calculated one, so neither is reported here.\n- Only the presence of the property is tested, never what it names. A `sourceColumn` that names a column the query does not produce passes the rule and fails the refresh.\n- A `sourceColumn:` line with nothing after it counts as missing, the same as no line at all.\n\nRead more: https://pbiplint.com/rules/data-columns-must-have-a-source-column',
  },
  "DATE/CALENDAR_TABLES_SHOULD_BE_MARKED_AS_A_DATE_TABLE": {
    text: 'Example\n\nFires the rule\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n\nAfter the fix\n\ntable Date\n\tdataCategory: Time\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n\nWhy it matters\n\nMarking the date table tells the engine which column is the calendar key, and every time intelligence function relies on it: DATESYTD, SAMEPERIODLASTYEAR, and the rest return wrong or blank results over an unmarked table without raising any error. Marking it also lets you turn off Auto date/time, which otherwise adds a hidden date table for every date column in the model.\n\nHow to fix it\n\nIn Power BI Desktop, select the table in the Data pane, open Table tools, choose Mark as date table, and pick the column that holds the dates. Desktop checks the column before it accepts it: the values must be unique, have no blanks, carry the same time of day throughout, and run without a gap from the first day to the last. In the TMDL file the result is dataCategory: Time on the table and isKey on that column, and both have to be present before the finding clears. Where the column fails the check, fix it where it is loaded: in Transform data, remove the time part with Date under the Transform tab, drop the duplicate rows, and fill the gaps by generating the calendar rather than deriving it from a fact table. Where the table is not a calendar at all and only the name caught it, rename it or ignore the finding on it.\n\nWhen to ignore it\n\nThe name test is a plain substring, so Updates, Candidates, and Mandates are all reported with no date in them anywhere. Those findings are noise and the rule has no way to see it. A table that holds dates without being a calendar is the more interesting case: an Event Calendar of scheduled events, or a Date Changes audit log. Marking either one would be wrong, because it is a fact table and the marking declares a calendar key. A calendar at a grain other than the day is the third case, for example a Fiscal Calendar of one row per period; Mark as date table requires one contiguous row per day, so the table cannot be marked and the finding stays for as long as the table exists. What is not a legitimate exception is the model\'s real day-grain calendar left unmarked because time intelligence appears to work in a quick test; it fails quietly at the edges of the range.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = DATE/CALENDAR_TABLES_SHOULD_BE_MARKED_AS_A_DATE_TABLE under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set "DATE/CALENDAR_TABLES_SHOULD_BE_MARKED_AS_A_DATE_TABLE": "off" under rules in pbiplint.config.json.\n\nQuirks\n\n- The table name is upper-cased before the test and the match is a substring, so Date, date, and DATE_DIM all count, and so do Updates and Candidates.\n- The data category comparison is exact and case-sensitive. A file that says dataCategory: time does not count as marked.\n- The key has to be a DateTime column. A calendar keyed on an integer date key is reported however it is categorized.\n- Calculated tables are in scope and calculation groups are not, so a calendar built with CALENDAR is checked and a calculation group called Date Intelligence is left alone.\n\nRead more: https://pbiplint.com/rules/date-calendar-tables-should-be-marked-as-a-date-table',
    markdown:
      '### Example\n\n**Fires the rule**\n\n```tmdl\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n```\n\n**After the fix**\n\n```tmdl\ntable Date\n\tdataCategory: Time\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n```\n\n### Why it matters\n\nMarking the date table tells the engine which column is the calendar key, and every time intelligence function relies on it: DATESYTD, SAMEPERIODLASTYEAR, and the rest return wrong or blank results over an unmarked table without raising any error. Marking it also lets you turn off Auto date/time, which otherwise adds a hidden date table for every date column in the model.\n\n### How to fix it\n\nIn Power BI Desktop, select the table in the Data pane, open Table tools, choose Mark as date table, and pick the column that holds the dates. Desktop checks the column before it accepts it: the values must be unique, have no blanks, carry the same time of day throughout, and run without a gap from the first day to the last. In the TMDL file the result is `dataCategory: Time` on the table and `isKey` on that column, and both have to be present before the finding clears. Where the column fails the check, fix it where it is loaded: in Transform data, remove the time part with Date under the Transform tab, drop the duplicate rows, and fill the gaps by generating the calendar rather than deriving it from a fact table. Where the table is not a calendar at all and only the name caught it, rename it or ignore the finding on it.\n\n### When to ignore it\n\nThe name test is a plain substring, so Updates, Candidates, and Mandates are all reported with no date in them anywhere. Those findings are noise and the rule has no way to see it. A table that holds dates without being a calendar is the more interesting case: an Event Calendar of scheduled events, or a Date Changes audit log. Marking either one would be wrong, because it is a fact table and the marking declares a calendar key. A calendar at a grain other than the day is the third case, for example a Fiscal Calendar of one row per period; Mark as date table requires one contiguous row per day, so the table cannot be marked and the finding stays for as long as the table exists. What is not a legitimate exception is the model\'s real day-grain calendar left unmarked because time intelligence appears to work in a quick test; it fails quietly at the edges of the range.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DATE/CALENDAR_TABLES_SHOULD_BE_MARKED_AS_A_DATE_TABLE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"DATE/CALENDAR_TABLES_SHOULD_BE_MARKED_AS_A_DATE_TABLE": "off"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The table name is upper-cased before the test and the match is a substring, so `Date`, `date`, and `DATE_DIM` all count, and so do Updates and Candidates.\n- The data category comparison is exact and case-sensitive. A file that says `dataCategory: time` does not count as marked.\n- The key has to be a DateTime column. A calendar keyed on an integer date key is reported however it is categorized.\n- Calculated tables are in scope and calculation groups are not, so a calendar built with CALENDAR is checked and a calculation group called Date Intelligence is left alone.\n\nRead more: https://pbiplint.com/rules/date-calendar-tables-should-be-marked-as-a-date-table',
  },
  DATECOLUMN_FORMATSTRING: {
    text: 'Example\n\nFires the rule\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n\nAfter the fix\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsummarizeBy: none\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n\nWhy it matters\n\nA date column with no format string is shown however the viewer\'s locale and the visual decide, so the same column can read 3/4/2026 in one visual and 4 March 2026 in another. A format string on the column fixes the presentation once for every report. The source ruleset picked the US short date as its convention.\n\nHow to fix it\n\nIn Power BI Desktop, select the column in the Data pane and set Format under Column tools. In the TMDL file, add formatString: mm/dd/yyyy under the column. The format string changes only how the value is rendered; the stored value and the data type are untouched, so nothing downstream of the model has to change with it.\n\nWhen to ignore it\n\nA model whose house convention is a different date order has nothing to gain here: every date column in it fires, and rewriting them all to the US short date is a worse outcome than the finding. Pick the format your readers expect, set it consistently, and treat the rule as house style you have already settled. The other case is a DateTime column that is not a date a reader ever sees, such as a hidden load timestamp caught by the name test, where a format string changes nothing on screen.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = DATECOLUMN_FORMATSTRING under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set "DATECOLUMN_FORMATSTRING": "off" under rules in pbiplint.config.json.\n\nQuirks\n\n- The name test is a substring matched without regard to letter case, so any column containing the letters date is checked, including Update Time and Candidate Start.\n- Only the exact string mm/dd/yyyy passes, and the comparison is case-sensitive, so a format string that differs from it only in letter case is still reported. Every other format fires too, including dd/mm/yyyy and yyyy-mm-dd.\n- Hidden columns and columns in hidden tables are in scope.\n- Only DateTime columns are read. A date held as text or as an integer date key is not reported here.\n\nRead more: https://pbiplint.com/rules/datecolumn-formatstring',
    markdown:
      '### Example\n\n**Fires the rule**\n\n```tmdl\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n```\n\n**After the fix**\n\n```tmdl\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsummarizeBy: none\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n```\n\n### Why it matters\n\nA date column with no format string is shown however the viewer\'s locale and the visual decide, so the same column can read 3/4/2026 in one visual and 4 March 2026 in another. A format string on the column fixes the presentation once for every report. The source ruleset picked the US short date as its convention.\n\n### How to fix it\n\nIn Power BI Desktop, select the column in the Data pane and set Format under Column tools. In the TMDL file, add `formatString: mm/dd/yyyy` under the column. The format string changes only how the value is rendered; the stored value and the data type are untouched, so nothing downstream of the model has to change with it.\n\n### When to ignore it\n\nA model whose house convention is a different date order has nothing to gain here: every date column in it fires, and rewriting them all to the US short date is a worse outcome than the finding. Pick the format your readers expect, set it consistently, and treat the rule as house style you have already settled. The other case is a DateTime column that is not a date a reader ever sees, such as a hidden load timestamp caught by the name test, where a format string changes nothing on screen.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DATECOLUMN_FORMATSTRING` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"DATECOLUMN_FORMATSTRING": "off"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The name test is a substring matched without regard to letter case, so any column containing the letters date is checked, including Update Time and Candidate Start.\n- Only the exact string `mm/dd/yyyy` passes, and the comparison is case-sensitive, so a format string that differs from it only in letter case is still reported. Every other format fires too, including `dd/mm/yyyy` and `yyyy-mm-dd`.\n- Hidden columns and columns in hidden tables are in scope.\n- Only DateTime columns are read. A date held as text or as an integer date key is not reported here.\n\nRead more: https://pbiplint.com/rules/datecolumn-formatstring',
  },
  DAX_COLUMNS_FULLY_QUALIFIED: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM([Amount])\n\t\tformatString: #,0\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nIn DAX a bare [Name] is the convention for a measure. A column written the same way reads as a measure to everyone who maintains the model, and the two behave differently in a row context, so the expression is misread before it is ever debugged. The bare form also breaks when the column moves to another table, or when a measure with the same name is added and the engine binds to that instead.\n\nHow to fix it\n\nPut the table name in front of every column reference:\n\nTotal Sales = SUM ( 'Sales'[Amount] )\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar, which completes the qualified form as soon as you start typing the table name. A row-level security filter is edited under Modeling, Manage roles. In the TMDL file, edit the expression after measure 'Total Sales' =, or the filter after tablePermission Sales = inside the role.\n\nWhen to ignore it\n\nThere is no case for the bare form. The rule is worth reading as a warning rather than a style note: the reference that fires it resolved to a column because no measure of that name exists today, and the day someone adds one, the expression silently starts reading the measure instead. Qualifying it is what stops that.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = DAX_COLUMNS_FULLY_QUALIFIED under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"DAX_COLUMNS_FULLY_QUALIFIED\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Calculation items are in the rule's scope but never fire, because Tabular Editor does not resolve bare column references inside calculation items and pbiplint matches that.\n- A bare name that matches any measure in the model is treated as a measure reference, so a column that shares its name with a measure is never flagged.\n- A bare name that matches no measure is looked for on the expression's own table first, then on every other table in model order, so a finding can be raised by a column that lives on a table the expression never mentions.\n- References are found by pattern matching, so a bare [Column] inside a string literal or a comment counts.\n- A measure's dynamic format string is read together with its expression, so a bare column reference written inside formatStringDefinition reports the measure that carries it.\n- Calculated columns and calculated tables are out of scope, so a bare column reference in either is not reported.\n\nRead more: https://pbiplint.com/rules/dax-columns-fully-qualified",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM([Amount])\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nIn DAX a bare `[Name]` is the convention for a measure. A column written the same way reads as a measure to everyone who maintains the model, and the two behave differently in a row context, so the expression is misread before it is ever debugged. The bare form also breaks when the column moves to another table, or when a measure with the same name is added and the engine binds to that instead.\n\n### How to fix it\n\nPut the table name in front of every column reference:\n\n```\nTotal Sales = SUM ( 'Sales'[Amount] )\n```\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar, which completes the qualified form as soon as you start typing the table name. A row-level security filter is edited under Modeling, Manage roles. In the TMDL file, edit the expression after `measure 'Total Sales' =`, or the filter after `tablePermission Sales =` inside the role.\n\n### When to ignore it\n\nThere is no case for the bare form. The rule is worth reading as a warning rather than a style note: the reference that fires it resolved to a column because no measure of that name exists today, and the day someone adds one, the expression silently starts reading the measure instead. Qualifying it is what stops that.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DAX_COLUMNS_FULLY_QUALIFIED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"DAX_COLUMNS_FULLY_QUALIFIED\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Calculation items are in the rule's scope but never fire, because Tabular Editor does not resolve bare column references inside calculation items and pbiplint matches that.\n- A bare name that matches any measure in the model is treated as a measure reference, so a column that shares its name with a measure is never flagged.\n- A bare name that matches no measure is looked for on the expression's own table first, then on every other table in model order, so a finding can be raised by a column that lives on a table the expression never mentions.\n- References are found by pattern matching, so a bare `[Column]` inside a string literal or a comment counts.\n- A measure's dynamic format string is read together with its expression, so a bare column reference written inside `formatStringDefinition` reports the measure that carries it.\n- Calculated columns and calculated tables are out of scope, so a bare column reference in either is not reported.\n\nRead more: https://pbiplint.com/rules/dax-columns-fully-qualified",
  },
  DAX_MEASURES_UNQUALIFIED: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Average Price' = DIVIDE('Sales'[Total Sales], SUM(Sales[Quantity]))\n\t\tformatString: #,0.00\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Average Price' = DIVIDE([Total Sales], SUM(Sales[Quantity]))\n\t\tformatString: #,0.00\n\nWhy it matters\n\nA measure belongs to the model, not to the table it sits in; the table is only its home in the field list. Writing 'Sales'[Total Sales] makes it look like a column, which changes what the next reader expects it to do, and it breaks the moment someone moves the measure to a measure table, which is a routine tidy-up.\n\nHow to fix it\n\nDelete the table name from the reference and leave the brackets:\n\nAverage Price = DIVIDE ( [Total Sales], SUM ( Sales[Quantity] ) )\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; the same goes for a calculated column, a calculated table, and a calculation item, each selected in the model view or the Data pane. In the TMDL file, edit the expression after measure 'Average Price' =, after column Name = for a calculated column, after source = in a calculated table's partition, or after calculationItem Name = in the calculation group.\n\nWhen to ignore it\n\nThere is no case for the table prefix on a measure. If a finding surprises you, check whether the table really does hold a measure of that name: pbiplint resolves 'Table'[Name] to a column first and only calls it a measure when the table has no column of that name, so a finding here means the reference bound to a measure.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = DAX_MEASURES_UNQUALIFIED under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"DAX_MEASURES_UNQUALIFIED\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- References are found by pattern matching, so a qualified measure reference inside a string literal or a comment counts.\n- A measure's dynamic format string is read together with its expression, so 'Sales'[Total Sales] written inside formatStringDefinition reports the measure that carries it.\n- The reference has to resolve. 'Sales'[Total Sales] written where the model has no table called Sales, or where Sales has no measure of that name, is not reported by this rule at all.\n- Row-level security filters are out of scope, so a qualified measure reference inside a role's table filter is never reported.\n- The table name may be written bare or in single quotes; both forms are matched.\n\nRead more: https://pbiplint.com/rules/dax-measures-unqualified",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Average Price' = DIVIDE('Sales'[Total Sales], SUM(Sales[Quantity]))\n\t\tformatString: #,0.00\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Average Price' = DIVIDE([Total Sales], SUM(Sales[Quantity]))\n\t\tformatString: #,0.00\n```\n\n### Why it matters\n\nA measure belongs to the model, not to the table it sits in; the table is only its home in the field list. Writing `'Sales'[Total Sales]` makes it look like a column, which changes what the next reader expects it to do, and it breaks the moment someone moves the measure to a measure table, which is a routine tidy-up.\n\n### How to fix it\n\nDelete the table name from the reference and leave the brackets:\n\n```\nAverage Price = DIVIDE ( [Total Sales], SUM ( Sales[Quantity] ) )\n```\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; the same goes for a calculated column, a calculated table, and a calculation item, each selected in the model view or the Data pane. In the TMDL file, edit the expression after `measure 'Average Price' =`, after `column Name =` for a calculated column, after `source =` in a calculated table's partition, or after `calculationItem Name =` in the calculation group.\n\n### When to ignore it\n\nThere is no case for the table prefix on a measure. If a finding surprises you, check whether the table really does hold a measure of that name: pbiplint resolves `'Table'[Name]` to a column first and only calls it a measure when the table has no column of that name, so a finding here means the reference bound to a measure.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DAX_MEASURES_UNQUALIFIED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"DAX_MEASURES_UNQUALIFIED\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- References are found by pattern matching, so a qualified measure reference inside a string literal or a comment counts.\n- A measure's dynamic format string is read together with its expression, so `'Sales'[Total Sales]` written inside `formatStringDefinition` reports the measure that carries it.\n- The reference has to resolve. `'Sales'[Total Sales]` written where the model has no table called Sales, or where Sales has no measure of that name, is not reported by this rule at all.\n- Row-level security filters are out of scope, so a qualified measure reference inside a role's table filter is never reported.\n- The table name may be written bare or in single quotes; both forms are matched.\n\nRead more: https://pbiplint.com/rules/dax-measures-unqualified",
  },
  ENSURE_TABLES_HAVE_RELATIONSHIPS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nWhy it matters\n\nA table that relates to nothing filters nothing and is filtered by nothing, so a visual that mixes its columns with another table's shows the same value repeated on every row. Sometimes that is the point: a parameter table, a measure table, or a security lookup that is read from DAX. More often it is a table that was loaded and never wired up, or a relationship that was deleted by accident.\n\nHow to fix it\n\nIn Power BI Desktop, open Model view and drag the key column of the fact table onto the matching column of the dimension, or use Manage relationships, New, and pick the two columns. Check the cardinality and the cross filter direction that Desktop proposes before you accept them. In the TMDL file a relationship is a relationship block of its own, with fromColumn on the many side and toColumn on the one side, each written as Table.Column. If the table really does stand alone, leave it as it is.\n\nWhen to ignore it\n\nA table that is meant to stand alone is the case to ignore: a what-if parameter table, a field parameter table, a table of slicer labels that a measure reads with SELECTEDVALUE, a list of thresholds compared against measures, or a lookup table read only by a row-level security filter. Check that the table is one of those before you ignore the finding, because the same line appears when a relationship was dropped in a merge or when a rename left the relationship pointing at a table name that no longer exists.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = ENSURE_TABLES_HAVE_RELATIONSHIPS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"ENSURE_TABLES_HAVE_RELATIONSHIPS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The rule reads relationships by the table names written in them, matched exactly. A relationship that spells the table differently, in letter case or after a rename, counts for the name it carries and not for the table, so the table is still reported.\n- Visibility is not read. A hidden measures table with a single hidden column is reported like any other table.\n- A table with no partitions, such as one whose file was only partly written, is a table to this rule and is reported when nothing relates to it.\n\nRead more: https://pbiplint.com/rules/ensure-tables-have-relationships",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n### Why it matters\n\nA table that relates to nothing filters nothing and is filtered by nothing, so a visual that mixes its columns with another table's shows the same value repeated on every row. Sometimes that is the point: a parameter table, a measure table, or a security lookup that is read from DAX. More often it is a table that was loaded and never wired up, or a relationship that was deleted by accident.\n\n### How to fix it\n\nIn Power BI Desktop, open Model view and drag the key column of the fact table onto the matching column of the dimension, or use Manage relationships, New, and pick the two columns. Check the cardinality and the cross filter direction that Desktop proposes before you accept them. In the TMDL file a relationship is a `relationship` block of its own, with `fromColumn` on the many side and `toColumn` on the one side, each written as `Table.Column`. If the table really does stand alone, leave it as it is.\n\n### When to ignore it\n\nA table that is meant to stand alone is the case to ignore: a what-if parameter table, a field parameter table, a table of slicer labels that a measure reads with SELECTEDVALUE, a list of thresholds compared against measures, or a lookup table read only by a row-level security filter. Check that the table is one of those before you ignore the finding, because the same line appears when a relationship was dropped in a merge or when a rename left the relationship pointing at a table name that no longer exists.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = ENSURE_TABLES_HAVE_RELATIONSHIPS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"ENSURE_TABLES_HAVE_RELATIONSHIPS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The rule reads relationships by the table names written in them, matched exactly. A relationship that spells the table differently, in letter case or after a rename, counts for the name it carries and not for the table, so the table is still reported.\n- Visibility is not read. A hidden measures table with a single hidden column is reported like any other table.\n- A table with no partitions, such as one whose file was only partly written, is a table to this rule and is reported when nothing relates to it.\n\nRead more: https://pbiplint.com/rules/ensure-tables-have-relationships",
  },
  EVALUATEANDLOG_SHOULD_NOT_BE_USED_IN_PRODUCTION_MODELS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = DIVIDE(EVALUATEANDLOG(SUM(Sales[Amount])), SUM(Sales[Quantity]))\n\t\tformatString: #,0.00\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = DIVIDE(SUM(Sales[Amount]), SUM(Sales[Quantity]))\n\t\tformatString: #,0.00\n\nWhy it matters\n\nEVALUATEANDLOG is a debugging aid: in Power BI Desktop it emits a trace event with its argument on every evaluation so you can watch intermediate values. The service ignores it. Leaving it in a published model ships debug scaffolding that every reader has to look past, and anyone who opens the file in Desktop gets trace output they did not ask for.\n\nHow to fix it\n\nDelete the wrapper and keep what was inside it. EVALUATEANDLOG returns its first argument unchanged, so removing it cannot change the result:\n\nAverage Price = DIVIDE ( SUM ( Sales[Amount] ), SUM ( Sales[Quantity] ) )\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar. In the TMDL file, edit the expression after measure 'Average Price' =. Where the call has a second argument it is only the label the trace event carries, so it goes with the wrapper.\n\nWhen to ignore it\n\nWhile you are actually debugging the measure, the call is the point, and the finding is telling you what you already know. The rule is worth leaving on so the call cannot reach a published model by accident: ignore the finding for the length of the investigation, not for the life of the measure. A model that is never published, such as a scratch file used to work out a pattern, is the one case where the finding has nothing behind it.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = EVALUATEANDLOG_SHOULD_NOT_BE_USED_IN_PRODUCTION_MODELS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"EVALUATEANDLOG_SHOULD_NOT_BE_USED_IN_PRODUCTION_MODELS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The test is for the text EVALUATEANDLOG(, in any letter case and with any spacing before the parenthesis, anywhere in the expression. A mention inside a string literal or a comment counts.\n- Measures only. A calculated column or a calculation item that calls the function is not reported, even though it reaches a published model the same way.\n- Only the measure's own expression is read. A call inside a dynamic format string is not reported.\n\nRead more: https://pbiplint.com/rules/evaluateandlog-should-not-be-used-in-production-models",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = DIVIDE(EVALUATEANDLOG(SUM(Sales[Amount])), SUM(Sales[Quantity]))\n\t\tformatString: #,0.00\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = DIVIDE(SUM(Sales[Amount]), SUM(Sales[Quantity]))\n\t\tformatString: #,0.00\n```\n\n### Why it matters\n\nEVALUATEANDLOG is a debugging aid: in Power BI Desktop it emits a trace event with its argument on every evaluation so you can watch intermediate values. The service ignores it. Leaving it in a published model ships debug scaffolding that every reader has to look past, and anyone who opens the file in Desktop gets trace output they did not ask for.\n\n### How to fix it\n\nDelete the wrapper and keep what was inside it. EVALUATEANDLOG returns its first argument unchanged, so removing it cannot change the result:\n\n```\nAverage Price = DIVIDE ( SUM ( Sales[Amount] ), SUM ( Sales[Quantity] ) )\n```\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar. In the TMDL file, edit the expression after `measure 'Average Price' =`. Where the call has a second argument it is only the label the trace event carries, so it goes with the wrapper.\n\n### When to ignore it\n\nWhile you are actually debugging the measure, the call is the point, and the finding is telling you what you already know. The rule is worth leaving on so the call cannot reach a published model by accident: ignore the finding for the length of the investigation, not for the life of the measure. A model that is never published, such as a scratch file used to work out a pattern, is the one case where the finding has nothing behind it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = EVALUATEANDLOG_SHOULD_NOT_BE_USED_IN_PRODUCTION_MODELS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"EVALUATEANDLOG_SHOULD_NOT_BE_USED_IN_PRODUCTION_MODELS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The test is for the text `EVALUATEANDLOG(`, in any letter case and with any spacing before the parenthesis, anywhere in the expression. A mention inside a string literal or a comment counts.\n- Measures only. A calculated column or a calculation item that calls the function is not reported, even though it reaches a published model the same way.\n- Only the measure's own expression is read. A call inside a dynamic format string is not reported.\n\nRead more: https://pbiplint.com/rules/evaluateandlog-should-not-be-used-in-production-models",
  },
  EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION: {
    text: "Example\n\nTotal Margin in the first snippet has nothing after its =. That is what an empty expression looks like in a TMDL file: the declaration is followed by another declaration at the same indentation, so nothing beneath it becomes the expression.\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tsourceColumn: Cost\n\n\tmeasure 'Total Margin' =\n\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tsourceColumn: Cost\n\n\tmeasure 'Total Margin' = SUM(Sales[Amount]) - SUM(Sales[Cost])\n\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nWithout an expression the object cannot be evaluated: a measure returns nothing, a calculated column is empty, and a calculation item does nothing. Depending on the engine version the deployment fails outright, and the error points at the object without saying why.\n\nHow to fix it\n\nWrite the DAX, or delete the object. In Power BI Desktop, select the measure in the Data pane and type the expression in the formula bar, or right-click it and choose Delete from model; a calculated column takes the same two routes from the same pane, and a calculation item is edited in the calculation group's own view. In the TMDL file the expression is whatever follows the =, either on the declaration line or in the block indented beneath it, so measure 'Total Margin' = SUM(Sales[Amount]) - SUM(Sales[Cost]) is the whole repair. Where the object is not wanted, remove its measure, column, or calculationItem block instead.\n\nWhen to ignore it\n\nThere is no case for keeping one. An object with no expression returns nothing wherever a report puts it, and the deployment may refuse it outright. A measure left blank as a placeholder while the work is unfinished is the closest thing to an exception, and giving it a body of BLANK() costs nothing and keeps the model valid in the meantime.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- An expression of only whitespace counts the same as no expression at all.\n- The block that follows a = is taken whole, before any property beneath the declaration is read. A formatString line written directly under a declaration whose = has nothing after it becomes that object's expression rather than its format string, so the rule stays quiet and PROVIDE_FORMAT_STRING_FOR_MEASURES reports the measure instead. An expression is empty only when the declaration is followed by a line indented no further than the declaration itself.\n\nRead more: https://pbiplint.com/rules/expression-reliant-objects-must-have-an-expression",
    markdown:
      "### Example\n\n`Total Margin` in the first snippet has nothing after its `=`. That is what an empty expression looks like in a TMDL file: the declaration is followed by another declaration at the same indentation, so nothing beneath it becomes the expression.\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tsourceColumn: Cost\n\n\tmeasure 'Total Margin' =\n\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tsourceColumn: Cost\n\n\tmeasure 'Total Margin' = SUM(Sales[Amount]) - SUM(Sales[Cost])\n\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nWithout an expression the object cannot be evaluated: a measure returns nothing, a calculated column is empty, and a calculation item does nothing. Depending on the engine version the deployment fails outright, and the error points at the object without saying why.\n\n### How to fix it\n\nWrite the DAX, or delete the object. In Power BI Desktop, select the measure in the Data pane and type the expression in the formula bar, or right-click it and choose Delete from model; a calculated column takes the same two routes from the same pane, and a calculation item is edited in the calculation group's own view. In the TMDL file the expression is whatever follows the `=`, either on the declaration line or in the block indented beneath it, so `measure 'Total Margin' = SUM(Sales[Amount]) - SUM(Sales[Cost])` is the whole repair. Where the object is not wanted, remove its `measure`, `column`, or `calculationItem` block instead.\n\n### When to ignore it\n\nThere is no case for keeping one. An object with no expression returns nothing wherever a report puts it, and the deployment may refuse it outright. A measure left blank as a placeholder while the work is unfinished is the closest thing to an exception, and giving it a body of `BLANK()` costs nothing and keeps the model valid in the meantime.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- An expression of only whitespace counts the same as no expression at all.\n- The block that follows a `=` is taken whole, before any property beneath the declaration is read. A `formatString` line written directly under a declaration whose `=` has nothing after it becomes that object's expression rather than its format string, so the rule stays quiet and `PROVIDE_FORMAT_STRING_FOR_MEASURES` reports the measure instead. An expression is empty only when the declaration is followed by a line indented no further than the declaration itself.\n\nRead more: https://pbiplint.com/rules/expression-reliant-objects-must-have-an-expression",
  },
  FILTER_COLUMN_VALUES: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Bike Sales' = CALCULATE([Total Sales], FILTER('Product', 'Product'[Category] = \"Bikes\"))\n\t\tformatString: #,0\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Bike Sales' = CALCULATE([Total Sales], KEEPFILTERS('Product'[Category] = \"Bikes\"))\n\t\tformatString: #,0\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nWhy it matters\n\nFILTER over a whole table walks every row, keeps the ones that pass, and hands that row set to CALCULATE. A plain column predicate, 'Table'[Column] = \"Value\", is applied to the column's distinct values before any row is touched, which is far cheaper on a fact table and lets the storage engine do the work. The two forms also differ in meaning: FILTER over the table respects a filter already on the column, which the plain predicate replaces, so KEEPFILTERS is the exact equivalent.\n\nHow to fix it\n\nDrop the FILTER and pass the predicate itself. Wrap it in KEEPFILTERS to keep whatever filter the visual already puts on the column, which is what the FILTER form was doing:\n\nBike Sales = CALCULATE ( [Total Sales], KEEPFILTERS ( 'Product'[Category] = \"Bikes\" ) )\n\nLeave KEEPFILTERS off to replace that filter instead, which is what a bare predicate inside CALCULATE means. The SQLBI article under Links covers which one you want. In Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column and a calculation item are edited the same way. In the TMDL file, edit the expression after measure 'Bike Sales' =, after column Name = for a calculated column, or after calculationItem Name = in the calculation group.\n\nWhen to ignore it\n\nA predicate that reads two columns of the same table row by row has no column equivalent: FILTER('Sales', 'Sales'[Amount] > 'Sales'[Budget]) needs the row context that FILTER supplies, and there is nothing to rewrite. The finding is also worth less on a small dimension table, where the table has a few hundred rows and the column a few dozen distinct values, than on a fact table with millions. What to check before deciding is which table the FILTER is over, not which table the measure lives on.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = FILTER_COLUMN_VALUES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"FILTER_COLUMN_VALUES\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The pattern accepts a space as the table name, so a predicate that starts with a bracketed name, FILTER('Product', [Total Sales] > 1000), is flagged by this rule as well as by FILTER_MEASURE_VALUES_BY_COLUMNS. The space after the comma is what makes that match, so the same predicate written as FILTER('Product',[Total Sales] > 1000) is reported only by the other rule.\n- Only the first filter argument is checked, and only when the expression before it contains no comma. CALCULATE(DIVIDE([A], [B]), FILTER(...)) passes, and so does a FILTER that comes after another filter argument.\n- Table and column names must contain only letters, digits, spaces, and underscores. A column called Category-Name puts the expression out of the pattern's reach.\n- CALCULATETABLE is matched by a second pattern of its own, with the same shape.\n- Function names are matched in any letter case and with any spacing before the parenthesis.\n- The expression is read as raw text, so a CALCULATE and FILTER shape written inside a string literal or a comment counts.\n\nRead more: https://pbiplint.com/rules/filter-column-values",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Bike Sales' = CALCULATE([Total Sales], FILTER('Product', 'Product'[Category] = \"Bikes\"))\n\t\tformatString: #,0\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Bike Sales' = CALCULATE([Total Sales], KEEPFILTERS('Product'[Category] = \"Bikes\"))\n\t\tformatString: #,0\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n### Why it matters\n\nFILTER over a whole table walks every row, keeps the ones that pass, and hands that row set to CALCULATE. A plain column predicate, `'Table'[Column] = \"Value\"`, is applied to the column's distinct values before any row is touched, which is far cheaper on a fact table and lets the storage engine do the work. The two forms also differ in meaning: FILTER over the table respects a filter already on the column, which the plain predicate replaces, so KEEPFILTERS is the exact equivalent.\n\n### How to fix it\n\nDrop the FILTER and pass the predicate itself. Wrap it in KEEPFILTERS to keep whatever filter the visual already puts on the column, which is what the FILTER form was doing:\n\n```\nBike Sales = CALCULATE ( [Total Sales], KEEPFILTERS ( 'Product'[Category] = \"Bikes\" ) )\n```\n\nLeave KEEPFILTERS off to replace that filter instead, which is what a bare predicate inside CALCULATE means. The SQLBI article under Links covers which one you want. In Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column and a calculation item are edited the same way. In the TMDL file, edit the expression after `measure 'Bike Sales' =`, after `column Name =` for a calculated column, or after `calculationItem Name =` in the calculation group.\n\n### When to ignore it\n\nA predicate that reads two columns of the same table row by row has no column equivalent: `FILTER('Sales', 'Sales'[Amount] > 'Sales'[Budget])` needs the row context that FILTER supplies, and there is nothing to rewrite. The finding is also worth less on a small dimension table, where the table has a few hundred rows and the column a few dozen distinct values, than on a fact table with millions. What to check before deciding is which table the FILTER is over, not which table the measure lives on.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = FILTER_COLUMN_VALUES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"FILTER_COLUMN_VALUES\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The pattern accepts a space as the table name, so a predicate that starts with a bracketed name, `FILTER('Product', [Total Sales] > 1000)`, is flagged by this rule as well as by `FILTER_MEASURE_VALUES_BY_COLUMNS`. The space after the comma is what makes that match, so the same predicate written as `FILTER('Product',[Total Sales] > 1000)` is reported only by the other rule.\n- Only the first filter argument is checked, and only when the expression before it contains no comma. `CALCULATE(DIVIDE([A], [B]), FILTER(...))` passes, and so does a FILTER that comes after another filter argument.\n- Table and column names must contain only letters, digits, spaces, and underscores. A column called `Category-Name` puts the expression out of the pattern's reach.\n- CALCULATETABLE is matched by a second pattern of its own, with the same shape.\n- Function names are matched in any letter case and with any spacing before the parenthesis.\n- The expression is read as raw text, so a CALCULATE and FILTER shape written inside a string literal or a comment counts.\n\nRead more: https://pbiplint.com/rules/filter-column-values",
  },
  FILTER_MEASURE_VALUES_BY_COLUMNS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Best Seller Sales' = CALCULATE([Total Sales], FILTER('Product', [Total Sales] > 1000))\n\t\tformatString: #,0\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Best Seller Sales' = CALCULATE([Total Sales], FILTER(VALUES('Product'[Product ID]), [Total Sales] > 1000))\n\t\tformatString: #,0\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nWhy it matters\n\nFILTER over a whole table evaluates the measure once per row of the table. Over a fact table that is millions of measure evaluations to keep a few rows. Filtering the distinct values of one column instead evaluates the measure once per value, usually thousands of times fewer, and produces the same rows.\n\nHow to fix it\n\nIterate the column the answer actually varies by, not the table:\n\nBest Seller Sales = CALCULATE ( [Total Sales], FILTER ( VALUES ( 'Product'[Product ID] ), [Total Sales] > 1000 ) )\n\nVALUES respects the filter already on the column; swap in ALL to ignore it. Pick the column with the fewest distinct values that still gives the right answer, and note that passing a column also narrows what the filter carries into CALCULATE, one column's values rather than whole rows of the table, so the rewrite pays even where the column you iterate is the table's key. In Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column and a calculation item are edited the same way. In the TMDL file, edit the expression after measure 'Best Seller Sales' =, after column Name = for a calculated column, or after calculationItem Name = in the calculation group.\n\nWhen to ignore it\n\nWhere the measure's value depends on more than one column of the table, no single column's distinct values reproduce the row set, and iterating the table is the honest form. Sales per product and store is the usual shape: iterate both columns together rather than the table if you can, and leave the finding alone if you cannot. The finding is also worth less over a small dimension, where the table has a few hundred rows and the column a few dozen distinct values, than over a fact table.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = FILTER_MEASURE_VALUES_BY_COLUMNS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"FILTER_MEASURE_VALUES_BY_COLUMNS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Only the first filter argument is checked, and only when the expression before it contains no comma. CALCULATE(DIVIDE([A], [B]), FILTER(...)) passes, and so does a FILTER that comes after another filter argument.\n- The predicate only has to start with a bracketed name, so a bare column reference, FILTER('Product', [Category] = \"Bikes\"), is reported here as well.\n- Table names must contain only letters, digits, spaces, and underscores.\n- CALCULATETABLE is matched by a second pattern of its own, with the same shape.\n- Function names are matched in any letter case and with any spacing before the parenthesis.\n- The expression is read as raw text, so a CALCULATE and FILTER shape written inside a string literal or a comment counts.\n\nRead more: https://pbiplint.com/rules/filter-measure-values-by-columns",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Best Seller Sales' = CALCULATE([Total Sales], FILTER('Product', [Total Sales] > 1000))\n\t\tformatString: #,0\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Best Seller Sales' = CALCULATE([Total Sales], FILTER(VALUES('Product'[Product ID]), [Total Sales] > 1000))\n\t\tformatString: #,0\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n### Why it matters\n\nFILTER over a whole table evaluates the measure once per row of the table. Over a fact table that is millions of measure evaluations to keep a few rows. Filtering the distinct values of one column instead evaluates the measure once per value, usually thousands of times fewer, and produces the same rows.\n\n### How to fix it\n\nIterate the column the answer actually varies by, not the table:\n\n```\nBest Seller Sales = CALCULATE ( [Total Sales], FILTER ( VALUES ( 'Product'[Product ID] ), [Total Sales] > 1000 ) )\n```\n\nVALUES respects the filter already on the column; swap in ALL to ignore it. Pick the column with the fewest distinct values that still gives the right answer, and note that passing a column also narrows what the filter carries into CALCULATE, one column's values rather than whole rows of the table, so the rewrite pays even where the column you iterate is the table's key. In Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column and a calculation item are edited the same way. In the TMDL file, edit the expression after `measure 'Best Seller Sales' =`, after `column Name =` for a calculated column, or after `calculationItem Name =` in the calculation group.\n\n### When to ignore it\n\nWhere the measure's value depends on more than one column of the table, no single column's distinct values reproduce the row set, and iterating the table is the honest form. Sales per product and store is the usual shape: iterate both columns together rather than the table if you can, and leave the finding alone if you cannot. The finding is also worth less over a small dimension, where the table has a few hundred rows and the column a few dozen distinct values, than over a fact table.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = FILTER_MEASURE_VALUES_BY_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"FILTER_MEASURE_VALUES_BY_COLUMNS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Only the first filter argument is checked, and only when the expression before it contains no comma. `CALCULATE(DIVIDE([A], [B]), FILTER(...))` passes, and so does a FILTER that comes after another filter argument.\n- The predicate only has to start with a bracketed name, so a bare column reference, `FILTER('Product', [Category] = \"Bikes\")`, is reported here as well.\n- Table names must contain only letters, digits, spaces, and underscores.\n- CALCULATETABLE is matched by a second pattern of its own, with the same shape.\n- Function names are matched in any letter case and with any spacing before the parenthesis.\n- The expression is read as raw text, so a CALCULATE and FILTER shape written inside a string literal or a comment counts.\n\nRead more: https://pbiplint.com/rules/filter-measure-values-by-columns",
  },
  FIRST_LETTER_OF_OBJECTS_MUST_BE_CAPITALIZED: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'total sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nObject names are the model's user interface: they appear in the field list, on axis labels, in tooltips, and in every export, and nothing capitalizes them for you. A field list that mixes \"Sales Amount\" with \"total cost\" reads as unfinished, and it tells a report author that the two fields came from different places and may not be equally trustworthy. Capitalizing the first letter costs nothing, survives every refresh, and is the convention nearly every published model follows. A name starting with a digit or a symbol is not flagged, because those characters have no upper case form.\n\nHow to fix it\n\nIn Power BI Desktop, double-click the object in the Data pane and retype the name, or select it and edit Name in the Properties pane of the model view. In the TMDL file the name is on the declaration line, so measure 'total sales' = becomes measure 'Total Sales' =. Renaming in Desktop carries the new name into the visuals bound to the object and into the DAX that references it; a hand edit in the file does not, so open the report and check its visuals after one.\n\nWhen to ignore it\n\nA name that is lower case on purpose is the exception worth keeping: eCommerce Orders, iPhone Sales, and anything else whose spelling belongs to a brand rather than to your style guide. Capitalizing those makes them wrong rather than tidy. Outside that, a lower case first letter is a slip, and the rule is reporting it before a reader does.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = FIRST_LETTER_OF_OBJECTS_MUST_BE_CAPITALIZED under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"FIRST_LETTER_OF_OBJECTS_MUST_BE_CAPITALIZED\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Data columns are not in scope; of the column kinds only calculated columns and calculated table columns are checked. Levels, partitions, perspectives, roles, named expressions, and calculation items are not checked either, so a lower case calculation item is not reported even when its calculation group is.\n- The first character is compared with its own upper case form, so a name that starts with a space is not reported here. OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE and TRIM_OBJECT_NAMES are the rules that read that one.\n\nRead more: https://pbiplint.com/rules/first-letter-of-objects-must-be-capitalized",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'total sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nObject names are the model's user interface: they appear in the field list, on axis labels, in tooltips, and in every export, and nothing capitalizes them for you. A field list that mixes \"Sales Amount\" with \"total cost\" reads as unfinished, and it tells a report author that the two fields came from different places and may not be equally trustworthy. Capitalizing the first letter costs nothing, survives every refresh, and is the convention nearly every published model follows. A name starting with a digit or a symbol is not flagged, because those characters have no upper case form.\n\n### How to fix it\n\nIn Power BI Desktop, double-click the object in the Data pane and retype the name, or select it and edit Name in the Properties pane of the model view. In the TMDL file the name is on the declaration line, so `measure 'total sales' =` becomes `measure 'Total Sales' =`. Renaming in Desktop carries the new name into the visuals bound to the object and into the DAX that references it; a hand edit in the file does not, so open the report and check its visuals after one.\n\n### When to ignore it\n\nA name that is lower case on purpose is the exception worth keeping: eCommerce Orders, iPhone Sales, and anything else whose spelling belongs to a brand rather than to your style guide. Capitalizing those makes them wrong rather than tidy. Outside that, a lower case first letter is a slip, and the rule is reporting it before a reader does.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = FIRST_LETTER_OF_OBJECTS_MUST_BE_CAPITALIZED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"FIRST_LETTER_OF_OBJECTS_MUST_BE_CAPITALIZED\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Data columns are not in scope; of the column kinds only calculated columns and calculated table columns are checked. Levels, partitions, perspectives, roles, named expressions, and calculation items are not checked either, so a lower case calculation item is not reported even when its calculation group is.\n- The first character is compared with its own upper case form, so a name that starts with a space is not reported here. `OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE` and `TRIM_OBJECT_NAMES` are the rules that read that one.\n\nRead more: https://pbiplint.com/rules/first-letter-of-objects-must-be-capitalized",
  },
  FIX_REFERENTIAL_INTEGRITY_VIOLATIONS: {
    text: "Why it matters\n\nEvery orphan key is grouped under a single blank row of the dimension, so slicers grow a blank entry, totals include amounts that no category explains, and a filter on any dimension attribute silently drops those rows. The blank row is also added to the dimension in memory on every refresh.\n\nHow to fix it\n\nFind the orphans first. In Power BI Desktop's DAX query view, run a query such as EVALUATE EXCEPT(VALUES('Sales'[Product Key]), VALUES('Product'[Product Key])) for each relationship you suspect, which lists the keys the dimension is missing. Then fix the data where it is loaded: add the missing rows to the dimension query, or add an Unknown row to the dimension and map the orphan keys to it in Power Query or in the warehouse view behind it. Where the orphans are legitimate and the dimension cannot grow, filter the fact rows out in Power Query instead, so the blank member never appears. DAX Studio's VertiPaq Analyzer reads the violation count for every relationship at once if you would rather start from a list than a query per relationship.\n\nQuirks\n\n- The source rule reads a Vertipaq_RIViolationInvalidRows annotation that a Tabular Editor script writes onto the model after loading VertiPaq statistics. A project's files never carry that annotation, which is why pbiplint lists the rule rather than running it.\n\nRead more: https://pbiplint.com/rules/fix-referential-integrity-violations",
    markdown:
      "### Why it matters\n\nEvery orphan key is grouped under a single blank row of the dimension, so slicers grow a blank entry, totals include amounts that no category explains, and a filter on any dimension attribute silently drops those rows. The blank row is also added to the dimension in memory on every refresh.\n\n### How to fix it\n\nFind the orphans first. In Power BI Desktop's DAX query view, run a query such as `EVALUATE EXCEPT(VALUES('Sales'[Product Key]), VALUES('Product'[Product Key]))` for each relationship you suspect, which lists the keys the dimension is missing. Then fix the data where it is loaded: add the missing rows to the dimension query, or add an Unknown row to the dimension and map the orphan keys to it in Power Query or in the warehouse view behind it. Where the orphans are legitimate and the dimension cannot grow, filter the fact rows out in Power Query instead, so the blank member never appears. DAX Studio's VertiPaq Analyzer reads the violation count for every relationship at once if you would rather start from a list than a query per relationship.\n\n### Quirks\n\n- The source rule reads a `Vertipaq_RIViolationInvalidRows` annotation that a Tabular Editor script writes onto the model after loading VertiPaq statistics. A project's files never carry that annotation, which is why pbiplint lists the rule rather than running it.\n\nRead more: https://pbiplint.com/rules/fix-referential-integrity-violations",
  },
  "FORMAT_FLAG_COLUMNS_AS_YES/NO_VALUE_STRINGS": {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn IsReturned\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: IsReturned\n\n\tcolumn 'Priority Flag'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Priority Flag\n\nAfter the fix\n\ntable Sales\n\tcolumn IsReturned\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: IsReturned\n\n\tcolumn 'Priority Flag'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Priority Flag\n\nWhy it matters\n\nA 0 or 1 in a slicer, a legend, or a table column tells the reader nothing without a lookup, and a whole-number flag is summed by default, so a card labeled Is Active shows a count of true rows that looks like something else. Yes and No read correctly everywhere and cannot be aggregated by accident.\n\nHow to fix it\n\nThe values have to change, not just the type, so the fix lives upstream of the model. In Power BI Desktop, choose Transform data, select the query, and either add a conditional column that returns Yes or No or use Replace Values on the column itself, then set the column's type to Text in Power Query. Where the query reads a view or a stored procedure, do the same in the select list and the model gets the text column already formed. The Data type box under Column tools changes the type in place on an import model but leaves the values as 0 and 1, so it is not the fix on its own. If a measure counts the flag, keep the numeric column and hide it, which also takes it out of this rule's reach.\n\nWhen to ignore it\n\nA column whose type is already boolean is the common false alarm: Power BI shows it as True and False, which reads as well as Yes and No, and the rule reports it only because it tests for text. The name tests catch words that are not flags at all, so a whole-number Issue Count or Isotope Number is noise on the Is side. The case worth acting on is the one the rule was written for: a visible 0 and 1 column that a report author has to decode.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = FORMAT_FLAG_COLUMNS_AS_YES/NO_VALUE_STRINGS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"FORMAT_FLAG_COLUMNS_AS_YES/NO_VALUE_STRINGS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Both name tests are case-sensitive. The prefix is the two characters Is, so a whole-number column called Island or Issue Count is reported, and one called isActive is not.\n- The suffix is a space followed by Flag, so Priority Flag is reported and PriorityFlag is not.\n- Hidden columns, and columns in hidden tables, are skipped by both halves.\n- The Is half needs the type to be exactly whole number, so a decimal IsActive is not reported. The Flag half fires on every type that is not text, boolean and DateTime included.\n\nRead more: https://pbiplint.com/rules/format-flag-columns-as-yes-no-value-strings",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn IsReturned\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: IsReturned\n\n\tcolumn 'Priority Flag'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Priority Flag\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn IsReturned\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: IsReturned\n\n\tcolumn 'Priority Flag'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Priority Flag\n```\n\n### Why it matters\n\nA 0 or 1 in a slicer, a legend, or a table column tells the reader nothing without a lookup, and a whole-number flag is summed by default, so a card labeled Is Active shows a count of true rows that looks like something else. Yes and No read correctly everywhere and cannot be aggregated by accident.\n\n### How to fix it\n\nThe values have to change, not just the type, so the fix lives upstream of the model. In Power BI Desktop, choose Transform data, select the query, and either add a conditional column that returns Yes or No or use Replace Values on the column itself, then set the column's type to Text in Power Query. Where the query reads a view or a stored procedure, do the same in the select list and the model gets the text column already formed. The Data type box under Column tools changes the type in place on an import model but leaves the values as 0 and 1, so it is not the fix on its own. If a measure counts the flag, keep the numeric column and hide it, which also takes it out of this rule's reach.\n\n### When to ignore it\n\nA column whose type is already boolean is the common false alarm: Power BI shows it as True and False, which reads as well as Yes and No, and the rule reports it only because it tests for text. The name tests catch words that are not flags at all, so a whole-number Issue Count or Isotope Number is noise on the Is side. The case worth acting on is the one the rule was written for: a visible 0 and 1 column that a report author has to decode.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = FORMAT_FLAG_COLUMNS_AS_YES/NO_VALUE_STRINGS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"FORMAT_FLAG_COLUMNS_AS_YES/NO_VALUE_STRINGS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Both name tests are case-sensitive. The prefix is the two characters Is, so a whole-number column called Island or Issue Count is reported, and one called isActive is not.\n- The suffix is a space followed by Flag, so Priority Flag is reported and PriorityFlag is not.\n- Hidden columns, and columns in hidden tables, are skipped by both halves.\n- The Is half needs the type to be exactly whole number, so a decimal IsActive is not reported. The Flag half fires on every type that is not text, boolean and DateTime included.\n\nRead more: https://pbiplint.com/rules/format-flag-columns-as-yes-no-value-strings",
  },
  HIDE_FACT_TABLE_COLUMNS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nOnce a measure exists for a column, the column itself is the wrong thing to drag onto a visual: it produces an implicit sum that may not match the measure, ignores whatever logic the measure adds, and sits in the field list right next to the measure under a similar name. Hiding the column leaves one correct choice.\n\nHow to fix it\n\nIn Power BI Desktop, open the model view, select the column, and turn on Is hidden in the Properties pane, or right-click the column in the Data pane of report view and choose Hide. In the TMDL file, add isHidden under the column. The column is still loaded, still refreshed, and still available to every measure and relationship; it only leaves the field list.\n\nWhen to ignore it\n\nA numeric column readers use as an attribute rather than as a number is the case to keep visible: a Year on a date table, a Unit Price a report author slices by, a Rating people put on an axis. That a measure also aggregates the column somewhere does not make it the wrong field to pick. The rule does not test whether the table is a fact table either, so a dimension attribute that one measure happens to sum is reported on the same terms as a fact column. What to check before hiding is whether a report already binds a visual to the column, because hiding it does not break that visual but does remove the field from the list for whoever edits it next.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = HIDE_FACT_TABLE_COLUMNS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"HIDE_FACT_TABLE_COLUMNS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Only fully qualified references count, and the quote marks around the table name are optional, so SUM(Sales[Amount]) matches as well as SUM('Sales'[Amount]). A bare SUM([Amount]) inside a measure on the same table does not.\n- Nothing may come between the column reference and the aggregation's closing parenthesis, so SUM('Sales'[Amount] * 2) is not matched. Spaces after the function name and inside the parentheses are allowed, and the function name matches in any letter case.\n- The measure may live on any table in the model, not only on the column's own table.\n- The expression is read as raw text, so an aggregation written inside a string literal or a comment counts.\n- Only numeric columns are in scope, so COUNTA('Sales'[Region]) over a text column is not reported.\n- A visible column in a hidden table is still reported: the rule tests the column's own visibility, not the table's.\n\nRead more: https://pbiplint.com/rules/hide-fact-table-columns",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nOnce a measure exists for a column, the column itself is the wrong thing to drag onto a visual: it produces an implicit sum that may not match the measure, ignores whatever logic the measure adds, and sits in the field list right next to the measure under a similar name. Hiding the column leaves one correct choice.\n\n### How to fix it\n\nIn Power BI Desktop, open the model view, select the column, and turn on Is hidden in the Properties pane, or right-click the column in the Data pane of report view and choose Hide. In the TMDL file, add `isHidden` under the column. The column is still loaded, still refreshed, and still available to every measure and relationship; it only leaves the field list.\n\n### When to ignore it\n\nA numeric column readers use as an attribute rather than as a number is the case to keep visible: a Year on a date table, a Unit Price a report author slices by, a Rating people put on an axis. That a measure also aggregates the column somewhere does not make it the wrong field to pick. The rule does not test whether the table is a fact table either, so a dimension attribute that one measure happens to sum is reported on the same terms as a fact column. What to check before hiding is whether a report already binds a visual to the column, because hiding it does not break that visual but does remove the field from the list for whoever edits it next.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = HIDE_FACT_TABLE_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"HIDE_FACT_TABLE_COLUMNS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Only fully qualified references count, and the quote marks around the table name are optional, so `SUM(Sales[Amount])` matches as well as `SUM('Sales'[Amount])`. A bare `SUM([Amount])` inside a measure on the same table does not.\n- Nothing may come between the column reference and the aggregation's closing parenthesis, so `SUM('Sales'[Amount] * 2)` is not matched. Spaces after the function name and inside the parentheses are allowed, and the function name matches in any letter case.\n- The measure may live on any table in the model, not only on the column's own table.\n- The expression is read as raw text, so an aggregation written inside a string literal or a comment counts.\n- Only numeric columns are in scope, so `COUNTA('Sales'[Region])` over a text column is not reported.\n- A visible column in a hidden table is still reported: the rule tests the column's own visibility, not the table's.\n\nRead more: https://pbiplint.com/rules/hide-fact-table-columns",
  },
  HIDE_FOREIGN_KEYS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tsourceColumn: ProductKey\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product Key'\n\ttoColumn: Product.'Product ID'\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductKey\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product Key'\n\ttoColumn: Product.'Product ID'\n\nWhy it matters\n\nA key column on the many side of a relationship carries no meaning for a report author: the values are surrogate integers, and grouping by the fact table's key gives one row per key value labeled with a number nobody recognizes. Leaving it visible also puts two versions of the same field in the field list, one on the fact table and one on the dimension, and only the dimension's version filters the way people expect. Hiding the key removes the wrong choice from the field list without changing anything about how the model behaves.\n\nHow to fix it\n\nIn Power BI Desktop, open the model view, select the column, and turn on Is hidden in the Properties pane, or right-click the column in the Data pane and choose Hide in report view. In the TMDL file, add isHidden under the column. A hidden column still takes part in the relationship and still filters. It only leaves the field list.\n\nWhen to ignore it\n\nA key that people search or filter by in its own right can stay visible, for example an order number that is both the key to an Orders dimension and a value a reader types into a slicer. Ignore the finding on that column and leave the rule on for the rest of the model. A bare surrogate key is never something a report author needs to see.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = HIDE_FOREIGN_KEYS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"HIDE_FOREIGN_KEYS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The source rule compares from-column names only, not table plus column, so a dimension's key that shares a name with the fact table's foreign key is flagged too. pbiplint keeps this to match Tabular Editor. The example above names the two columns differently for that reason.\n\nRead more: https://pbiplint.com/rules/hide-foreign-keys",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tsourceColumn: ProductKey\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product Key'\n\ttoColumn: Product.'Product ID'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductKey\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product Key'\n\ttoColumn: Product.'Product ID'\n```\n\n### Why it matters\n\nA key column on the many side of a relationship carries no meaning for a report author: the values are surrogate integers, and grouping by the fact table's key gives one row per key value labeled with a number nobody recognizes. Leaving it visible also puts two versions of the same field in the field list, one on the fact table and one on the dimension, and only the dimension's version filters the way people expect. Hiding the key removes the wrong choice from the field list without changing anything about how the model behaves.\n\n### How to fix it\n\nIn Power BI Desktop, open the model view, select the column, and turn on Is hidden in the Properties pane, or right-click the column in the Data pane and choose Hide in report view. In the TMDL file, add `isHidden` under the column. A hidden column still takes part in the relationship and still filters. It only leaves the field list.\n\n### When to ignore it\n\nA key that people search or filter by in its own right can stay visible, for example an order number that is both the key to an Orders dimension and a value a reader types into a slicer. Ignore the finding on that column and leave the rule on for the rest of the model. A bare surrogate key is never something a report author needs to see.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = HIDE_FOREIGN_KEYS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"HIDE_FOREIGN_KEYS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The source rule compares from-column names only, not table plus column, so a dimension's key that shares a name with the fact table's foreign key is flagged too. pbiplint keeps this to match Tabular Editor. The example above names the two columns differently for that reason.\n\nRead more: https://pbiplint.com/rules/hide-foreign-keys",
  },
  INACTIVE_RELATIONSHIPS_THAT_ARE_NEVER_ACTIVATED: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tsourceColumn: OrderDate\n\tcolumn 'Ship Date'\n\t\tdataType: dateTime\n\t\tsourceColumn: ShipDate\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tsourceColumn: Date\n\nrelationship Sales_Date_Order\n\tfromColumn: Sales.'Order Date'\n\ttoColumn: Date.Date\n\nrelationship Sales_Date_Ship\n\tisActive: false\n\tfromColumn: Sales.'Ship Date'\n\ttoColumn: Date.Date\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tsourceColumn: OrderDate\n\tcolumn 'Ship Date'\n\t\tdataType: dateTime\n\t\tsourceColumn: ShipDate\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Shipped Sales' = CALCULATE([Total Sales], USERELATIONSHIP(Sales[Ship Date], 'Date'[Date]))\n\t\tformatString: #,0\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tsourceColumn: Date\n\nrelationship Sales_Date_Order\n\tfromColumn: Sales.'Order Date'\n\ttoColumn: Date.Date\n\nrelationship Sales_Date_Ship\n\tisActive: false\n\tfromColumn: Sales.'Ship Date'\n\ttoColumn: Date.Date\n\nWhy it matters\n\nAn inactive relationship does nothing on its own. It exists so a measure can switch it on with USERELATIONSHIP, typically for a second date on a fact table. If no measure does, the relationship is either a leftover from a design that changed or a plan that was never finished, and a report author who sees the dotted line in the model view will assume the filter works.\n\nHow to fix it\n\nWrite the measure the relationship was put there for, so the second date has something that reads it:\n\nShipped Sales = CALCULATE ( [Total Sales], USERELATIONSHIP ( Sales[Ship Date], 'Date'[Date] ) )\n\nIn Power BI Desktop, choose New measure on the Home ribbon and type the expression in the formula bar. In the TMDL file, add the measure block to the fact table. Name the columns in the order the relationship declares them, its from column first. DAX takes them either way round, but only that order counts as activation here.\n\nWhere nothing needs the relationship, delete it instead: open the model view, right-click the dotted line, and choose Delete, or remove its relationship block from the TMDL file.\n\nWhen to ignore it\n\npbiplint reads the semantic model, not the reports built on it. A report-level measure in a live-connected report can call USERELATIONSHIP, and this rule cannot see it, so check the reports before deleting a relationship that looks unused. The same goes for a relationship activated from a calculated column, a calculated table, or a row-level security filter: none of those is scanned here, and a finding on one of them is noise. A relationship added this week for measures that are still being written is a fair thing to leave alone for a sprint.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = INACTIVE_RELATIONSHIPS_THAT_ARE_NEVER_ACTIVATED under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"INACTIVE_RELATIONSHIPS_THAT_ARE_NEVER_ACTIVATED\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Only USERELATIONSHIP(from column, to column) counts as activation; the reversed argument order does not, even though DAX accepts it.\n- Only measures and calculation items are scanned. A USERELATIONSHIP call in a calculated column, a calculated table, or a row-level security filter does not count as activation.\n- The call is matched as text, in any letter case, so a USERELATIONSHIP written inside a string literal or a comment counts as activating the relationship.\n- Either table name may be written bare or in single quotes, and any spacing around the comma is accepted.\n- pbiplint escapes table and column names before building the pattern, which the source rule does not, so names with parentheses cannot break the check.\n\nRead more: https://pbiplint.com/rules/inactive-relationships-that-are-never-activated",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tsourceColumn: OrderDate\n\tcolumn 'Ship Date'\n\t\tdataType: dateTime\n\t\tsourceColumn: ShipDate\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tsourceColumn: Date\n\nrelationship Sales_Date_Order\n\tfromColumn: Sales.'Order Date'\n\ttoColumn: Date.Date\n\nrelationship Sales_Date_Ship\n\tisActive: false\n\tfromColumn: Sales.'Ship Date'\n\ttoColumn: Date.Date\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tsourceColumn: OrderDate\n\tcolumn 'Ship Date'\n\t\tdataType: dateTime\n\t\tsourceColumn: ShipDate\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Shipped Sales' = CALCULATE([Total Sales], USERELATIONSHIP(Sales[Ship Date], 'Date'[Date]))\n\t\tformatString: #,0\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tsourceColumn: Date\n\nrelationship Sales_Date_Order\n\tfromColumn: Sales.'Order Date'\n\ttoColumn: Date.Date\n\nrelationship Sales_Date_Ship\n\tisActive: false\n\tfromColumn: Sales.'Ship Date'\n\ttoColumn: Date.Date\n```\n\n### Why it matters\n\nAn inactive relationship does nothing on its own. It exists so a measure can switch it on with USERELATIONSHIP, typically for a second date on a fact table. If no measure does, the relationship is either a leftover from a design that changed or a plan that was never finished, and a report author who sees the dotted line in the model view will assume the filter works.\n\n### How to fix it\n\nWrite the measure the relationship was put there for, so the second date has something that reads it:\n\n```\nShipped Sales = CALCULATE ( [Total Sales], USERELATIONSHIP ( Sales[Ship Date], 'Date'[Date] ) )\n```\n\nIn Power BI Desktop, choose New measure on the Home ribbon and type the expression in the formula bar. In the TMDL file, add the `measure` block to the fact table. Name the columns in the order the relationship declares them, its from column first. DAX takes them either way round, but only that order counts as activation here.\n\nWhere nothing needs the relationship, delete it instead: open the model view, right-click the dotted line, and choose Delete, or remove its `relationship` block from the TMDL file.\n\n### When to ignore it\n\npbiplint reads the semantic model, not the reports built on it. A report-level measure in a live-connected report can call USERELATIONSHIP, and this rule cannot see it, so check the reports before deleting a relationship that looks unused. The same goes for a relationship activated from a calculated column, a calculated table, or a row-level security filter: none of those is scanned here, and a finding on one of them is noise. A relationship added this week for measures that are still being written is a fair thing to leave alone for a sprint.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = INACTIVE_RELATIONSHIPS_THAT_ARE_NEVER_ACTIVATED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"INACTIVE_RELATIONSHIPS_THAT_ARE_NEVER_ACTIVATED\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Only `USERELATIONSHIP(from column, to column)` counts as activation; the reversed argument order does not, even though DAX accepts it.\n- Only measures and calculation items are scanned. A USERELATIONSHIP call in a calculated column, a calculated table, or a row-level security filter does not count as activation.\n- The call is matched as text, in any letter case, so a USERELATIONSHIP written inside a string literal or a comment counts as activating the relationship.\n- Either table name may be written bare or in single quotes, and any spacing around the comma is accepted.\n- pbiplint escapes table and column names before building the pattern, which the source rule does not, so names with parentheses cannot break the check.\n\nRead more: https://pbiplint.com/rules/inactive-relationships-that-are-never-activated",
  },
  INTEGER_FORMATTING: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Order Count' = COUNTROWS('Sales')\n\t\tformatString: 0\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Order Count' = COUNTROWS('Sales')\n\t\tformatString: #,0\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nAn unformatted whole number is rendered with whatever default the client picks, so a measure that should read 1,234,567 can appear as 1234567 and leave the reader counting digits. Thousands separators are the single biggest readability win on a card or in a table column, and setting the format on the measure means every visual inherits it instead of each report author fixing it by hand and getting it slightly different. Currency and percentage measures follow their own conventions, which is why a format string containing $ or % is left alone by this rule.\n\nHow to fix it\n\nSet a format string that matches what the measure represents: #,0 for counts and other whole numbers, a currency format such as $#,0.00 for money, or #,0.0%;-#,0.0%;#,0.0% for percentages, which is the exact string PERCENTAGE_FORMATTING expects. In Power BI Desktop, select the measure in the Data pane and type the string into the Format box under Measure tools. In the TMDL file the property is formatString: #,0 under the measure.\n\nWhen to ignore it\n\nA measure already formatted the way its number deserves is the usual false alarm. Only two plain number formats pass, so an average carrying two decimals as #,0.00, a rate written 0.000, and a price in a currency whose symbol is not the dollar sign are all reported although each is formatted on purpose. Look at the detail on the finding before deciding: no format string is always worth fixing, while a format string the rule merely does not recognize is a question of house style. A measure that returns text rather than a number has no format to set at all.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = INTEGER_FORMATTING under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"INTEGER_FORMATTING\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The currency and percentage escape hatches are substring tests over the whole format string, so any string containing $ or % anywhere passes, whatever else it says.\n- Currency formats that do not use the $ character, for example €#,0.00, are reported as though they were unformatted numbers, because the source rule looks for $ only.\n- A measure with a dynamic format string but no static format string is reported, because the source rule reads only the static format string.\n- There is no visibility test. A hidden measure, and a measure on a hidden table, are reported on the same terms as a visible one.\n\nRead more: https://pbiplint.com/rules/integer-formatting",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Order Count' = COUNTROWS('Sales')\n\t\tformatString: 0\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Order Count' = COUNTROWS('Sales')\n\t\tformatString: #,0\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nAn unformatted whole number is rendered with whatever default the client picks, so a measure that should read 1,234,567 can appear as 1234567 and leave the reader counting digits. Thousands separators are the single biggest readability win on a card or in a table column, and setting the format on the measure means every visual inherits it instead of each report author fixing it by hand and getting it slightly different. Currency and percentage measures follow their own conventions, which is why a format string containing $ or % is left alone by this rule.\n\n### How to fix it\n\nSet a format string that matches what the measure represents: `#,0` for counts and other whole numbers, a currency format such as `$#,0.00` for money, or `#,0.0%;-#,0.0%;#,0.0%` for percentages, which is the exact string `PERCENTAGE_FORMATTING` expects. In Power BI Desktop, select the measure in the Data pane and type the string into the Format box under Measure tools. In the TMDL file the property is `formatString: #,0` under the measure.\n\n### When to ignore it\n\nA measure already formatted the way its number deserves is the usual false alarm. Only two plain number formats pass, so an average carrying two decimals as `#,0.00`, a rate written `0.000`, and a price in a currency whose symbol is not the dollar sign are all reported although each is formatted on purpose. Look at the detail on the finding before deciding: `no format string` is always worth fixing, while a format string the rule merely does not recognize is a question of house style. A measure that returns text rather than a number has no format to set at all.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = INTEGER_FORMATTING` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"INTEGER_FORMATTING\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The currency and percentage escape hatches are substring tests over the whole format string, so any string containing `$` or `%` anywhere passes, whatever else it says.\n- Currency formats that do not use the `$` character, for example `€#,0.00`, are reported as though they were unformatted numbers, because the source rule looks for `$` only.\n- A measure with a dynamic format string but no static format string is reported, because the source rule reads only the static format string.\n- There is no visibility test. A hidden measure, and a measure on a hidden table, are reported on the same terms as a visible one.\n\nRead more: https://pbiplint.com/rules/integer-formatting",
  },
  ISAVAILABLEINMDX_FALSE_NONATTRIBUTE_COLUMNS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: ProductKey\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tisAvailableInMdx: false\n\t\tsummarizeBy: none\n\t\tsourceColumn: ProductKey\n\nWhy it matters\n\nWhen IsAvailableInMdx is true the engine builds an attribute hierarchy for the column at every refresh: a sorted structure that lets Excel and other MDX clients browse the column's values. A hidden column is never browsed, so the structure is built, stored, and rebuilt for nothing. On wide tables with many hidden keys and helper columns that is measurable refresh time and memory.\n\nHow to fix it\n\nAdd isAvailableInMdx: false under the column in its table's TMDL file. Power BI Desktop has no setting for the property and never writes it, but it keeps the value once it is in the file, and it keeps it the same way on an import table and a DirectQuery one. The other way to clear a finding is to decide the column should not be hidden after all: clear Is hidden in the Properties pane, or remove isHidden from under the column, and the rule stops reading it, as long as its table is visible too. Where a table has dozens of hidden keys, Tabular Editor's property grid sets the property on every selected column in one edit, which is quicker than the same change repeated down a file.\n\nWhen to ignore it\n\nSize is the first judgment. The saving is roughly proportional to the column's distinct count, so a hidden flag with two values is not worth an edit and a hidden key with a million is. Work down the list by cardinality and stop where the numbers get small. A variation is the one case where acting on the finding can break something: pbiplint reads a variation's default column only, so a hidden column a variation reaches through its default hierarchy is reported here, and setting the property to false on it takes away the attribute hierarchy the variation needs. Check the date table's hidden columns against its variations before you touch them. A column you are about to unhide is a fair thing to leave, since unhiding it clears the finding anyway, as long as its table is visible.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = ISAVAILABLEINMDX_FALSE_NONATTRIBUTE_COLUMNS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"ISAVAILABLEINMDX_FALSE_NONATTRIBUTE_COLUMNS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- A column with no isAvailableInMdx line counts as true, because that is the default pbiplint applies wherever the property is absent. Power BI Desktop never writes the property, so a Desktop-authored model gets a finding for every hidden column the rest of the condition does not excuse, until they are set by hand.\n- Visibility is the column's own isHidden or its table's. A visible column in a hidden table is reported.\n- Both ends of a sort-by pair are out of scope: the column another column sorts by, and the column that names one in sortByColumn.\n- Variations are matched on the default column alone, so a column a variation reaches only through its default hierarchy is not protected here.\n- Relationships are not read. A hidden foreign key, which is exactly what HIDE_FOREIGN_KEYS asks you to create, is reported here.\n\nRead more: https://pbiplint.com/rules/isavailableinmdx-false-nonattribute-columns",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: ProductKey\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tisAvailableInMdx: false\n\t\tsummarizeBy: none\n\t\tsourceColumn: ProductKey\n```\n\n### Why it matters\n\nWhen IsAvailableInMdx is true the engine builds an attribute hierarchy for the column at every refresh: a sorted structure that lets Excel and other MDX clients browse the column's values. A hidden column is never browsed, so the structure is built, stored, and rebuilt for nothing. On wide tables with many hidden keys and helper columns that is measurable refresh time and memory.\n\n### How to fix it\n\nAdd `isAvailableInMdx: false` under the column in its table's TMDL file. Power BI Desktop has no setting for the property and never writes it, but it keeps the value once it is in the file, and it keeps it the same way on an import table and a DirectQuery one. The other way to clear a finding is to decide the column should not be hidden after all: clear Is hidden in the Properties pane, or remove `isHidden` from under the column, and the rule stops reading it, as long as its table is visible too. Where a table has dozens of hidden keys, Tabular Editor's property grid sets the property on every selected column in one edit, which is quicker than the same change repeated down a file.\n\n### When to ignore it\n\nSize is the first judgment. The saving is roughly proportional to the column's distinct count, so a hidden flag with two values is not worth an edit and a hidden key with a million is. Work down the list by cardinality and stop where the numbers get small. A variation is the one case where acting on the finding can break something: pbiplint reads a variation's default column only, so a hidden column a variation reaches through its default hierarchy is reported here, and setting the property to false on it takes away the attribute hierarchy the variation needs. Check the date table's hidden columns against its variations before you touch them. A column you are about to unhide is a fair thing to leave, since unhiding it clears the finding anyway, as long as its table is visible.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = ISAVAILABLEINMDX_FALSE_NONATTRIBUTE_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"ISAVAILABLEINMDX_FALSE_NONATTRIBUTE_COLUMNS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- A column with no `isAvailableInMdx` line counts as true, because that is the default pbiplint applies wherever the property is absent. Power BI Desktop never writes the property, so a Desktop-authored model gets a finding for every hidden column the rest of the condition does not excuse, until they are set by hand.\n- Visibility is the column's own `isHidden` or its table's. A visible column in a hidden table is reported.\n- Both ends of a sort-by pair are out of scope: the column another column sorts by, and the column that names one in `sortByColumn`.\n- Variations are matched on the default column alone, so a column a variation reaches only through its default hierarchy is not protected here.\n- Relationships are not read. A hidden foreign key, which is exactly what `HIDE_FOREIGN_KEYS` asks you to create, is reported here.\n\nRead more: https://pbiplint.com/rules/isavailableinmdx-false-nonattribute-columns",
  },
  LARGE_TABLES_SHOULD_BE_PARTITIONED: {
    text: "Why it matters\n\nA single partition means every refresh reloads the whole table, and a 25-million-row table reloaded nightly is the usual reason a refresh runs for hours or times out. With partitions, only the ones whose data changed are processed, and a failed refresh costs one partition rather than the table. In Power BI that is what incremental refresh sets up for you.\n\nHow to fix it\n\nFind the row count first. In Power BI Desktop's DAX query view, run a query such as EVALUATE ROW(\"rows\", COUNTROWS('Sales')) for each table you suspect. Then set up incremental refresh on the ones that are large: define the RangeStart and RangeEnd date parameters in Transform data, filter the table's date column between them, and close and apply; back in the report view, right-click the table in the Data pane, choose Incremental refresh, and set how much history to keep and how much of it to reload each time. In the TMDL file the result is a refreshPolicy block under the table beside its one partition, and the dated partitions themselves are created by the service when the model is refreshed after publishing, so a project's files keep showing a single partition. A table that is large but has no date column to range over is partitioned by hand instead, by writing one partition block per slice with its own filtered source. DAX Studio's VertiPaq Analyzer reads the row count of every table at once if you would rather start from a list than a query per table, and if you already use Tabular Editor, the walkthrough under Links loads the same statistics into its Best Practice Analyzer, which can then run this rule directly.\n\nQuirks\n\n- The source rule reads a Vertipaq_RowCount annotation that a Tabular Editor script writes onto the model after loading VertiPaq statistics. A project's files never carry that annotation, which is why pbiplint lists the rule rather than running it.\n- The partition test is for exactly one partition, so a 100-million-row table already split in two is not reported however unbalanced the split is.\n- The threshold is a flat 25 million rows. Nothing about the table's width, its column cardinality, or how long its refresh actually takes enters into it.\n\nRead more: https://pbiplint.com/rules/large-tables-should-be-partitioned",
    markdown:
      "### Why it matters\n\nA single partition means every refresh reloads the whole table, and a 25-million-row table reloaded nightly is the usual reason a refresh runs for hours or times out. With partitions, only the ones whose data changed are processed, and a failed refresh costs one partition rather than the table. In Power BI that is what incremental refresh sets up for you.\n\n### How to fix it\n\nFind the row count first. In Power BI Desktop's DAX query view, run a query such as `EVALUATE ROW(\"rows\", COUNTROWS('Sales'))` for each table you suspect. Then set up incremental refresh on the ones that are large: define the RangeStart and RangeEnd date parameters in Transform data, filter the table's date column between them, and close and apply; back in the report view, right-click the table in the Data pane, choose Incremental refresh, and set how much history to keep and how much of it to reload each time. In the TMDL file the result is a `refreshPolicy` block under the table beside its one partition, and the dated partitions themselves are created by the service when the model is refreshed after publishing, so a project's files keep showing a single partition. A table that is large but has no date column to range over is partitioned by hand instead, by writing one `partition` block per slice with its own filtered `source`. DAX Studio's VertiPaq Analyzer reads the row count of every table at once if you would rather start from a list than a query per table, and if you already use Tabular Editor, the walkthrough under Links loads the same statistics into its Best Practice Analyzer, which can then run this rule directly.\n\n### Quirks\n\n- The source rule reads a `Vertipaq_RowCount` annotation that a Tabular Editor script writes onto the model after loading VertiPaq statistics. A project's files never carry that annotation, which is why pbiplint lists the rule rather than running it.\n- The partition test is for exactly one partition, so a 100-million-row table already split in two is not reported however unbalanced the split is.\n- The threshold is a flat 25 million rows. Nothing about the table's width, its column cardinality, or how long its refresh actually takes enters into it.\n\nRead more: https://pbiplint.com/rules/large-tables-should-be-partitioned",
  },
  "LIMIT_ROW_LEVEL_SECURITY_(RLS)_LOGIC": {
    text: "Example\n\nFires the rule\n\ntable Employee\n\tcolumn Email\n\t\tdataType: string\n\t\tsourceColumn: Email\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrole 'Regional Users'\n\tmodelPermission: read\n\n\ttablePermission Employee = UPPER('Employee'[Email]) = UPPER(USERPRINCIPALNAME())\n\nAfter the fix\n\ntable Employee\n\tcolumn Email\n\t\tdataType: string\n\t\tsourceColumn: EmailNormalized\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrole 'Regional Users'\n\tmodelPermission: read\n\n\ttablePermission Employee = 'Employee'[Email] = USERPRINCIPALNAME()\n\nWhy it matters\n\nA security filter runs on every query from every user in the role, and string functions in it are evaluated row by row on the secured table. A filter that compares a precomputed key column with equals is applied as a lookup instead. The string logic usually exists to derive a key from an email address or a code, which the source can produce once at load.\n\nHow to fix it\n\nPrecompute the value the filter is deriving, then compare it with equals. In Power BI Desktop, choose Transform data, select the query behind the secured table, and add the derived column there with Add Column, Custom Column, or better still add it to the view the query reads so every model gets it. Then, under Modeling, Manage roles, rewrite the filter as a plain comparison such as 'Employee'[Email] = USERPRINCIPALNAME(); in the TMDL file that is the text after the = on the role's tablePermission line. The example above is the common one: DAX compares text without regard to letter case, so the two UPPER calls were doing nothing the equals sign did not already do, and the fix is to delete them. Where the string work is real, for example taking the domain off an address, do it in the query and leave the filter as one comparison. The route is the same for an import table and a DirectQuery one, though on DirectQuery the derived column has to fold, so the source view is the safer place for it.\n\nWhen to ignore it\n\nWhere the function is applied to the user's name rather than to a column, the finding is noise. An expression such as 'Employee'[Domain] = RIGHT(USERPRINCIPALNAME(), LEN(USERPRINCIPALNAME()) - FIND(\"@\", USERPRINCIPALNAME())) evaluates the string work once per query, not once per row, which is the cost the rule is about. A small secured table is the second case: a few hundred rows of a security table cost little however the filter is written, so measure with the role applied before you rebuild a query. What is not worth ignoring is a string function applied to a column of a large fact or dimension table, because that is the row-by-row evaluation the rule was written for, and the table only gets bigger.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = LIMIT_ROW_LEVEL_SECURITY_(RLS)_LOGIC under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"LIMIT_ROW_LEVEL_SECURITY_(RLS)_LOGIC\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Spaces are removed before matching and the match is a substring, so BRIGHT( or L E F T( also match.\n- The five names are matched without regard to letter case, so upper( counts.\n- Only those five functions are matched. SUBSTITUTE, SEARCH, CONCATENATE, PATHCONTAINS, and the rest pass, however heavy the filter they sit in.\n- The finding is on the table, so a table filtered by three roles with string logic in each is reported once.\n- Calculated tables are in scope; calculation groups are not.\n\nRead more: https://pbiplint.com/rules/limit-row-level-security-rls-logic",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Employee\n\tcolumn Email\n\t\tdataType: string\n\t\tsourceColumn: Email\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrole 'Regional Users'\n\tmodelPermission: read\n\n\ttablePermission Employee = UPPER('Employee'[Email]) = UPPER(USERPRINCIPALNAME())\n```\n\n**After the fix**\n\n```tmdl\ntable Employee\n\tcolumn Email\n\t\tdataType: string\n\t\tsourceColumn: EmailNormalized\n\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\nrole 'Regional Users'\n\tmodelPermission: read\n\n\ttablePermission Employee = 'Employee'[Email] = USERPRINCIPALNAME()\n```\n\n### Why it matters\n\nA security filter runs on every query from every user in the role, and string functions in it are evaluated row by row on the secured table. A filter that compares a precomputed key column with equals is applied as a lookup instead. The string logic usually exists to derive a key from an email address or a code, which the source can produce once at load.\n\n### How to fix it\n\nPrecompute the value the filter is deriving, then compare it with equals. In Power BI Desktop, choose Transform data, select the query behind the secured table, and add the derived column there with Add Column, Custom Column, or better still add it to the view the query reads so every model gets it. Then, under Modeling, Manage roles, rewrite the filter as a plain comparison such as `'Employee'[Email] = USERPRINCIPALNAME()`; in the TMDL file that is the text after the `=` on the role's `tablePermission` line. The example above is the common one: DAX compares text without regard to letter case, so the two UPPER calls were doing nothing the equals sign did not already do, and the fix is to delete them. Where the string work is real, for example taking the domain off an address, do it in the query and leave the filter as one comparison. The route is the same for an import table and a DirectQuery one, though on DirectQuery the derived column has to fold, so the source view is the safer place for it.\n\n### When to ignore it\n\nWhere the function is applied to the user's name rather than to a column, the finding is noise. An expression such as `'Employee'[Domain] = RIGHT(USERPRINCIPALNAME(), LEN(USERPRINCIPALNAME()) - FIND(\"@\", USERPRINCIPALNAME()))` evaluates the string work once per query, not once per row, which is the cost the rule is about. A small secured table is the second case: a few hundred rows of a security table cost little however the filter is written, so measure with the role applied before you rebuild a query. What is not worth ignoring is a string function applied to a column of a large fact or dimension table, because that is the row-by-row evaluation the rule was written for, and the table only gets bigger.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = LIMIT_ROW_LEVEL_SECURITY_(RLS)_LOGIC` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"LIMIT_ROW_LEVEL_SECURITY_(RLS)_LOGIC\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Spaces are removed before matching and the match is a substring, so `BRIGHT(` or `L E F T(` also match.\n- The five names are matched without regard to letter case, so `upper(` counts.\n- Only those five functions are matched. SUBSTITUTE, SEARCH, CONCATENATE, PATHCONTAINS, and the rest pass, however heavy the filter they sit in.\n- The finding is on the table, so a table filtered by three roles with string logic in each is reported once.\n- Calculated tables are in scope; calculation groups are not.\n\nRead more: https://pbiplint.com/rules/limit-row-level-security-rls-logic",
  },
  "MANY-TO-MANY_RELATIONSHIPS_SHOULD_BE_SINGLE-DIRECTION": {
    text: "Example\n\nFires the rule\n\ntable Customer\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\ntable 'Regional Budget'\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Budget\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Budget\n\nrelationship Customer_RegionalBudget\n\tfromCardinality: many\n\ttoCardinality: many\n\tcrossFilteringBehavior: bothDirections\n\tfromColumn: Customer.Region\n\ttoColumn: 'Regional Budget'.Region\n\nAfter the fix\n\ntable Customer\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\ntable 'Regional Budget'\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Budget\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Budget\n\nrelationship Customer_RegionalBudget\n\tfromCardinality: many\n\ttoCardinality: many\n\tfromColumn: Customer.Region\n\ttoColumn: 'Regional Budget'.Region\n\nWhy it matters\n\nA many-to-many relationship has no unique key on either side, so the engine resolves it through a set of distinct values rather than a direct lookup. Making that relationship bi-directional as well lets filters travel back through the same expansion, and that is where filter ambiguity begins: as soon as two paths reach the same table, the result depends on which path the engine chooses, and totals stop agreeing with the sum of their parts. The extra direction also costs at query time, because every filter has to be expanded across the distinct values on both sides instead of one. Single direction keeps one predictable filter path and is the accepted default; add the reverse direction only where a specific report needs it and you have confirmed the model has no second path.\n\nHow to fix it\n\nIn Power BI Desktop, open the model view, double-click the relationship, and set Cross filter direction to Single in the Edit relationship dialog. In the TMDL file that is the crossFilteringBehavior: bothDirections line under the relationship, deleted; single direction is the default and needs no line of its own. Check which way the one direction then runs: with single direction the filter travels from the relationship's to column toward its from column, which are the toColumn and fromColumn lines in the file and the two ends of the arrow in the model view. Where a report needed the reverse filter, put it in the measure instead of the model, as in Budget In Scope = CALCULATE(SUM('Regional Budget'[Budget]), CROSSFILTER('Customer'[Region], 'Regional Budget'[Region], BOTH)), so one visual pays for it rather than every query. Better again, load a region table with one row per region and relate both tables to it many-to-one, which removes the many-to-many relationship and the question with it.\n\nWhen to ignore it\n\nA bridge that has to filter upward is the legitimate case: a security table that must narrow a dimension, or a mapping table between two dimensions that a slicer has to reach through. Both are designs where the reverse direction is the whole point, and neither is fixed by the rule's advice. Before you ignore one, trace the model view for a second path between the same two tables, because the ambiguity this rule guards against only exists when there are two, and one bridge with one path is safe. Ignore the finding on that relationship and leave the rule on: the next bi-directional many-to-many relationship someone adds is the one you want to hear about.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = MANY-TO-MANY_RELATIONSHIPS_SHOULD_BE_SINGLE-DIRECTION under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"MANY-TO-MANY_RELATIONSHIPS_SHOULD_BE_SINGLE-DIRECTION\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Both halves are read from the relationship alone. Nothing about the columns, their distinct counts, or whether any report uses the filter enters into it.\n- Inactive relationships are reported. A relationship that only comes alive inside USERELATIONSHIP is treated the same as an active one.\n- The from side is many by default and the to side is one, so a relationship counts as many-to-many only where toCardinality: many was written, whether or not fromCardinality: many is there beside it.\n\nRead more: https://pbiplint.com/rules/many-to-many-relationships-should-be-single-direction",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Customer\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\ntable 'Regional Budget'\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Budget\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Budget\n\nrelationship Customer_RegionalBudget\n\tfromCardinality: many\n\ttoCardinality: many\n\tcrossFilteringBehavior: bothDirections\n\tfromColumn: Customer.Region\n\ttoColumn: 'Regional Budget'.Region\n```\n\n**After the fix**\n\n```tmdl\ntable Customer\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn 'Customer ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CustomerID\n\ntable 'Regional Budget'\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Budget\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Budget\n\nrelationship Customer_RegionalBudget\n\tfromCardinality: many\n\ttoCardinality: many\n\tfromColumn: Customer.Region\n\ttoColumn: 'Regional Budget'.Region\n```\n\n### Why it matters\n\nA many-to-many relationship has no unique key on either side, so the engine resolves it through a set of distinct values rather than a direct lookup. Making that relationship bi-directional as well lets filters travel back through the same expansion, and that is where filter ambiguity begins: as soon as two paths reach the same table, the result depends on which path the engine chooses, and totals stop agreeing with the sum of their parts. The extra direction also costs at query time, because every filter has to be expanded across the distinct values on both sides instead of one. Single direction keeps one predictable filter path and is the accepted default; add the reverse direction only where a specific report needs it and you have confirmed the model has no second path.\n\n### How to fix it\n\nIn Power BI Desktop, open the model view, double-click the relationship, and set Cross filter direction to Single in the Edit relationship dialog. In the TMDL file that is the `crossFilteringBehavior: bothDirections` line under the relationship, deleted; single direction is the default and needs no line of its own. Check which way the one direction then runs: with single direction the filter travels from the relationship's to column toward its from column, which are the `toColumn` and `fromColumn` lines in the file and the two ends of the arrow in the model view. Where a report needed the reverse filter, put it in the measure instead of the model, as in `Budget In Scope = CALCULATE(SUM('Regional Budget'[Budget]), CROSSFILTER('Customer'[Region], 'Regional Budget'[Region], BOTH))`, so one visual pays for it rather than every query. Better again, load a region table with one row per region and relate both tables to it many-to-one, which removes the many-to-many relationship and the question with it.\n\n### When to ignore it\n\nA bridge that has to filter upward is the legitimate case: a security table that must narrow a dimension, or a mapping table between two dimensions that a slicer has to reach through. Both are designs where the reverse direction is the whole point, and neither is fixed by the rule's advice. Before you ignore one, trace the model view for a second path between the same two tables, because the ambiguity this rule guards against only exists when there are two, and one bridge with one path is safe. Ignore the finding on that relationship and leave the rule on: the next bi-directional many-to-many relationship someone adds is the one you want to hear about.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MANY-TO-MANY_RELATIONSHIPS_SHOULD_BE_SINGLE-DIRECTION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"MANY-TO-MANY_RELATIONSHIPS_SHOULD_BE_SINGLE-DIRECTION\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Both halves are read from the relationship alone. Nothing about the columns, their distinct counts, or whether any report uses the filter enters into it.\n- Inactive relationships are reported. A relationship that only comes alive inside USERELATIONSHIP is treated the same as an active one.\n- The from side is many by default and the to side is one, so a relationship counts as many-to-many only where `toCardinality: many` was written, whether or not `fromCardinality: many` is there beside it.\n\nRead more: https://pbiplint.com/rules/many-to-many-relationships-should-be-single-direction",
  },
  MARK_PRIMARY_KEYS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Product Key\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Product ID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product Key'\n\ttoColumn: Product.'Product ID'\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Product Key\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Product ID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product Key'\n\ttoColumn: Product.'Product ID'\n\nWhy it matters\n\nThe key flag declares that the column is unique, which lets the engine and client tools treat it as the identifier of the row rather than one more attribute to aggregate, and on an import model the engine enforces the uniqueness at refresh, so a duplicate key fails loudly instead of quietly doubling a total. It also documents intent: the next person reading the model can see at a glance which column defines the grain of the dimension, without tracing every relationship to work it out. Tables marked as date tables are skipped, because marking a table as a date table already sets the key on its date column.\n\nHow to fix it\n\nAdd isKey under the column in the TMDL file. Power BI Desktop has no box for the property on an ordinary table, and it keeps the value once it is in the file; the one place Desktop sets a key itself is Mark as date table, which sets it on the date column of the table you mark and takes that table out of this rule at the same time. Check that the column really is unique before you set it, because the engine takes the property at its word. Tabular Editor exposes the property in its property grid, which is a quicker way to set it across the dimensions of a large model than editing each file.\n\nWhen to ignore it\n\nA dimension you cannot yet guarantee is unique is the case to leave alone. If the table is loaded from a feed that occasionally repeats a row, the key property turns a silent double-count into a loud failure, which is the right trade once the source is under control and the wrong one while you are still chasing it. Check the distinct count against the row count before you set the property, not after. A calendar table is the other case: mark it as a date table instead, which sets the key on its date column and takes the table out of the rule.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = MARK_PRIMARY_KEYS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"MARK_PRIMARY_KEYS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- A table is skipped only when its data category is exactly Time, and the comparison is case-sensitive, so a file that says dataCategory: time does not count as a date table here.\n- A relationship that names no cardinality counts as many-to-one, which is Power BI's default, so an ordinary relationship block with only fromColumn and toColumn puts its to column in scope.\n- Inactive relationships count. A column that is only ever the one side of a relationship no measure activates is still reported.\n- The column is reported once however many relationships point at it.\n\nRead more: https://pbiplint.com/rules/mark-primary-keys",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Product Key\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Product ID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product Key'\n\ttoColumn: Product.'Product ID'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Product Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Product Key\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Product ID\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product Key'\n\ttoColumn: Product.'Product ID'\n```\n\n### Why it matters\n\nThe key flag declares that the column is unique, which lets the engine and client tools treat it as the identifier of the row rather than one more attribute to aggregate, and on an import model the engine enforces the uniqueness at refresh, so a duplicate key fails loudly instead of quietly doubling a total. It also documents intent: the next person reading the model can see at a glance which column defines the grain of the dimension, without tracing every relationship to work it out. Tables marked as date tables are skipped, because marking a table as a date table already sets the key on its date column.\n\n### How to fix it\n\nAdd `isKey` under the column in the TMDL file. Power BI Desktop has no box for the property on an ordinary table, and it keeps the value once it is in the file; the one place Desktop sets a key itself is Mark as date table, which sets it on the date column of the table you mark and takes that table out of this rule at the same time. Check that the column really is unique before you set it, because the engine takes the property at its word. Tabular Editor exposes the property in its property grid, which is a quicker way to set it across the dimensions of a large model than editing each file.\n\n### When to ignore it\n\nA dimension you cannot yet guarantee is unique is the case to leave alone. If the table is loaded from a feed that occasionally repeats a row, the key property turns a silent double-count into a loud failure, which is the right trade once the source is under control and the wrong one while you are still chasing it. Check the distinct count against the row count before you set the property, not after. A calendar table is the other case: mark it as a date table instead, which sets the key on its date column and takes the table out of the rule.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MARK_PRIMARY_KEYS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"MARK_PRIMARY_KEYS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- A table is skipped only when its data category is exactly `Time`, and the comparison is case-sensitive, so a file that says `dataCategory: time` does not count as a date table here.\n- A relationship that names no cardinality counts as many-to-one, which is Power BI's default, so an ordinary relationship block with only `fromColumn` and `toColumn` puts its to column in scope.\n- Inactive relationships count. A column that is only ever the one side of a relationship no measure activates is still reported.\n- The column is reported once however many relationships point at it.\n\nRead more: https://pbiplint.com/rules/mark-primary-keys",
  },
  MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure Revenue = [Total Sales]\n\t\tformatString: #,0\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nAn alias measure is a second name for the same number. Reports pick one or the other, the two drift apart the first time someone edits the alias instead of the original, and anyone reading the model has to follow the reference to learn what it means.\n\nHow to fix it\n\nRepoint the visuals that use the alias at the original, then delete it. In Power BI Desktop, right-click the alias in the Data pane and choose Delete from model. In the TMDL file, remove its measure block from the table.\n\nWhere the alias exists only because its name is the better one, do the rename the other way around: rename the original and delete the alias. Select the original in the Data pane, press F2, and type the new name, and Desktop repoints the visuals that use it. In the TMDL file the name is on the declaration line, so measure 'Total Sales' = becomes measure Revenue =, and a hand edit there does not update the report, so open the report and check its visuals afterwards.\n\nWhen to ignore it\n\nA rename in progress is the case that holds up: the alias keeps published reports working until each one is repointed, and it goes the day the last one moves. Give it an end date rather than leaving it. The argument that the alias puts the number in a second place in the field list does not hold, because the original's home table and display folder are both properties you can set on it, which is the same result without a second definition.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Only the exact form matches: the whole expression has to be [Name] and nothing else. A table prefix, a comment, a space inside the brackets, or any function around it takes the measure out of this rule. Whitespace around the expression does not: the parser trims it, so an alias written on the line below the = is still reported.\n- The match is case sensitive, so [total sales] is not reported even though DAX resolves it to the same measure.\n- The name in brackets has to be a measure in the model. An expression that is one bare reference to a column is not reported here, and neither is one that names nothing.\n- Measures only. A calculated column whose expression is a single measure reference is not reported.\n\nRead more: https://pbiplint.com/rules/measures-should-not-be-direct-references-of-other-measures",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure Revenue = [Total Sales]\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nAn alias measure is a second name for the same number. Reports pick one or the other, the two drift apart the first time someone edits the alias instead of the original, and anyone reading the model has to follow the reference to learn what it means.\n\n### How to fix it\n\nRepoint the visuals that use the alias at the original, then delete it. In Power BI Desktop, right-click the alias in the Data pane and choose Delete from model. In the TMDL file, remove its `measure` block from the table.\n\nWhere the alias exists only because its name is the better one, do the rename the other way around: rename the original and delete the alias. Select the original in the Data pane, press F2, and type the new name, and Desktop repoints the visuals that use it. In the TMDL file the name is on the declaration line, so `measure 'Total Sales' =` becomes `measure Revenue =`, and a hand edit there does not update the report, so open the report and check its visuals afterwards.\n\n### When to ignore it\n\nA rename in progress is the case that holds up: the alias keeps published reports working until each one is repointed, and it goes the day the last one moves. Give it an end date rather than leaving it. The argument that the alias puts the number in a second place in the field list does not hold, because the original's home table and display folder are both properties you can set on it, which is the same result without a second definition.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Only the exact form matches: the whole expression has to be `[Name]` and nothing else. A table prefix, a comment, a space inside the brackets, or any function around it takes the measure out of this rule. Whitespace around the expression does not: the parser trims it, so an alias written on the line below the `=` is still reported.\n- The match is case sensitive, so `[total sales]` is not reported even though DAX resolves it to the same measure.\n- The name in brackets has to be a measure in the model. An expression that is one bare reference to a column is not reported here, and neither is one that names nothing.\n- Measures only. A calculated column whose expression is a single measure reference is not reported.\n\nRead more: https://pbiplint.com/rules/measures-should-not-be-direct-references-of-other-measures",
  },
  MEASURES_USING_TIME_INTELLIGENCE_AND_MODEL_IS_USING_DIRECT_QUERY: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tmeasure 'Sales Last Year' = CALCULATE(SUM('Sales'[Amount]), SAMEPERIODLASTYEAR('Date'[Date]))\n\t\tformatString: #,0\n\n\tpartition Sales = m\n\t\tmode: directQuery\n\t\tsource = let Source = Sql.Database(\"finance\", \"Warehouse\"), Sales = Source{[Item = \"Sales\"]}[Data] in Sales\n\ntable Date\n\tdataCategory: Time\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tcolumn 'Amount Prior Year'\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: AmountPriorYear\n\n\tmeasure 'Sales Last Year' = SUM('Sales'[Amount Prior Year])\n\t\tformatString: #,0\n\n\tpartition Sales = m\n\t\tmode: directQuery\n\t\tsource = let Source = Sql.Database(\"finance\", \"Warehouse\"), Sales = Source{[Item = \"vwSalesWithPriorYear\"]}[Data] in Sales\n\ntable Date\n\tdataCategory: Time\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n\nWhy it matters\n\nTime intelligence functions build sets of dates and evaluate the measure over each set. In Import mode that is in-memory work. In DirectQuery each set becomes a query, or a long list of dates inside one, sent to the source on every visual refresh, and sources are rarely fast at it. The functions work, but a page of year-to-date and prior-year cards can take many seconds to render.\n\nHow to fix it\n\nEither take the model out of DirectQuery or take the time intelligence out of the measure. For the first, select the table in Power BI Desktop's model view and set Storage mode to Import in the Properties pane, which is the partition's mode: import line in the TMDL file; the finding clears only once no table in the model is left in DirectQuery, because the condition is about the model and not about the tables the measure happens to read. For the second, move the comparison into the data: add the prior period's value to each row in the source view or the warehouse, load it as an ordinary column, and write the measure as a SUM over it, which is what the example above does. Where neither is possible, keep the number of time intelligence measures on one page small and cache what you can in the source, because every one of them is another round trip.\n\nWhen to ignore it\n\nThe common false alarm is a measure that has nothing to do with the DirectQuery table. The rule reads the model, not the query path, so one small DirectQuery table kept for real-time status will report every time intelligence measure in the model, including the ones that run entirely over imported tables. Check which tables the measure actually touches before you act on it. A source that answers quickly is the second case: a well-indexed warehouse over a few million rows returns a year-to-date query in well under a second, and a page that renders fast is not a problem whatever the rule says. Time the visual before rewriting anything. What is not a legitimate exception is a large DirectQuery fact table over a source you do not control, where the finding is naming the reason the report is slow.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = MEASURES_USING_TIME_INTELLIGENCE_AND_MODEL_IS_USING_DIRECT_QUERY under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"MEASURES_USING_TIME_INTELLIGENCE_AND_MODEL_IS_USING_DIRECT_QUERY\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Function names are matched case-sensitively, in upper case only, as in the source rule, so totalytd( is not reported.\n- The names are matched anywhere in the expression, with no word boundary in front, so a measure or function whose name ends in one of them, such as MYDATEADD(, counts as a match. Whitespace between the name and the parenthesis is allowed.\n- The list is the source's thirty-seven functions, and it includes FIRSTNONBLANK, LASTNONBLANK, FIRSTNONBLANKVALUE, and LASTNONBLANKVALUE, which are regularly used over columns that hold no dates, so a measure with no date in it anywhere can be reported.\n- A table counts as DirectQuery when its first partition says mode: directQuery, letter case aside. No other mode counts, so a table set to Dual storage mode is not a DirectQuery table here, and a calculated table or a calculation group never is.\n\nRead more: https://pbiplint.com/rules/measures-using-time-intelligence-and-model-is-using-direct-query",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tmeasure 'Sales Last Year' = CALCULATE(SUM('Sales'[Amount]), SAMEPERIODLASTYEAR('Date'[Date]))\n\t\tformatString: #,0\n\n\tpartition Sales = m\n\t\tmode: directQuery\n\t\tsource = let Source = Sql.Database(\"finance\", \"Warehouse\"), Sales = Source{[Item = \"Sales\"]}[Data] in Sales\n\ntable Date\n\tdataCategory: Time\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tcolumn 'Amount Prior Year'\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: AmountPriorYear\n\n\tmeasure 'Sales Last Year' = SUM('Sales'[Amount Prior Year])\n\t\tformatString: #,0\n\n\tpartition Sales = m\n\t\tmode: directQuery\n\t\tsource = let Source = Sql.Database(\"finance\", \"Warehouse\"), Sales = Source{[Item = \"vwSalesWithPriorYear\"]}[Data] in Sales\n\ntable Date\n\tdataCategory: Time\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n```\n\n### Why it matters\n\nTime intelligence functions build sets of dates and evaluate the measure over each set. In Import mode that is in-memory work. In DirectQuery each set becomes a query, or a long list of dates inside one, sent to the source on every visual refresh, and sources are rarely fast at it. The functions work, but a page of year-to-date and prior-year cards can take many seconds to render.\n\n### How to fix it\n\nEither take the model out of DirectQuery or take the time intelligence out of the measure. For the first, select the table in Power BI Desktop's model view and set Storage mode to Import in the Properties pane, which is the partition's `mode: import` line in the TMDL file; the finding clears only once no table in the model is left in DirectQuery, because the condition is about the model and not about the tables the measure happens to read. For the second, move the comparison into the data: add the prior period's value to each row in the source view or the warehouse, load it as an ordinary column, and write the measure as a SUM over it, which is what the example above does. Where neither is possible, keep the number of time intelligence measures on one page small and cache what you can in the source, because every one of them is another round trip.\n\n### When to ignore it\n\nThe common false alarm is a measure that has nothing to do with the DirectQuery table. The rule reads the model, not the query path, so one small DirectQuery table kept for real-time status will report every time intelligence measure in the model, including the ones that run entirely over imported tables. Check which tables the measure actually touches before you act on it. A source that answers quickly is the second case: a well-indexed warehouse over a few million rows returns a year-to-date query in well under a second, and a page that renders fast is not a problem whatever the rule says. Time the visual before rewriting anything. What is not a legitimate exception is a large DirectQuery fact table over a source you do not control, where the finding is naming the reason the report is slow.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MEASURES_USING_TIME_INTELLIGENCE_AND_MODEL_IS_USING_DIRECT_QUERY` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"MEASURES_USING_TIME_INTELLIGENCE_AND_MODEL_IS_USING_DIRECT_QUERY\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Function names are matched case-sensitively, in upper case only, as in the source rule, so `totalytd(` is not reported.\n- The names are matched anywhere in the expression, with no word boundary in front, so a measure or function whose name ends in one of them, such as `MYDATEADD(`, counts as a match. Whitespace between the name and the parenthesis is allowed.\n- The list is the source's thirty-seven functions, and it includes FIRSTNONBLANK, LASTNONBLANK, FIRSTNONBLANKVALUE, and LASTNONBLANKVALUE, which are regularly used over columns that hold no dates, so a measure with no date in it anywhere can be reported.\n- A table counts as DirectQuery when its first partition says `mode: directQuery`, letter case aside. No other mode counts, so a table set to Dual storage mode is not a DirectQuery table here, and a calculated table or a calculation group never is.\n\nRead more: https://pbiplint.com/rules/measures-using-time-intelligence-and-model-is-using-direct-query",
  },
  MINIMIZE_POWER_QUERY_TRANSFORMATIONS: {
    text: 'Example\n\nFires the rule\n\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database("finance", "Warehouse"), Orders = Source{[Item = "Orders"]}[Data], Totals = Table.Group(Orders, {"OrderID"}, {{"Amount", each List.Sum([LineAmount])}}) in Totals\n\nAfter the fix\n\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database("finance", "Warehouse"), Totals = Source{[Item = "vwOrderTotals"]}[Data] in Totals\n\nWhy it matters\n\nThese are the steps most likely to stop query folding. When folding stops, Power Query pulls the raw rows and does the work itself on the refresh machine, on every refresh, instead of asking the source for the finished result. On a large table that is the difference between a five-minute refresh and an hour, and the same logic in a view or the warehouse runs once, with indexes.\n\nHow to fix it\n\nMove the work to the source. Create a view that does the join, the grouping, or the pivot, then in Power BI Desktop choose Transform data, point the query at the view, and delete the steps the view now does, so the Applied steps list is Source and little else. In the TMDL file the same text is the partition\'s source block, which is what Transform data edits. Where a step has to stay in Power Query, check that it still folds: right-click the last step in Applied steps and look at View native query, which is greyed out once folding has stopped at or before that step, and move everything after that point upstream. A native SQL query is its own case, because what folds after one depends on the connector; the safer shape is a view the query simply reads, which folds like any other table. Where the source is a file or a folder and there is nowhere upstream to move anything, leave the steps and read the finding as a note about why the refresh takes what it takes.\n\nWhen to ignore it\n\nWhere there is no upstream to move to, the finding is noise. A folder of CSV exports combined with Table.Combine, a SharePoint list, a workbook someone maintains by hand, an API that returns records to expand: none of these has a view behind it, and Power Query is the only place the work can happen. A step that folds is the second case: Table.Group over a SQL source turns into GROUP BY and costs the refresh nothing, so check View native query before rewriting anything. Size is the third judgment: on a dimension of a few thousand rows the whole question is worth less than the time spent on it. The case to act on is a large fact table whose query folds up to a point and then stops, which is where the rule pays for itself.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = MINIMIZE_POWER_QUERY_TRANSFORMATIONS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set "MINIMIZE_POWER_QUERY_TRANSFORMATIONS": "off" under rules in pbiplint.config.json.\n\nQuirks\n\n- The check is a case-sensitive substring match on the M text, so a function name inside a comment counts too, and a lower-case table.group( does not.\n- Each of the Table function patterns includes the opening parenthesis, so Table.Group ( written with a space is not matched. The native-query names carry no parenthesis and match wherever they appear.\n- Only partitions whose source type is M are read. A calculated table\'s expression is never checked, even where it contains one of these names.\n- The native-query patterns are [Query="SELECT, Value.NativeQuery, OleDb.Query, and Odbc.Query. The first is matched literally, so [Query = "SELECT with spaces around the equals sign passes, and so does a lower-case select.\n\nRead more: https://pbiplint.com/rules/minimize-power-query-transformations',
    markdown:
      '### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database("finance", "Warehouse"), Orders = Source{[Item = "Orders"]}[Data], Totals = Table.Group(Orders, {"OrderID"}, {{"Amount", each List.Sum([LineAmount])}}) in Totals\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database("finance", "Warehouse"), Totals = Source{[Item = "vwOrderTotals"]}[Data] in Totals\n```\n\n### Why it matters\n\nThese are the steps most likely to stop query folding. When folding stops, Power Query pulls the raw rows and does the work itself on the refresh machine, on every refresh, instead of asking the source for the finished result. On a large table that is the difference between a five-minute refresh and an hour, and the same logic in a view or the warehouse runs once, with indexes.\n\n### How to fix it\n\nMove the work to the source. Create a view that does the join, the grouping, or the pivot, then in Power BI Desktop choose Transform data, point the query at the view, and delete the steps the view now does, so the Applied steps list is Source and little else. In the TMDL file the same text is the partition\'s `source` block, which is what Transform data edits. Where a step has to stay in Power Query, check that it still folds: right-click the last step in Applied steps and look at View native query, which is greyed out once folding has stopped at or before that step, and move everything after that point upstream. A native SQL query is its own case, because what folds after one depends on the connector; the safer shape is a view the query simply reads, which folds like any other table. Where the source is a file or a folder and there is nowhere upstream to move anything, leave the steps and read the finding as a note about why the refresh takes what it takes.\n\n### When to ignore it\n\nWhere there is no upstream to move to, the finding is noise. A folder of CSV exports combined with Table.Combine, a SharePoint list, a workbook someone maintains by hand, an API that returns records to expand: none of these has a view behind it, and Power Query is the only place the work can happen. A step that folds is the second case: Table.Group over a SQL source turns into GROUP BY and costs the refresh nothing, so check View native query before rewriting anything. Size is the third judgment: on a dimension of a few thousand rows the whole question is worth less than the time spent on it. The case to act on is a large fact table whose query folds up to a point and then stops, which is where the rule pays for itself.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MINIMIZE_POWER_QUERY_TRANSFORMATIONS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MINIMIZE_POWER_QUERY_TRANSFORMATIONS": "off"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The check is a case-sensitive substring match on the M text, so a function name inside a comment counts too, and a lower-case `table.group(` does not.\n- Each of the Table function patterns includes the opening parenthesis, so `Table.Group (` written with a space is not matched. The native-query names carry no parenthesis and match wherever they appear.\n- Only partitions whose source type is M are read. A calculated table\'s expression is never checked, even where it contains one of these names.\n- The native-query patterns are `[Query="SELECT`, `Value.NativeQuery`, `OleDb.Query`, and `Odbc.Query`. The first is matched literally, so `[Query = "SELECT` with spaces around the equals sign passes, and so does a lower-case `select`.\n\nRead more: https://pbiplint.com/rules/minimize-power-query-transformations',
  },
  MODEL_SHOULD_HAVE_A_DATE_TABLE: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Date\n\tdataCategory: Time\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n\nWhy it matters\n\nEvery time intelligence function needs a contiguous date column to work over, and the marked date table is where it finds one. Without it, the model either leans on Auto date/time, which adds a hidden date table per date column and cannot be extended with fiscal periods or holidays, or does no time intelligence at all. A single shared date table also gives every fact table the same month, quarter, and year attributes, so visuals from different tables line up.\n\nHow to fix it\n\nAdd a calendar with one row per day covering every date the model holds, then mark it. The first-choice route is the source: load a calendar view or table in Transform data, so the fiscal periods and holidays live where the rest of the business already agrees on them. Failing that, build one in Power Query from a list of dates, or in Power BI Desktop under Modeling, New table with DAX such as Date = CALENDAR(DATE(2020, 1, 1), DATE(2030, 12, 31)); New table needs a table in import storage mode, so a model whose tables are all DirectQuery has to take the calendar from the source. Then select the table, open Table tools, choose Mark as date table, and pick the date column, which writes dataCategory: Time on the table and isKey on that column in the file. Finish by relating each fact table's date column to it in the model view and turning off Auto date/time under File, Options and settings, Options, Data Load, so the hidden per-column calendars stop being built.\n\nWhen to ignore it\n\nA model with no dates in it is the clean exception: a reference list, a product catalogue published for other models to join to, a survey result set. There is no time intelligence to do and no calendar would have anything to cover. A model that answers only current-state questions, such as a stock-on-hand report with no period comparison anywhere, is the same judgment made deliberately rather than by omission. Everything else that shows a trend, a year-to-date figure, or a comparison with last year needs the table, and the reason the rule is at warning is that the alternative, Auto date/time, works well enough in a demo to hide the problem until someone asks for a fiscal year.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = MODEL_SHOULD_HAVE_A_DATE_TABLE under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"MODEL_SHOULD_HAVE_A_DATE_TABLE\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Both properties are needed on one table: dataCategory: Time and isKey on one of its DateTime columns. A table with only one of them does not satisfy the rule.\n- The data category comparison is exact and case-sensitive, so dataCategory: time leaves the model reported.\n- Nothing else about the table is tested. It is not checked for contiguity, for covering the model's date range, or for being related to anything, so a one-row table marked as a date table clears the finding without helping any measure.\n- Any table can satisfy it, of any kind. A calculated calendar counts the same as a loaded one.\n\nRead more: https://pbiplint.com/rules/model-should-have-a-date-table",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Date\n\tdataCategory: Time\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n```\n\n### Why it matters\n\nEvery time intelligence function needs a contiguous date column to work over, and the marked date table is where it finds one. Without it, the model either leans on Auto date/time, which adds a hidden date table per date column and cannot be extended with fiscal periods or holidays, or does no time intelligence at all. A single shared date table also gives every fact table the same month, quarter, and year attributes, so visuals from different tables line up.\n\n### How to fix it\n\nAdd a calendar with one row per day covering every date the model holds, then mark it. The first-choice route is the source: load a calendar view or table in Transform data, so the fiscal periods and holidays live where the rest of the business already agrees on them. Failing that, build one in Power Query from a list of dates, or in Power BI Desktop under Modeling, New table with DAX such as `Date = CALENDAR(DATE(2020, 1, 1), DATE(2030, 12, 31))`; New table needs a table in import storage mode, so a model whose tables are all DirectQuery has to take the calendar from the source. Then select the table, open Table tools, choose Mark as date table, and pick the date column, which writes `dataCategory: Time` on the table and `isKey` on that column in the file. Finish by relating each fact table's date column to it in the model view and turning off Auto date/time under File, Options and settings, Options, Data Load, so the hidden per-column calendars stop being built.\n\n### When to ignore it\n\nA model with no dates in it is the clean exception: a reference list, a product catalogue published for other models to join to, a survey result set. There is no time intelligence to do and no calendar would have anything to cover. A model that answers only current-state questions, such as a stock-on-hand report with no period comparison anywhere, is the same judgment made deliberately rather than by omission. Everything else that shows a trend, a year-to-date figure, or a comparison with last year needs the table, and the reason the rule is at warning is that the alternative, Auto date/time, works well enough in a demo to hide the problem until someone asks for a fiscal year.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MODEL_SHOULD_HAVE_A_DATE_TABLE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"MODEL_SHOULD_HAVE_A_DATE_TABLE\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Both properties are needed on one table: `dataCategory: Time` and `isKey` on one of its DateTime columns. A table with only one of them does not satisfy the rule.\n- The data category comparison is exact and case-sensitive, so `dataCategory: time` leaves the model reported.\n- Nothing else about the table is tested. It is not checked for contiguity, for covering the model's date range, or for being related to anything, so a one-row table marked as a date table clears the finding without helping any measure.\n- Any table can satisfy it, of any kind. A calculated calendar counts the same as a loaded one.\n\nRead more: https://pbiplint.com/rules/model-should-have-a-date-table",
  },
  MODEL_USING_DIRECT_QUERY_AND_NO_AGGREGATIONS: {
    text: 'Example\n\nFires the rule\n\nmodel Model\n\tculture: en-US\n\tdefaultPowerBIDataSourceVersion: powerBI_V3\n\ntable Sales\n\tcolumn \'Order Date\'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: directQuery\n\t\tsource = let Source = Sql.Database("finance", "Warehouse"), Sales = Source{[Item = "Sales"]}[Data] in Sales\n\nAfter the fix\n\nmodel Model\n\tculture: en-US\n\tdefaultPowerBIDataSourceVersion: powerBI_V3\n\ntable Sales\n\tcolumn \'Order Date\'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: directQuery\n\t\tsource = let Source = Sql.Database("finance", "Warehouse"), Sales = Source{[Item = "Sales"]}[Data] in Sales\n\ntable \'Sales by Day\'\n\tisHidden\n\n\tcolumn \'Order Date\'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\t\talternateOf\n\t\t\tsummarization: groupBy\n\t\t\tbaseColumn: Order Date\n\t\t\tbaseTable: Sales\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\t\talternateOf\n\t\t\tsummarization: sum\n\t\t\tbaseColumn: Amount\n\t\t\tbaseTable: Sales\n\n\tpartition \'Sales by Day\' = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database("finance", "Warehouse"), Agg = Source{[Item = "vwSalesByDay"]}[Data] in Agg\n\nWhy it matters\n\nIn DirectQuery every visual sends a query to the source. Aggregation tables let the engine answer the common high-level questions, totals by month or by region, from a small imported table and send only the detail queries through. Without them, the summary page of a dashboard pays the full round trip to the source on every interaction. This is an info-level prompt to consider the feature, not a defect.\n\nHow to fix it\n\nBuild a summary table at the grain the reports use most, one row per day and region rather than one per transaction, and load it from a view in the source so the two tables stay consistent. Import it, keep the detail table in DirectQuery, and in Power BI Desktop right-click the summary table in the model view, choose Manage aggregations, and map each of its columns to the detail column it summarizes and the function that summarizes it. In the TMDL file that mapping is an alternateOf block under each aggregation column, which is the only thing the rule looks for, naming baseTable, baseColumn, and a summarization such as sum or groupBy. Hide the summary table afterwards: report authors write their measures against the detail table, and the engine redirects the query when it can. Any one aggregation mapping anywhere in the model clears this finding, so treat the rule as a prompt to start rather than a measure of how far you got.\n\nWhen to ignore it\n\nThe question is whether there is a summary worth precomputing. A DirectQuery table kept for a handful of live status tiles has none: the whole point is that the numbers are current to the second, and a cached summary would be wrong. A report that only ever reads detail rows, such as a lookup of one order by number, has none either, because there is no total for an aggregation to answer. A source that already serves a summarized view at the grain the report asks for is the third case, and there the aggregation exists, it is just on the other side of the connector. Where the report opens on a page of totals by month over a large DirectQuery fact table, the finding is worth acting on, and at info severity it will not fail a build while you decide.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = MODEL_USING_DIRECT_QUERY_AND_NO_AGGREGATIONS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set "MODEL_USING_DIRECT_QUERY_AND_NO_AGGREGATIONS": "off" under rules in pbiplint.config.json.\n\nQuirks\n\n- The data source version has to be present and read as powerBI_V3, compared without regard to letter case. A model file that does not carry defaultPowerBIDataSourceVersion at all is never reported, whatever its tables say.\n- One column with an alternateOf block anywhere in the model clears the finding, whatever it maps to. A single half-finished aggregation table counts as much as a complete set.\n- A table counts as DirectQuery when its first partition says mode: directQuery, letter case aside. No other mode counts, so a table set to Dual storage mode is not a DirectQuery table here.\n\nRead more: https://pbiplint.com/rules/model-using-direct-query-and-no-aggregations',
    markdown:
      '### Example\n\n**Fires the rule**\n\n```tmdl\nmodel Model\n\tculture: en-US\n\tdefaultPowerBIDataSourceVersion: powerBI_V3\n\ntable Sales\n\tcolumn \'Order Date\'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: directQuery\n\t\tsource = let Source = Sql.Database("finance", "Warehouse"), Sales = Source{[Item = "Sales"]}[Data] in Sales\n```\n\n**After the fix**\n\n```tmdl\nmodel Model\n\tculture: en-US\n\tdefaultPowerBIDataSourceVersion: powerBI_V3\n\ntable Sales\n\tcolumn \'Order Date\'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: directQuery\n\t\tsource = let Source = Sql.Database("finance", "Warehouse"), Sales = Source{[Item = "Sales"]}[Data] in Sales\n\ntable \'Sales by Day\'\n\tisHidden\n\n\tcolumn \'Order Date\'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\t\talternateOf\n\t\t\tsummarization: groupBy\n\t\t\tbaseColumn: Order Date\n\t\t\tbaseTable: Sales\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\t\talternateOf\n\t\t\tsummarization: sum\n\t\t\tbaseColumn: Amount\n\t\t\tbaseTable: Sales\n\n\tpartition \'Sales by Day\' = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database("finance", "Warehouse"), Agg = Source{[Item = "vwSalesByDay"]}[Data] in Agg\n```\n\n### Why it matters\n\nIn DirectQuery every visual sends a query to the source. Aggregation tables let the engine answer the common high-level questions, totals by month or by region, from a small imported table and send only the detail queries through. Without them, the summary page of a dashboard pays the full round trip to the source on every interaction. This is an info-level prompt to consider the feature, not a defect.\n\n### How to fix it\n\nBuild a summary table at the grain the reports use most, one row per day and region rather than one per transaction, and load it from a view in the source so the two tables stay consistent. Import it, keep the detail table in DirectQuery, and in Power BI Desktop right-click the summary table in the model view, choose Manage aggregations, and map each of its columns to the detail column it summarizes and the function that summarizes it. In the TMDL file that mapping is an `alternateOf` block under each aggregation column, which is the only thing the rule looks for, naming `baseTable`, `baseColumn`, and a `summarization` such as sum or groupBy. Hide the summary table afterwards: report authors write their measures against the detail table, and the engine redirects the query when it can. Any one aggregation mapping anywhere in the model clears this finding, so treat the rule as a prompt to start rather than a measure of how far you got.\n\n### When to ignore it\n\nThe question is whether there is a summary worth precomputing. A DirectQuery table kept for a handful of live status tiles has none: the whole point is that the numbers are current to the second, and a cached summary would be wrong. A report that only ever reads detail rows, such as a lookup of one order by number, has none either, because there is no total for an aggregation to answer. A source that already serves a summarized view at the grain the report asks for is the third case, and there the aggregation exists, it is just on the other side of the connector. Where the report opens on a page of totals by month over a large DirectQuery fact table, the finding is worth acting on, and at info severity it will not fail a build while you decide.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MODEL_USING_DIRECT_QUERY_AND_NO_AGGREGATIONS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MODEL_USING_DIRECT_QUERY_AND_NO_AGGREGATIONS": "off"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The data source version has to be present and read as powerBI_V3, compared without regard to letter case. A model file that does not carry `defaultPowerBIDataSourceVersion` at all is never reported, whatever its tables say.\n- One column with an `alternateOf` block anywhere in the model clears the finding, whatever it maps to. A single half-finished aggregation table counts as much as a complete set.\n- A table counts as DirectQuery when its first partition says `mode: directQuery`, letter case aside. No other mode counts, so a table set to Dual storage mode is not a DirectQuery table here.\n\nRead more: https://pbiplint.com/rules/model-using-direct-query-and-no-aggregations',
  },
  "MONTH_(AS_A_STRING)_MUST_BE_SORTED": {
    text: "Example\n\nFires the rule\n\ntable Date\n\tcolumn 'Month Name'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Month Name\n\n\tcolumn 'Month Number'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Month Number\n\nAfter the fix\n\ntable Date\n\tcolumn 'Month Name'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsortByColumn: 'Month Number'\n\t\tsourceColumn: Month Name\n\n\tcolumn 'Month Number'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Month Number\n\nWhy it matters\n\nA text month sorts alphabetically: April, August, December. Every axis and slicer that uses the column shows that order until someone notices, and the fix has to be repeated in each visual unless it is made once on the column.\n\nHow to fix it\n\nAdd a month number column to the table, hide it, then in Power BI Desktop select the month name column and pick the number under Sort by column in Column tools. In the TMDL file the property is sortByColumn: 'Month Number' under the month name column. Each month name has to map to exactly one number, so a name like January that appears in several years needs a number column at the same grain, 1 through 12, not a year-month key; Power BI rejects the sort otherwise. Where the axis runs across years, sort a Month Year column by a year-month number instead and leave the plain month name for the within-year views.\n\nWhen to ignore it\n\nA text column the name test catches that is not a list of month names is noise: a Monthly Target note, a Month Comment, anything where alphabetical order is as good as any other. A month column whose values already sort correctly is the other case, such as one holding 2026-01 and 2026-02, where a sort-by column would only add a second column to maintain. Where the values are month names, there is no reason to leave the sort alphabetical.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = MONTH_(AS_A_STRING)_MUST_BE_SORTED under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"MONTH_(AS_A_STRING)_MUST_BE_SORTED\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The name test is a substring of the upper-cased name, so Month Name is reported and so is a text column called Monthly Target.\n- The exclusion is the substring MONTHS, not the word, so Months Elapsed passes and so do MonthStart and MonthSort, whose upper-cased names contain MONTHS. Written with a space, Month Start is reported.\n- Only text columns are read. A month held as a whole number, or as a DateTime, is not reported here.\n- Any sort-by column clears the finding. The rule checks that the property is set, not that it points at a month number.\n- Hidden columns, and columns in hidden tables, are in scope.\n\nRead more: https://pbiplint.com/rules/month-as-a-string-must-be-sorted",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Date\n\tcolumn 'Month Name'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Month Name\n\n\tcolumn 'Month Number'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Month Number\n```\n\n**After the fix**\n\n```tmdl\ntable Date\n\tcolumn 'Month Name'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsortByColumn: 'Month Number'\n\t\tsourceColumn: Month Name\n\n\tcolumn 'Month Number'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Month Number\n```\n\n### Why it matters\n\nA text month sorts alphabetically: April, August, December. Every axis and slicer that uses the column shows that order until someone notices, and the fix has to be repeated in each visual unless it is made once on the column.\n\n### How to fix it\n\nAdd a month number column to the table, hide it, then in Power BI Desktop select the month name column and pick the number under Sort by column in Column tools. In the TMDL file the property is `sortByColumn: 'Month Number'` under the month name column. Each month name has to map to exactly one number, so a name like January that appears in several years needs a number column at the same grain, 1 through 12, not a year-month key; Power BI rejects the sort otherwise. Where the axis runs across years, sort a Month Year column by a year-month number instead and leave the plain month name for the within-year views.\n\n### When to ignore it\n\nA text column the name test catches that is not a list of month names is noise: a Monthly Target note, a Month Comment, anything where alphabetical order is as good as any other. A month column whose values already sort correctly is the other case, such as one holding 2026-01 and 2026-02, where a sort-by column would only add a second column to maintain. Where the values are month names, there is no reason to leave the sort alphabetical.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MONTH_(AS_A_STRING)_MUST_BE_SORTED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"MONTH_(AS_A_STRING)_MUST_BE_SORTED\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The name test is a substring of the upper-cased name, so Month Name is reported and so is a text column called Monthly Target.\n- The exclusion is the substring MONTHS, not the word, so Months Elapsed passes and so do MonthStart and MonthSort, whose upper-cased names contain MONTHS. Written with a space, Month Start is reported.\n- Only text columns are read. A month held as a whole number, or as a DateTime, is not reported here.\n- Any sort-by column clears the finding. The rule checks that the property is set, not that it points at a month number.\n- Hidden columns, and columns in hidden tables, are in scope.\n\nRead more: https://pbiplint.com/rules/month-as-a-string-must-be-sorted",
  },
  MONTHCOLUMN_FORMATSTRING: {
    text: "Example\n\nFires the rule\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsummarizeBy: none\n\t\tsourceColumn: Date\n\n\tcolumn 'Month Start'\n\t\tdataType: dateTime\n\t\tsummarizeBy: none\n\t\tsourceColumn: Month Start\n\nAfter the fix\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsummarizeBy: none\n\t\tsourceColumn: Date\n\n\tcolumn 'Month Start'\n\t\tdataType: dateTime\n\t\tformatString: MMMM yyyy\n\t\tsummarizeBy: none\n\t\tsourceColumn: Month Start\n\nWhy it matters\n\nA DateTime column named Month usually holds the first day of each month, and with a default date format it reads as March 1, 2026 rather than March 2026. The MMMM yyyy format shows the month and year, and setting it on the column fixes every visual at once.\n\nHow to fix it\n\nIn Power BI Desktop, select the column in the Data pane and set Format under Column tools. In the TMDL file, add formatString: MMMM yyyy under the column. The column keeps its DateTime type and its value, so it still sorts chronologically and still works in a relationship to the date table; only what a visual prints changes.\n\nWhen to ignore it\n\nA DateTime column with month in its name that holds a full date, not a month start, is the case to leave alone: formatting Month End Date as MMMM yyyy throws away the day, which is the part a reader needs. House style is the other case, where a model already writes its month labels as MMM yyyy and changing them would leave two conventions in the same report. A hidden month column shows nothing to anyone, so its format string is not worth a change on its own.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = MONTHCOLUMN_FORMATSTRING under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"MONTHCOLUMN_FORMATSTRING\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The name test is a substring matched without regard to letter case, so any DateTime column with month in its name is checked, including Month End Date and a Bimonthly Cutoff column.\n- Only the exact string MMMM yyyy passes, and the comparison is case-sensitive, so a format string that differs from it only in letter case is still reported.\n- Only DateTime columns are read. A month held as text or as a whole number is not reported here.\n- Hidden columns, and columns in hidden tables, are in scope.\n\nRead more: https://pbiplint.com/rules/monthcolumn-formatstring",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsummarizeBy: none\n\t\tsourceColumn: Date\n\n\tcolumn 'Month Start'\n\t\tdataType: dateTime\n\t\tsummarizeBy: none\n\t\tsourceColumn: Month Start\n```\n\n**After the fix**\n\n```tmdl\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsummarizeBy: none\n\t\tsourceColumn: Date\n\n\tcolumn 'Month Start'\n\t\tdataType: dateTime\n\t\tformatString: MMMM yyyy\n\t\tsummarizeBy: none\n\t\tsourceColumn: Month Start\n```\n\n### Why it matters\n\nA DateTime column named Month usually holds the first day of each month, and with a default date format it reads as March 1, 2026 rather than March 2026. The `MMMM yyyy` format shows the month and year, and setting it on the column fixes every visual at once.\n\n### How to fix it\n\nIn Power BI Desktop, select the column in the Data pane and set Format under Column tools. In the TMDL file, add `formatString: MMMM yyyy` under the column. The column keeps its DateTime type and its value, so it still sorts chronologically and still works in a relationship to the date table; only what a visual prints changes.\n\n### When to ignore it\n\nA DateTime column with month in its name that holds a full date, not a month start, is the case to leave alone: formatting Month End Date as `MMMM yyyy` throws away the day, which is the part a reader needs. House style is the other case, where a model already writes its month labels as `MMM yyyy` and changing them would leave two conventions in the same report. A hidden month column shows nothing to anyone, so its format string is not worth a change on its own.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MONTHCOLUMN_FORMATSTRING` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"MONTHCOLUMN_FORMATSTRING\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The name test is a substring matched without regard to letter case, so any DateTime column with month in its name is checked, including Month End Date and a Bimonthly Cutoff column.\n- Only the exact string `MMMM yyyy` passes, and the comparison is case-sensitive, so a format string that differs from it only in letter case is still reported.\n- Only DateTime columns are read. A month held as text or as a whole number is not reported here.\n- Hidden columns, and columns in hidden tables, are in scope.\n\nRead more: https://pbiplint.com/rules/monthcolumn-formatstring",
  },
  NUMERIC_COLUMN_SUMMARIZE_BY: {
    text: 'Example\n\nFires the rule\n\ntable Date\n\tcolumn Year\n\t\tdataType: int64\n\t\tsourceColumn: Year\n\nAfter the fix\n\ntable Date\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n\nWhy it matters\n\nWith a default summarization, dragging the column onto a visual produces an implicit sum, and it is easy to sum something that should never be summed: a year, a unit price, a percentage, a key. The implicit measure also bypasses the format string and the logic of the real measures, so two visuals of the same thing disagree. With summarization off, the column lands on a visual as a category and the author reaches for a measure.\n\nHow to fix it\n\nIn Power BI Desktop, select the column in the Data pane and set Summarization to Don\'t summarize under Column tools. In the TMDL file the property is summarizeBy: none under the column. Where the column really is a number reports need totals of, add an explicit measure for it, because the point of the change is that the aggregation becomes something the model defines rather than something a visual guesses.\n\nWhen to ignore it\n\nAn additive column with no measure behind it is the case to weigh. On a small planning or budget table that a handful of people build their own matrices from, the implicit sum is the feature, and taking it away without writing the measures first makes the model harder to use, not safer. Check which reports drag the column in before you change it. A year, a key, a price, or a rate is never that case: summing any of them produces a number with no meaning, and those are the findings to act on first.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = NUMERIC_COLUMN_SUMMARIZE_BY under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set "NUMERIC_COLUMN_SUMMARIZE_BY": "off" under rules in pbiplint.config.json.\n\nQuirks\n\n- A column with no summarizeBy property is treated as Default, which is not None, so it is reported. That is where most findings come from.\n- The property value is compared without regard to letter case, so summarizeBy: None passes as well as summarizeBy: none.\n- Hidden columns, and columns in hidden tables, are skipped.\n- Only whole number, decimal, and double columns are in scope, so a DateTime or text column with a summarization set is never reported here.\n\nRead more: https://pbiplint.com/rules/numeric-column-summarize-by',
    markdown:
      '### Example\n\n**Fires the rule**\n\n```tmdl\ntable Date\n\tcolumn Year\n\t\tdataType: int64\n\t\tsourceColumn: Year\n```\n\n**After the fix**\n\n```tmdl\ntable Date\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n```\n\n### Why it matters\n\nWith a default summarization, dragging the column onto a visual produces an implicit sum, and it is easy to sum something that should never be summed: a year, a unit price, a percentage, a key. The implicit measure also bypasses the format string and the logic of the real measures, so two visuals of the same thing disagree. With summarization off, the column lands on a visual as a category and the author reaches for a measure.\n\n### How to fix it\n\nIn Power BI Desktop, select the column in the Data pane and set Summarization to Don\'t summarize under Column tools. In the TMDL file the property is `summarizeBy: none` under the column. Where the column really is a number reports need totals of, add an explicit measure for it, because the point of the change is that the aggregation becomes something the model defines rather than something a visual guesses.\n\n### When to ignore it\n\nAn additive column with no measure behind it is the case to weigh. On a small planning or budget table that a handful of people build their own matrices from, the implicit sum is the feature, and taking it away without writing the measures first makes the model harder to use, not safer. Check which reports drag the column in before you change it. A year, a key, a price, or a rate is never that case: summing any of them produces a number with no meaning, and those are the findings to act on first.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = NUMERIC_COLUMN_SUMMARIZE_BY` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"NUMERIC_COLUMN_SUMMARIZE_BY": "off"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- A column with no `summarizeBy` property is treated as Default, which is not None, so it is reported. That is where most findings come from.\n- The property value is compared without regard to letter case, so `summarizeBy: None` passes as well as `summarizeBy: none`.\n- Hidden columns, and columns in hidden tables, are skipped.\n- Only whole number, decimal, and double columns are in scope, so a DateTime or text column with a summarization set is never reported here.\n\nRead more: https://pbiplint.com/rules/numeric-column-summarize-by',
  },
  OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order ID '\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\nWhy it matters\n\nA leading or trailing space is invisible on screen but is part of the name, so \"Sales \" and \"Sales\" are two different objects to the engine. That is enough to break a DAX reference, a report visual binding, or a deployment that expects the trimmed name, and the error you get back will name an object that looks perfectly correct. Stray spaces almost always arrive by accident, pasted in or inherited from a source column name, so trimming them is safe and rarely breaks anything downstream. TRIM_OBJECT_NAMES makes the same check across more object types at a lower severity, so every finding here appears there as well.\n\nHow to fix it\n\nIn Power BI Desktop, double-click the field in the Data pane and retype the name without the space, or select the object and clear the space from Name in the Properties pane. In the TMDL file the name is on the declaration line, so column 'Order ID ' becomes column 'Order ID'. A data column carries its own sourceColumn, so trimming the model name does not change what the refresh loads. Renaming in Desktop updates the visuals bound to the field; a hand edit in the file does not, so open the report and check its visuals after one. Where the space arrives with a source column name, trim it in Power Query too, so the next column you add from that query comes in clean.\n\nWhen to ignore it\n\nNo name should start or end with a space, and this rule reports at error severity because a name that reads as correct and is not costs more to diagnose than to fix. A leading space is sometimes used to push a measure to the top of the field list; a display folder puts the measure where it belongs without hiding a character in its name.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Narrower scope than TRIM_OBJECT_NAMES: levels, roles, named expressions, calculation items, calculation group tables, data sources, calculated tables, and calculated table columns are not checked here.\n- The test is for the space character at the start or the end of the name. A name padded with a tab is not reported here; SPECIAL_CHARS_IN_OBJECT_NAMES covers that one.\n- The model object is in scope, and a finding on the model is always named Model whatever the model is called, so a stray space in the model's own name gives a finding with nothing in the line to show it. The model's name is on the model line in the TMDL file.\n- In the browser, the \"Choose a folder\" button in Chrome and Edge does not list a file whose name begins or ends with a space, so a table file named that way is never read on that route and its findings are missing. Drag the folder onto the page, or use the command line, to read it.\n\nRead more: https://pbiplint.com/rules/objects-should-not-start-or-end-with-a-space",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID '\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n```\n\n### Why it matters\n\nA leading or trailing space is invisible on screen but is part of the name, so \"Sales \" and \"Sales\" are two different objects to the engine. That is enough to break a DAX reference, a report visual binding, or a deployment that expects the trimmed name, and the error you get back will name an object that looks perfectly correct. Stray spaces almost always arrive by accident, pasted in or inherited from a source column name, so trimming them is safe and rarely breaks anything downstream. `TRIM_OBJECT_NAMES` makes the same check across more object types at a lower severity, so every finding here appears there as well.\n\n### How to fix it\n\nIn Power BI Desktop, double-click the field in the Data pane and retype the name without the space, or select the object and clear the space from Name in the Properties pane. In the TMDL file the name is on the declaration line, so `column 'Order ID '` becomes `column 'Order ID'`. A data column carries its own `sourceColumn`, so trimming the model name does not change what the refresh loads. Renaming in Desktop updates the visuals bound to the field; a hand edit in the file does not, so open the report and check its visuals after one. Where the space arrives with a source column name, trim it in Power Query too, so the next column you add from that query comes in clean.\n\n### When to ignore it\n\nNo name should start or end with a space, and this rule reports at error severity because a name that reads as correct and is not costs more to diagnose than to fix. A leading space is sometimes used to push a measure to the top of the field list; a display folder puts the measure where it belongs without hiding a character in its name.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Narrower scope than `TRIM_OBJECT_NAMES`: levels, roles, named expressions, calculation items, calculation group tables, data sources, calculated tables, and calculated table columns are not checked here.\n- The test is for the space character at the start or the end of the name. A name padded with a tab is not reported here; `SPECIAL_CHARS_IN_OBJECT_NAMES` covers that one.\n- The model object is in scope, and a finding on the model is always named `Model` whatever the model is called, so a stray space in the model's own name gives a finding with nothing in the line to show it. The model's name is on the `model` line in the TMDL file.\n- In the browser, the \"Choose a folder\" button in Chrome and Edge does not list a file whose name begins or ends with a space, so a table file named that way is never read on that route and its findings are missing. Drag the folder onto the page, or use the command line, to read it.\n\nRead more: https://pbiplint.com/rules/objects-should-not-start-or-end-with-a-space",
  },
  OBJECTS_WITH_NO_DESCRIPTION: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nAfter the fix\n\n/// One row per order line, loaded nightly from the sales warehouse.\ntable Sales\n\n\t/// Line amount in US dollars, net of discount and before tax.\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\t/// Sum of line amount over whatever the visual is filtered to.\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nThe description is the tooltip a report author sees when hovering a field in the field list, and it is the only place in the model to say what a measure counts, which currency a column is in, or which of two similar fields to use. Without it, every author works that out from the name, and gets it wrong at about the same rate. Descriptions also feed documentation tools, so the same sentence pays off twice.\n\nHow to fix it\n\nIn Power BI Desktop, open Model view, select the object, and type the Description in the Properties pane. In the TMDL file a description is one or more /// lines directly above the object's declaration, with no blank line between the last /// line and the declaration: a blank line ends the description, and the object below it is read as having none. With hundreds of objects, Tabular Editor can paste descriptions into many at once from a list.\n\nWhen to ignore it\n\nA name that already says the whole thing needs nothing added: 'Date'[Year] gains nothing from a sentence reading \"the year\". Spend the descriptions on measures, on any column whose unit, currency, grain, or filter behavior is not in its name, and on the two fields a reader has to choose between. A table or column you are about to hide is better hidden than described, because hiding it also clears this finding.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = OBJECTS_WITH_NO_DESCRIPTION under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"OBJECTS_WITH_NO_DESCRIPTION\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Visibility is the object's own isHidden flag: a visible column inside a hidden table is still reported.\n- A calculation group table is reported once, as a calculation group.\n- A description of only spaces or tabs counts as none, so padding a description to quiet the rule does not work.\n- Hierarchies, hierarchy levels, calculation items, partitions, roles, perspectives, data sources, and named expressions are outside the scope, so an undescribed hierarchy is never reported here.\n\nRead more: https://pbiplint.com/rules/objects-with-no-description",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\n/// One row per order line, loaded nightly from the sales warehouse.\ntable Sales\n\n\t/// Line amount in US dollars, net of discount and before tax.\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\t/// Sum of line amount over whatever the visual is filtered to.\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nThe description is the tooltip a report author sees when hovering a field in the field list, and it is the only place in the model to say what a measure counts, which currency a column is in, or which of two similar fields to use. Without it, every author works that out from the name, and gets it wrong at about the same rate. Descriptions also feed documentation tools, so the same sentence pays off twice.\n\n### How to fix it\n\nIn Power BI Desktop, open Model view, select the object, and type the Description in the Properties pane. In the TMDL file a description is one or more `///` lines directly above the object's declaration, with no blank line between the last `///` line and the declaration: a blank line ends the description, and the object below it is read as having none. With hundreds of objects, Tabular Editor can paste descriptions into many at once from a list.\n\n### When to ignore it\n\nA name that already says the whole thing needs nothing added: `'Date'[Year]` gains nothing from a sentence reading \"the year\". Spend the descriptions on measures, on any column whose unit, currency, grain, or filter behavior is not in its name, and on the two fields a reader has to choose between. A table or column you are about to hide is better hidden than described, because hiding it also clears this finding.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = OBJECTS_WITH_NO_DESCRIPTION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"OBJECTS_WITH_NO_DESCRIPTION\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Visibility is the object's own isHidden flag: a visible column inside a hidden table is still reported.\n- A calculation group table is reported once, as a calculation group.\n- A description of only spaces or tabs counts as none, so padding a description to quiet the rule does not work.\n- Hierarchies, hierarchy levels, calculation items, partitions, roles, perspectives, data sources, and named expressions are outside the scope, so an undescribed hierarchy is never reported here.\n\nRead more: https://pbiplint.com/rules/objects-with-no-description",
  },
  PARSE_ISSUE: {
    text: 'Example\n\nFires the rule\n\ntable Sales\n    column Amount\n        dataType: decimal\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\nThe first snippet is indented with spaces, so both lines under the table are reported, and the model pbiplint checks has a Sales table with no columns.\n\nWhy it matters\n\nThe parser skipped the line, so whatever it declared, a column, a property, a measure, is missing from the model the rules see. Findings on that object and on anything that references it may be missing or wrong, and a result that looks clean may not be. The orphaned description is the mild case: no declaration is lost, only the description, which stops at the blank line instead of reaching the object below it, so that object is read as having none. Tabular Editor\'s TMDL reader is stricter and refuses to open a file that puts a blank line after a /// line at all.\n\nHow to fix it\n\nOpen the file at the reported line. TMDL is indented with tabs, and expression blocks open and close with ``` on their own lines. A /// description must sit directly above its declaration, with no blank line between them. Power BI Desktop writes valid TMDL, so a parse issue usually means a hand edit or a merge conflict marker.\n\nWhen to ignore it\n\nNot on purpose. A parse issue means the model pbiplint checked is not the model in the file, so every other result on that file is in doubt until the line is fixed. The one exception is a line that Power BI Desktop wrote and opens without complaint and pbiplint still reports: that is a gap in pbiplint\'s parser. Report it with the line. Until it is fixed, only the project-wide switch quiets it, and that also hides real parse issues, so weigh the two.\n\nThis rule reports on files, so there is no object to annotate. To turn the rule off for a whole project, set "PARSE_ISSUE": "off" under rules in pbiplint.config.json.\n\nRead more: https://pbiplint.com/rules/parse-issue',
    markdown:
      '### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n    column Amount\n        dataType: decimal\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n```\n\nThe first snippet is indented with spaces, so both lines under the table are reported, and the model pbiplint checks has a Sales table with no columns.\n\n### Why it matters\n\nThe parser skipped the line, so whatever it declared, a column, a property, a measure, is missing from the model the rules see. Findings on that object and on anything that references it may be missing or wrong, and a result that looks clean may not be. The orphaned description is the mild case: no declaration is lost, only the description, which stops at the blank line instead of reaching the object below it, so that object is read as having none. Tabular Editor\'s TMDL reader is stricter and refuses to open a file that puts a blank line after a `///` line at all.\n\n### How to fix it\n\nOpen the file at the reported line. TMDL is indented with tabs, and expression blocks open and close with ``` on their own lines. A `///` description must sit directly above its declaration, with no blank line between them. Power BI Desktop writes valid TMDL, so a parse issue usually means a hand edit or a merge conflict marker.\n\n### When to ignore it\n\nNot on purpose. A parse issue means the model pbiplint checked is not the model in the file, so every other result on that file is in doubt until the line is fixed. The one exception is a line that Power BI Desktop wrote and opens without complaint and pbiplint still reports: that is a gap in pbiplint\'s parser. Report it with the line. Until it is fixed, only the project-wide switch quiets it, and that also hides real parse issues, so weigh the two.\n\nThis rule reports on files, so there is no object to annotate. To turn the rule off for a whole project, set `"PARSE_ISSUE": "off"` under `rules` in `pbiplint.config.json`.\n\nRead more: https://pbiplint.com/rules/parse-issue',
  },
  PARTITION_NAME_SHOULD_MATCH_TABLE_NAME_FOR_SINGLE_PARTITION_TABLES: {
    text: 'Example\n\nFires the rule\n\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tpartition SalesData = m\n\t\tmode: import\n\t\tsource = Sql.Database("contoso", "Sales")\n\nAfter the fix\n\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = Sql.Database("contoso", "Sales")\n\nWhy it matters\n\nA single-partition table has no reason for its partition to carry a different name, and when it does it is usually the table\'s old name from before a rename. Refresh logs, error messages, and the TMDL file all name the partition, so a mismatch sends the reader looking for a table that no longer exists.\n\nHow to fix it\n\nThe partition\'s name sits on its declaration line, so partition SalesData = m under table Sales becomes partition Sales = m. Nothing else in the TMDL file refers to a partition by name, so on a single-partition table the rename changes nothing but the label in the refresh log. Power BI Desktop has no partition list and no field for a partition name: it names the partition when it creates the table and leaves the name alone afterwards, so a mismatch on a Desktop project points at a hand edit, a table renamed outside Desktop, or a model migrated from another tool. If a whole model needs correcting, Tabular Editor\'s partition editor renames partitions without opening each file.\n\nWhen to ignore it\n\nA partition that the people who run the refresh already know by another name can keep it, for example one named after the stored procedure that fills it, because that is the name they will look for when the refresh fails. Outside that, a single partition named anything but its table is a leftover, and the rename costs nothing.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = PARTITION_NAME_SHOULD_MATCH_TABLE_NAME_FOR_SINGLE_PARTITION_TABLES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set "PARTITION_NAME_SHOULD_MATCH_TABLE_NAME_FOR_SINGLE_PARTITION_TABLES": "off" under rules in pbiplint.config.json.\n\nQuirks\n\n- The condition tests tables with exactly one partition. A table with none, and a table with several, is never reported, whatever its partitions are called.\n\nRead more: https://pbiplint.com/rules/partition-name-should-match-table-name-for-single-partition-tables',
    markdown:
      '### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tpartition SalesData = m\n\t\tmode: import\n\t\tsource = Sql.Database("contoso", "Sales")\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn \'Order ID\'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = Sql.Database("contoso", "Sales")\n```\n\n### Why it matters\n\nA single-partition table has no reason for its partition to carry a different name, and when it does it is usually the table\'s old name from before a rename. Refresh logs, error messages, and the TMDL file all name the partition, so a mismatch sends the reader looking for a table that no longer exists.\n\n### How to fix it\n\nThe partition\'s name sits on its declaration line, so `partition SalesData = m` under `table Sales` becomes `partition Sales = m`. Nothing else in the TMDL file refers to a partition by name, so on a single-partition table the rename changes nothing but the label in the refresh log. Power BI Desktop has no partition list and no field for a partition name: it names the partition when it creates the table and leaves the name alone afterwards, so a mismatch on a Desktop project points at a hand edit, a table renamed outside Desktop, or a model migrated from another tool. If a whole model needs correcting, Tabular Editor\'s partition editor renames partitions without opening each file.\n\n### When to ignore it\n\nA partition that the people who run the refresh already know by another name can keep it, for example one named after the stored procedure that fills it, because that is the name they will look for when the refresh fails. Outside that, a single partition named anything but its table is a leftover, and the rename costs nothing.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = PARTITION_NAME_SHOULD_MATCH_TABLE_NAME_FOR_SINGLE_PARTITION_TABLES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"PARTITION_NAME_SHOULD_MATCH_TABLE_NAME_FOR_SINGLE_PARTITION_TABLES": "off"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The condition tests tables with exactly one partition. A table with none, and a table with several, is never reported, whatever its partitions are called.\n\nRead more: https://pbiplint.com/rules/partition-name-should-match-table-name-for-single-partition-tables',
  },
  PERCENTAGE_FORMATTING: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Cost\n\n\tmeasure 'Margin %' = DIVIDE(SUM('Sales'[Amount]) - SUM('Sales'[Cost]), SUM('Sales'[Amount]))\n\t\tformatString: 0.0%\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Cost\n\n\tmeasure 'Margin %' = DIVIDE(SUM('Sales'[Amount]) - SUM('Sales'[Cost]), SUM('Sales'[Amount]))\n\t\tformatString: #,0.0%;-#,0.0%;#,0.0%\n\nWhy it matters\n\nPercentages formatted inconsistently end up side by side in the same report, so one card reads 12.3% while the next reads 12.34% or 12%, and the reader is left wondering whether the numbers disagree or only the formatting does. The three-part string this rule expects sets the positive, negative, and zero cases together, so a negative percentage keeps its sign and a thousands separator appears once values pass 1000%. Setting it on the measure fixes the presentation for every report that uses the model, rather than leaving each report author to format the visual by hand. This is house style rather than correctness: the rule enforces one convention, not the only workable one.\n\nHow to fix it\n\nUse the format string #,0.0%;-#,0.0%;#,0.0%. In Power BI Desktop, select the measure in the Data pane and paste the string into the Format box under Measure tools. In the TMDL file, set formatString: #,0.0%;-#,0.0%;#,0.0% under the measure. The three parts are the positive, negative, and zero cases in that order, which is why the string repeats itself: it says how each of the three is rendered rather than leaving two of them to a default.\n\nWhen to ignore it\n\nA percentage that needs a different precision is the honest exception: a conversion rate people read to two decimals, or a completion figure that reads better as a whole number on a card. If that is the house standard, every percentage measure in the model fires and the rule is measuring the wrong convention, which is worth settling once for the whole model rather than card by card. What is not an exception is a single measure left at the client default because nobody chose a format for it.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = PERCENTAGE_FORMATTING under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"PERCENTAGE_FORMATTING\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The rule reads any static format string containing % anywhere, so a custom format that carries an escaped percent sign is treated as a percentage format and reported.\n- Only the exact three-part string passes. #,0.0% alone is reported, and so is the same string written with different spacing.\n- There is no visibility test. A hidden measure, and a measure on a hidden table, are reported on the same terms as a visible one.\n- Only the static format string is read, so a measure with a dynamic format string and no static one is never reported here.\n\nRead more: https://pbiplint.com/rules/percentage-formatting",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Cost\n\n\tmeasure 'Margin %' = DIVIDE(SUM('Sales'[Amount]) - SUM('Sales'[Cost]), SUM('Sales'[Amount]))\n\t\tformatString: 0.0%\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tcolumn Cost\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Cost\n\n\tmeasure 'Margin %' = DIVIDE(SUM('Sales'[Amount]) - SUM('Sales'[Cost]), SUM('Sales'[Amount]))\n\t\tformatString: #,0.0%;-#,0.0%;#,0.0%\n```\n\n### Why it matters\n\nPercentages formatted inconsistently end up side by side in the same report, so one card reads 12.3% while the next reads 12.34% or 12%, and the reader is left wondering whether the numbers disagree or only the formatting does. The three-part string this rule expects sets the positive, negative, and zero cases together, so a negative percentage keeps its sign and a thousands separator appears once values pass 1000%. Setting it on the measure fixes the presentation for every report that uses the model, rather than leaving each report author to format the visual by hand. This is house style rather than correctness: the rule enforces one convention, not the only workable one.\n\n### How to fix it\n\nUse the format string `#,0.0%;-#,0.0%;#,0.0%`. In Power BI Desktop, select the measure in the Data pane and paste the string into the Format box under Measure tools. In the TMDL file, set `formatString: #,0.0%;-#,0.0%;#,0.0%` under the measure. The three parts are the positive, negative, and zero cases in that order, which is why the string repeats itself: it says how each of the three is rendered rather than leaving two of them to a default.\n\n### When to ignore it\n\nA percentage that needs a different precision is the honest exception: a conversion rate people read to two decimals, or a completion figure that reads better as a whole number on a card. If that is the house standard, every percentage measure in the model fires and the rule is measuring the wrong convention, which is worth settling once for the whole model rather than card by card. What is not an exception is a single measure left at the client default because nobody chose a format for it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = PERCENTAGE_FORMATTING` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"PERCENTAGE_FORMATTING\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The rule reads any static format string containing `%` anywhere, so a custom format that carries an escaped percent sign is treated as a percentage format and reported.\n- Only the exact three-part string passes. `#,0.0%` alone is reported, and so is the same string written with different spacing.\n- There is no visibility test. A hidden measure, and a measure on a hidden table, are reported on the same terms as a visible one.\n- Only the static format string is read, so a measure with a dynamic format string and no static one is never reported here.\n\nRead more: https://pbiplint.com/rules/percentage-formatting",
  },
  PERSPECTIVES_WITH_NO_OBJECTS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nperspective 'Sales View'\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nperspective 'Sales View'\n\n\tperspectiveTable Sales\n\n\t\tperspectiveMeasure 'Total Sales'\n\nWhy it matters\n\nAn empty perspective still shows up in clients that offer perspectives, such as Excel, as a named view of the model that contains nothing. It is either an abandoned start or the remains of objects that were removed, and it leaves the next person asking what it was for.\n\nHow to fix it\n\nPower BI Desktop has no perspective editor, so the fix is in the file. A perspective is a perspective block of its own, and the objects it shows are perspectiveTable entries under it, with the columns, measures, and hierarchies it shows listed beneath each one. Add the tables the perspective should show, or delete its file from the perspectives folder and drop the matching ref perspective line from model.tmdl. Tabular Editor edits perspectives in a UI if you would rather tick boxes than edit the file.\n\nWhen to ignore it\n\nThere is no case for it. A perspective you have created and not yet filled is the one you want reported, because nothing else will tell you it is still empty, and an empty perspective in a published model offers a report author a view of the model with no fields in it.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = PERSPECTIVES_WITH_NO_OBJECTS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"PERSPECTIVES_WITH_NO_OBJECTS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The rule counts the perspectiveTable entries the perspective carries, not the objects they resolve to. A perspective that lists a table which was deleted is not empty and is not reported.\n- Power BI Desktop never writes perspectives, so this rule fires only on models built or edited somewhere else.\n\nRead more: https://pbiplint.com/rules/perspectives-with-no-objects",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nperspective 'Sales View'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nperspective 'Sales View'\n\n\tperspectiveTable Sales\n\n\t\tperspectiveMeasure 'Total Sales'\n```\n\n### Why it matters\n\nAn empty perspective still shows up in clients that offer perspectives, such as Excel, as a named view of the model that contains nothing. It is either an abandoned start or the remains of objects that were removed, and it leaves the next person asking what it was for.\n\n### How to fix it\n\nPower BI Desktop has no perspective editor, so the fix is in the file. A perspective is a `perspective` block of its own, and the objects it shows are `perspectiveTable` entries under it, with the columns, measures, and hierarchies it shows listed beneath each one. Add the tables the perspective should show, or delete its file from the `perspectives` folder and drop the matching `ref perspective` line from `model.tmdl`. Tabular Editor edits perspectives in a UI if you would rather tick boxes than edit the file.\n\n### When to ignore it\n\nThere is no case for it. A perspective you have created and not yet filled is the one you want reported, because nothing else will tell you it is still empty, and an empty perspective in a published model offers a report author a view of the model with no fields in it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = PERSPECTIVES_WITH_NO_OBJECTS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"PERSPECTIVES_WITH_NO_OBJECTS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The rule counts the `perspectiveTable` entries the perspective carries, not the objects they resolve to. A perspective that lists a table which was deleted is not empty and is not reported.\n- Power BI Desktop never writes perspectives, so this rule fires only on models built or edited somewhere else.\n\nRead more: https://pbiplint.com/rules/perspectives-with-no-objects",
  },
  PROVIDE_FORMAT_STRING_FOR_MEASURES: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nA measure with no format string is rendered with the client's default, which usually means no thousands separator and a decimal count that varies with the data, so the same measure can look different in two visuals on the same page. Setting the format on the measure fixes the presentation once for every report that will ever use the model, instead of leaving each report author to set it per visual and get it slightly wrong. Hidden measures and measures on hidden tables are not checked, because nothing displays them directly; a measure that has only a dynamic format string is also left alone.\n\nHow to fix it\n\nIn Power BI Desktop, select the measure in the Data pane and set Format under Measure tools. In the TMDL file, add formatString under the measure: #,0 for whole numbers, #,0.00 for decimals, a currency format such as $#,0.00, or #,0.0%;-#,0.0%;#,0.0% for percentages. Where the format depends on what the measure returns, a dynamic format string satisfies the rule as well: pick Dynamic in the Format list under Measure tools and write the expression in the formula bar, which the file records as a formatStringDefinition block under the measure.\n\nWhen to ignore it\n\nA measure that returns text has nothing to format. A label measure that builds a title, and a measure that returns a hex color for conditional formatting, are both reported here and neither has a number behind it. Everything else the rule reports is a visible number a reader will see, so the finding is usually worth the ten seconds it takes to clear.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = PROVIDE_FORMAT_STRING_FOR_MEASURES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"PROVIDE_FORMAT_STRING_FOR_MEASURES\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- A format string of nothing but spaces counts as no format string, so formatString: \" \" is reported.\n- A measure with only a dynamic format string passes here but fires INTEGER_FORMATTING, which reads the static format string alone.\n- Hidden measures, and measures on hidden tables, are skipped. INTEGER_FORMATTING skips neither.\n\nRead more: https://pbiplint.com/rules/provide-format-string-for-measures",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nA measure with no format string is rendered with the client's default, which usually means no thousands separator and a decimal count that varies with the data, so the same measure can look different in two visuals on the same page. Setting the format on the measure fixes the presentation once for every report that will ever use the model, instead of leaving each report author to set it per visual and get it slightly wrong. Hidden measures and measures on hidden tables are not checked, because nothing displays them directly; a measure that has only a dynamic format string is also left alone.\n\n### How to fix it\n\nIn Power BI Desktop, select the measure in the Data pane and set Format under Measure tools. In the TMDL file, add `formatString` under the measure: `#,0` for whole numbers, `#,0.00` for decimals, a currency format such as `$#,0.00`, or `#,0.0%;-#,0.0%;#,0.0%` for percentages. Where the format depends on what the measure returns, a dynamic format string satisfies the rule as well: pick Dynamic in the Format list under Measure tools and write the expression in the formula bar, which the file records as a `formatStringDefinition` block under the measure.\n\n### When to ignore it\n\nA measure that returns text has nothing to format. A label measure that builds a title, and a measure that returns a hex color for conditional formatting, are both reported here and neither has a number behind it. Everything else the rule reports is a visible number a reader will see, so the finding is usually worth the ten seconds it takes to clear.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = PROVIDE_FORMAT_STRING_FOR_MEASURES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"PROVIDE_FORMAT_STRING_FOR_MEASURES\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- A format string of nothing but spaces counts as no format string, so `formatString: \" \"` is reported.\n- A measure with only a dynamic format string passes here but fires `INTEGER_FORMATTING`, which reads the static format string alone.\n- Hidden measures, and measures on hidden tables, are skipped. `INTEGER_FORMATTING` skips neither.\n\nRead more: https://pbiplint.com/rules/provide-format-string-for-measures",
  },
  REDUCE_NUMBER_OF_CALCULATED_COLUMNS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Quantity\n\n\tcolumn 'Unit Price'\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: UnitPrice\n\n\tcolumn 'Line Total' = 'Sales'[Quantity] * 'Sales'[Unit Price]\n\t\tdataType: decimal\n\n\tcolumn 'Line Total Rounded' = ROUND('Sales'[Line Total], 0)\n\t\tdataType: decimal\n\n\tcolumn 'Order Year' = YEAR('Sales'[Order Date])\n\t\tdataType: int64\n\n\tcolumn 'Order Week' = WEEKNUM('Sales'[Order Date])\n\t\tdataType: int64\n\n\tcolumn 'Order Month Name' = FORMAT('Sales'[Order Date], \"MMMM\")\n\t\tdataType: string\n\n\tcolumn 'Quantity Band' = IF('Sales'[Quantity] > 10, \"Bulk\", \"Single\")\n\t\tdataType: string\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database(\"finance\", \"Warehouse\"), Sales = Source{[Item = \"Sales\"]}[Data] in Sales\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Quantity\n\n\tcolumn 'Unit Price'\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: UnitPrice\n\n\tcolumn 'Line Total'\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: LineTotal\n\n\tcolumn 'Line Total Rounded'\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: LineTotalRounded\n\n\tcolumn 'Order Year'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderYear\n\n\tcolumn 'Order Week'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderWeek\n\n\tcolumn 'Order Month Name'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderMonthName\n\n\tcolumn 'Quantity Band'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: QuantityBand\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database(\"finance\", \"Warehouse\"), Sales = Source{[Item = \"vwSalesEnriched\"]}[Data] in Sales\n\nWhy it matters\n\nA calculated column is computed after load, one row at a time, and stored without the compression the engine gets for a column it loaded from the source, so each one costs refresh time and memory out of proportion to its size. Five is a budget rather than a limit: past it, the model is usually doing in DAX what Power Query or the source would do once and better.\n\nHow to fix it\n\nMove the work upstream. In Power BI Desktop choose Transform data, select the query, and use Add Column, Custom Column, or one of the ready-made transforms such as Extract or Round, then delete the DAX column: right-click it in the Data pane and choose Delete from model, or remove its column Name = expression block from the table's TMDL file. Better still, add the expression to the view the query reads, where it computes once for every model that reads the view and folds into the refresh rather than running after it. Date parts are the common case and have a third home: year, month, and week belong on the date table, related to the fact table, rather than repeated on every fact row. Keep DAX calculated columns for the few cases that need the model, such as a value that depends on a measure or on a relationship.\n\nWhen to ignore it\n\nFive is somebody's round number, not a law, and a model can be perfectly healthy at eight. The judgment is what the columns cost, which the rule cannot see: six columns on a two-thousand-row dimension are free, and one on a hundred-million-row fact table is the thing to look at first. A column that genuinely needs the model is the other legitimate case: a value derived from a measure, or a flag that depends on a relationship, cannot be computed in Power Query at all, because the model does not exist yet when the query runs. Count how many of the columns are on large tables before deciding, and ignore the finding once the answer is none.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = REDUCE_NUMBER_OF_CALCULATED_COLUMNS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"REDUCE_NUMBER_OF_CALCULATED_COLUMNS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The threshold is strictly more than five, counted across every table in the model at once. Five columns is silent and the sixth reports the whole model.\n- A column counts as calculated when it carries a DAX expression of its own. The columns a calculated table produces carry none, so a model built from calculated tables can hold hundreds of columns without being reported here, although each of those tables is reported by REDUCE_USAGE_OF_CALCULATED_TABLES.\n- Nothing about the columns is weighed: not the table's size, not the column's cardinality, and not whether the expression is cheap. Six trivial flags on a lookup table read exactly as six expensive strings on a fact table.\n- The finding names the model and no column, so it cannot be ignored per column. In the files the columns are the lines that read column Name = ; in Power BI Desktop they carry the calculated-column icon in the Data pane.\n\nRead more: https://pbiplint.com/rules/reduce-number-of-calculated-columns",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Quantity\n\n\tcolumn 'Unit Price'\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: UnitPrice\n\n\tcolumn 'Line Total' = 'Sales'[Quantity] * 'Sales'[Unit Price]\n\t\tdataType: decimal\n\n\tcolumn 'Line Total Rounded' = ROUND('Sales'[Line Total], 0)\n\t\tdataType: decimal\n\n\tcolumn 'Order Year' = YEAR('Sales'[Order Date])\n\t\tdataType: int64\n\n\tcolumn 'Order Week' = WEEKNUM('Sales'[Order Date])\n\t\tdataType: int64\n\n\tcolumn 'Order Month Name' = FORMAT('Sales'[Order Date], \"MMMM\")\n\t\tdataType: string\n\n\tcolumn 'Quantity Band' = IF('Sales'[Quantity] > 10, \"Bulk\", \"Single\")\n\t\tdataType: string\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database(\"finance\", \"Warehouse\"), Sales = Source{[Item = \"Sales\"]}[Data] in Sales\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Quantity\n\n\tcolumn 'Unit Price'\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: UnitPrice\n\n\tcolumn 'Line Total'\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: LineTotal\n\n\tcolumn 'Line Total Rounded'\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: LineTotalRounded\n\n\tcolumn 'Order Year'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderYear\n\n\tcolumn 'Order Week'\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderWeek\n\n\tcolumn 'Order Month Name'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: OrderMonthName\n\n\tcolumn 'Quantity Band'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: QuantityBand\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database(\"finance\", \"Warehouse\"), Sales = Source{[Item = \"vwSalesEnriched\"]}[Data] in Sales\n```\n\n### Why it matters\n\nA calculated column is computed after load, one row at a time, and stored without the compression the engine gets for a column it loaded from the source, so each one costs refresh time and memory out of proportion to its size. Five is a budget rather than a limit: past it, the model is usually doing in DAX what Power Query or the source would do once and better.\n\n### How to fix it\n\nMove the work upstream. In Power BI Desktop choose Transform data, select the query, and use Add Column, Custom Column, or one of the ready-made transforms such as Extract or Round, then delete the DAX column: right-click it in the Data pane and choose Delete from model, or remove its `column Name = expression` block from the table's TMDL file. Better still, add the expression to the view the query reads, where it computes once for every model that reads the view and folds into the refresh rather than running after it. Date parts are the common case and have a third home: year, month, and week belong on the date table, related to the fact table, rather than repeated on every fact row. Keep DAX calculated columns for the few cases that need the model, such as a value that depends on a measure or on a relationship.\n\n### When to ignore it\n\nFive is somebody's round number, not a law, and a model can be perfectly healthy at eight. The judgment is what the columns cost, which the rule cannot see: six columns on a two-thousand-row dimension are free, and one on a hundred-million-row fact table is the thing to look at first. A column that genuinely needs the model is the other legitimate case: a value derived from a measure, or a flag that depends on a relationship, cannot be computed in Power Query at all, because the model does not exist yet when the query runs. Count how many of the columns are on large tables before deciding, and ignore the finding once the answer is none.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REDUCE_NUMBER_OF_CALCULATED_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"REDUCE_NUMBER_OF_CALCULATED_COLUMNS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The threshold is strictly more than five, counted across every table in the model at once. Five columns is silent and the sixth reports the whole model.\n- A column counts as calculated when it carries a DAX expression of its own. The columns a calculated table produces carry none, so a model built from calculated tables can hold hundreds of columns without being reported here, although each of those tables is reported by `REDUCE_USAGE_OF_CALCULATED_TABLES`.\n- Nothing about the columns is weighed: not the table's size, not the column's cardinality, and not whether the expression is cheap. Six trivial flags on a lookup table read exactly as six expensive strings on a fact table.\n- The finding names the model and no column, so it cannot be ignored per column. In the files the columns are the lines that read `column Name = `; in Power BI Desktop they carry the calculated-column icon in the Data pane.\n\nRead more: https://pbiplint.com/rules/reduce-number-of-calculated-columns",
  },
  REDUCE_USAGE_OF_CALCULATED_COLUMNS_THAT_USE_THE_RELATED_FUNCTION: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tcolumn Category = RELATED('Product'[Category])\n\t\tdataType: string\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nWhy it matters\n\nRELATED in a calculated column copies a value from the one side of a relationship onto every row of the many side. That is a lookup the source can do with a join, or Power Query with a merge, at load time and often folded to the source. Done in DAX it is computed row by row after load and stored without full compression, and the copied column then duplicates a dimension attribute, which REMOVE_REDUNDANT_COLUMNS_IN_RELATED_TABLES also flags.\n\nHow to fix it\n\nMost of the time the column does not need to exist. The value is already on the dimension and the relationship already reaches it, so build the visual on the dimension's column and delete the copy: right-click it in Power BI Desktop's Data pane and choose Delete from model, or remove its column Name = expression block from the table's TMDL file, which is what the example above does. Where the value genuinely has to sit on the fact table, because a measure filters by it at row grain or a composite key needs it, bring it in where the rows are loaded rather than after: in Transform data use Merge Queries against the dimension query and expand the one column you want, or add the join to the view the query reads, and the column arrives compressed like any other loaded column. Where the value is only wanted inside one measure, call RELATED there instead, since a measure computes at query time and stores nothing.\n\nWhen to ignore it\n\nA small table is the clean exception. The cost is per row, so RELATED on a dimension of a few thousand rows is not worth an edit, while the same expression on a fact table of fifty million is the reason the model is large. A column that cannot be merged upstream is the other case: where the fact table and the dimension come from different sources and the merge would break query folding, doing the lookup in DAX after load can be the cheaper of the two. Check the row count and check whether the merge folds before rewriting anything. What is not a legitimate exception is a copy of a dimension attribute on a large fact table that exists because the field list was easier to browse that way.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = REDUCE_USAGE_OF_CALCULATED_COLUMNS_THAT_USE_THE_RELATED_FUNCTION under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"REDUCE_USAGE_OF_CALCULATED_COLUMNS_THAT_USE_THE_RELATED_FUNCTION\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The match is case-insensitive and allows whitespace before the parenthesis, so related ( counts as much as RELATED(.\n- RELATEDTABLE( is not matched, because only whitespace may stand between the name and the parenthesis.\n- Only calculated columns are in scope. The same call in a measure, a calculation item, or a calculated table's expression is not reported here.\n- The test reads the expression as text, so a RELATED call inside a comment or a quoted string counts, and a lookup written with LOOKUPVALUE instead does not.\n\nRead more: https://pbiplint.com/rules/reduce-usage-of-calculated-columns-that-use-the-related-function",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\n\tcolumn Category = RELATED('Product'[Category])\n\t\tdataType: string\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn Category\n\t\tdataType: string\n\t\tsourceColumn: Category\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n### Why it matters\n\nRELATED in a calculated column copies a value from the one side of a relationship onto every row of the many side. That is a lookup the source can do with a join, or Power Query with a merge, at load time and often folded to the source. Done in DAX it is computed row by row after load and stored without full compression, and the copied column then duplicates a dimension attribute, which `REMOVE_REDUNDANT_COLUMNS_IN_RELATED_TABLES` also flags.\n\n### How to fix it\n\nMost of the time the column does not need to exist. The value is already on the dimension and the relationship already reaches it, so build the visual on the dimension's column and delete the copy: right-click it in Power BI Desktop's Data pane and choose Delete from model, or remove its `column Name = expression` block from the table's TMDL file, which is what the example above does. Where the value genuinely has to sit on the fact table, because a measure filters by it at row grain or a composite key needs it, bring it in where the rows are loaded rather than after: in Transform data use Merge Queries against the dimension query and expand the one column you want, or add the join to the view the query reads, and the column arrives compressed like any other loaded column. Where the value is only wanted inside one measure, call RELATED there instead, since a measure computes at query time and stores nothing.\n\n### When to ignore it\n\nA small table is the clean exception. The cost is per row, so RELATED on a dimension of a few thousand rows is not worth an edit, while the same expression on a fact table of fifty million is the reason the model is large. A column that cannot be merged upstream is the other case: where the fact table and the dimension come from different sources and the merge would break query folding, doing the lookup in DAX after load can be the cheaper of the two. Check the row count and check whether the merge folds before rewriting anything. What is not a legitimate exception is a copy of a dimension attribute on a large fact table that exists because the field list was easier to browse that way.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REDUCE_USAGE_OF_CALCULATED_COLUMNS_THAT_USE_THE_RELATED_FUNCTION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"REDUCE_USAGE_OF_CALCULATED_COLUMNS_THAT_USE_THE_RELATED_FUNCTION\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The match is case-insensitive and allows whitespace before the parenthesis, so `related (` counts as much as `RELATED(`.\n- `RELATEDTABLE(` is not matched, because only whitespace may stand between the name and the parenthesis.\n- Only calculated columns are in scope. The same call in a measure, a calculation item, or a calculated table's expression is not reported here.\n- The test reads the expression as text, so a RELATED call inside a comment or a quoted string counts, and a lookup written with LOOKUPVALUE instead does not.\n\nRead more: https://pbiplint.com/rules/reduce-usage-of-calculated-columns-that-use-the-related-function",
  },
  REDUCE_USAGE_OF_CALCULATED_TABLES: {
    text: "Example\n\nFires the rule\n\ntable 'Product Category'\n\tcolumn Category\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: [Category]\n\n\tpartition 'Product Category' = calculated\n\t\tmode: import\n\t\tsource = DISTINCT('Product'[Category])\n\nAfter the fix\n\ntable 'Product Category'\n\tcolumn Category\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Category\n\n\tpartition 'Product Category' = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database(\"finance\", \"Warehouse\"), Category = Source{[Item = \"vwProductCategory\"]}[Data] in Category\n\nWhy it matters\n\nA calculated table is rebuilt from DAX after every refresh, holds a copy of data that exists somewhere else, and is invisible to the source's lineage and to every other model. When two models need the same table, each rebuilds it its own way and they drift. A date table is the usual exception, and even there a shared table in the source or in a dataflow serves every model the same way.\n\nHow to fix it\n\nLoad the table instead of computing it. In Power BI Desktop, choose Transform data and build the query there, or better, point it at a view in the source so every model that needs the table gets the same one; then right-click the calculated table in the Data pane and choose Delete from model. In the TMDL file the difference is in the partition's declaration: partition Name = calculated with a DAX expression becomes partition Name = m with a Power Query expression, and that declaration is the only thing the rule reads. Where the calculated table came from Auto date/time rather than from you, the way to remove it is to clear that option under Options, Current file, Data Load, not to delete the table. Where a calculated table stays, keep it small and put the reason in the table's description, which is the Description box in the Properties pane.\n\nWhen to ignore it\n\nSeveral of these tables are features rather than choices. A field parameter and a what-if parameter are both calculated tables that Power BI Desktop writes for you when you use New parameter, and deleting either one breaks the report that uses it. A disconnected table of thresholds or scenario labels, small and static, is in the same position: there is nothing upstream to load it from and nothing to gain by inventing one. A bridge table built with DISTINCT over two fact tables is the judgment call worth making deliberately, because building it in the source is usually better but is not always worth the round trip through another team. What is not a legitimate exception is a large table built with DAX because the source was inconvenient, which is the case the rule is for, and the hidden tables Auto date/time generates, which should be turned off rather than ignored.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = REDUCE_USAGE_OF_CALCULATED_TABLES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"REDUCE_USAGE_OF_CALCULATED_TABLES\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- A table counts as calculated when any of its partitions declares a calculated source, whatever its mode line says. One calculated partition beside several Power Query ones is enough.\n- Calculation groups are classified as calculation group tables rather than calculated tables, so they are never reported here even though they hold DAX.\n- There is no threshold despite the name. One calculated table is reported exactly as twenty are, and the rule has no way to tell a two-row parameter table from a copy of a fact table.\n- With Auto date/time on, each hidden LocalDateTable is a calculated table and fires here as well as REMOVE_AUTO-DATE_TABLE. Turning the option off clears both.\n\nRead more: https://pbiplint.com/rules/reduce-usage-of-calculated-tables",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable 'Product Category'\n\tcolumn Category\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: [Category]\n\n\tpartition 'Product Category' = calculated\n\t\tmode: import\n\t\tsource = DISTINCT('Product'[Category])\n```\n\n**After the fix**\n\n```tmdl\ntable 'Product Category'\n\tcolumn Category\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Category\n\n\tpartition 'Product Category' = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database(\"finance\", \"Warehouse\"), Category = Source{[Item = \"vwProductCategory\"]}[Data] in Category\n```\n\n### Why it matters\n\nA calculated table is rebuilt from DAX after every refresh, holds a copy of data that exists somewhere else, and is invisible to the source's lineage and to every other model. When two models need the same table, each rebuilds it its own way and they drift. A date table is the usual exception, and even there a shared table in the source or in a dataflow serves every model the same way.\n\n### How to fix it\n\nLoad the table instead of computing it. In Power BI Desktop, choose Transform data and build the query there, or better, point it at a view in the source so every model that needs the table gets the same one; then right-click the calculated table in the Data pane and choose Delete from model. In the TMDL file the difference is in the partition's declaration: `partition Name = calculated` with a DAX expression becomes `partition Name = m` with a Power Query expression, and that declaration is the only thing the rule reads. Where the calculated table came from Auto date/time rather than from you, the way to remove it is to clear that option under Options, Current file, Data Load, not to delete the table. Where a calculated table stays, keep it small and put the reason in the table's description, which is the Description box in the Properties pane.\n\n### When to ignore it\n\nSeveral of these tables are features rather than choices. A field parameter and a what-if parameter are both calculated tables that Power BI Desktop writes for you when you use New parameter, and deleting either one breaks the report that uses it. A disconnected table of thresholds or scenario labels, small and static, is in the same position: there is nothing upstream to load it from and nothing to gain by inventing one. A bridge table built with DISTINCT over two fact tables is the judgment call worth making deliberately, because building it in the source is usually better but is not always worth the round trip through another team. What is not a legitimate exception is a large table built with DAX because the source was inconvenient, which is the case the rule is for, and the hidden tables Auto date/time generates, which should be turned off rather than ignored.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REDUCE_USAGE_OF_CALCULATED_TABLES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"REDUCE_USAGE_OF_CALCULATED_TABLES\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- A table counts as calculated when any of its partitions declares a `calculated` source, whatever its `mode` line says. One calculated partition beside several Power Query ones is enough.\n- Calculation groups are classified as calculation group tables rather than calculated tables, so they are never reported here even though they hold DAX.\n- There is no threshold despite the name. One calculated table is reported exactly as twenty are, and the rule has no way to tell a two-row parameter table from a copy of a fact table.\n- With Auto date/time on, each hidden LocalDateTable is a calculated table and fires here as well as `REMOVE_AUTO-DATE_TABLE`. Turning the option off clears both.\n\nRead more: https://pbiplint.com/rules/reduce-usage-of-calculated-tables",
  },
  "REDUCE_USAGE_OF_LONG-LENGTH_COLUMNS_WITH_HIGH_CARDINALITY": {
    text: "Why it matters\n\nThe engine stores each distinct text value once in a dictionary and encodes the rows against it. Long unique strings, such as comments, descriptions, or URLs with query strings, defeat that: the dictionary grows as large as the data, memory and refresh time follow, and every visual that touches the column pays to decode it. Such a column is usually never shown in a visual anyway.\n\nHow to fix it\n\nFind the columns first. In Power BI Desktop's DAX query view, run a query such as EVALUATE ROW(\"long rows\", COUNTROWS(FILTER('Sales', LEN('Sales'[Comment]) > 100)), \"distinct\", DISTINCTCOUNT('Sales'[Comment])) against each text column you suspect. Then deal with the ones that come back large. The cheapest answer is not to load the column: choose Transform data, select the query, and use Choose Columns or Remove Columns, or drop it from the select list of the view the query reads. Where a report does show the text, shorten it where it is loaded, with Extract, First Characters under the Transform tab, or keep the full text in a separate detail table that a drillthrough page reads, so the wide column is never scanned by a summary visual. Where the text is a code or a URL with a repeating prefix, splitting the prefix into its own column gives the dictionary something to compress. DAX Studio's VertiPaq Analyzer reports every column's size and cardinality at once if you would rather start from a list than a query per column, and if you already use Tabular Editor, the walkthrough under Links loads the same statistics into its Best Practice Analyzer, which can then run this rule directly.\n\nQuirks\n\n- The source rule reads a LongLengthRowCount annotation that a Tabular Editor script writes onto the model after loading VertiPaq statistics. A project's files never carry that annotation, which is why pbiplint lists the rule rather than running it.\n- Despite the name, cardinality is not in the condition. Only the number of rows holding a value longer than 100 characters is tested, so a column whose million rows all hold the same long string, which compresses perfectly, meets it.\n- The threshold is a flat count of rows, not a share of the table. A million-row column whose values are all 99 characters long is never reported, and a 400,000-row table of kilobyte strings is not reported either.\n\nRead more: https://pbiplint.com/rules/reduce-usage-of-long-length-columns-with-high-cardinality",
    markdown:
      "### Why it matters\n\nThe engine stores each distinct text value once in a dictionary and encodes the rows against it. Long unique strings, such as comments, descriptions, or URLs with query strings, defeat that: the dictionary grows as large as the data, memory and refresh time follow, and every visual that touches the column pays to decode it. Such a column is usually never shown in a visual anyway.\n\n### How to fix it\n\nFind the columns first. In Power BI Desktop's DAX query view, run a query such as `EVALUATE ROW(\"long rows\", COUNTROWS(FILTER('Sales', LEN('Sales'[Comment]) > 100)), \"distinct\", DISTINCTCOUNT('Sales'[Comment]))` against each text column you suspect. Then deal with the ones that come back large. The cheapest answer is not to load the column: choose Transform data, select the query, and use Choose Columns or Remove Columns, or drop it from the select list of the view the query reads. Where a report does show the text, shorten it where it is loaded, with Extract, First Characters under the Transform tab, or keep the full text in a separate detail table that a drillthrough page reads, so the wide column is never scanned by a summary visual. Where the text is a code or a URL with a repeating prefix, splitting the prefix into its own column gives the dictionary something to compress. DAX Studio's VertiPaq Analyzer reports every column's size and cardinality at once if you would rather start from a list than a query per column, and if you already use Tabular Editor, the walkthrough under Links loads the same statistics into its Best Practice Analyzer, which can then run this rule directly.\n\n### Quirks\n\n- The source rule reads a `LongLengthRowCount` annotation that a Tabular Editor script writes onto the model after loading VertiPaq statistics. A project's files never carry that annotation, which is why pbiplint lists the rule rather than running it.\n- Despite the name, cardinality is not in the condition. Only the number of rows holding a value longer than 100 characters is tested, so a column whose million rows all hold the same long string, which compresses perfectly, meets it.\n- The threshold is a flat count of rows, not a share of the table. A million-row column whose values are all 99 characters long is never reported, and a 400,000-row table of kilobyte strings is not reported either.\n\nRead more: https://pbiplint.com/rules/reduce-usage-of-long-length-columns-with-high-cardinality",
  },
  RELATIONSHIP_COLUMNS_SAME_DATA_TYPE: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: string\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nWhy it matters\n\nThe engine relates columns by value, and when the types differ it converts one side for every query. A text key on one side and a whole number on the other works until a value like 007 meets 7, at which point rows quietly fall into the blank member. Matching types remove both the conversion cost and the surprise.\n\nHow to fix it\n\nSet the two columns to the same type, and prefer a whole number for a key. In Power BI Desktop there are two places to do it: Column tools, Data type on the selected column, which changes the type on the model, or Transform data, where a Changed Type step in Power Query gets the type right before the data is loaded and keeps it right on every refresh. Power Query is the better of the two when the source is the reason the types differ. In the TMDL file the property is dataType on each column. Converting a text key to a whole number fails at refresh on any value that is not a number, so look for padded keys such as 007 first and strip the padding in the same Power Query step.\n\nWhen to ignore it\n\nA column whose declaration carries no dataType at all compares as having none, so a relationship onto a calculated column that was written without the property is reported although both sides may hold the same type once the model is loaded. That is the one finding here worth reading twice, and the answer to it is to write the property rather than to change a type. Where both types are written and they differ, there is nothing to ignore.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = RELATIONSHIP_COLUMNS_SAME_DATA_TYPE under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"RELATIONSHIP_COLUMNS_SAME_DATA_TYPE\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Both sides have to resolve to a column the model declares. A relationship naming a table or a column that does not exist is skipped, so a typo in fromColumn or toColumn hides the relationship from this rule.\n- The comparison is on the declared dataType, ignoring letter case. A column with no dataType line compares as having none, and so differs from any column that has one.\n- Only the declared type is compared, never the values. Two text keys that will never match, one padded and one not, pass the rule.\n\nRead more: https://pbiplint.com/rules/relationship-columns-same-data-type",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: string\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n### Why it matters\n\nThe engine relates columns by value, and when the types differ it converts one side for every query. A text key on one side and a whole number on the other works until a value like 007 meets 7, at which point rows quietly fall into the blank member. Matching types remove both the conversion cost and the surprise.\n\n### How to fix it\n\nSet the two columns to the same type, and prefer a whole number for a key. In Power BI Desktop there are two places to do it: Column tools, Data type on the selected column, which changes the type on the model, or Transform data, where a Changed Type step in Power Query gets the type right before the data is loaded and keeps it right on every refresh. Power Query is the better of the two when the source is the reason the types differ. In the TMDL file the property is `dataType` on each column. Converting a text key to a whole number fails at refresh on any value that is not a number, so look for padded keys such as `007` first and strip the padding in the same Power Query step.\n\n### When to ignore it\n\nA column whose declaration carries no `dataType` at all compares as having none, so a relationship onto a calculated column that was written without the property is reported although both sides may hold the same type once the model is loaded. That is the one finding here worth reading twice, and the answer to it is to write the property rather than to change a type. Where both types are written and they differ, there is nothing to ignore.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = RELATIONSHIP_COLUMNS_SAME_DATA_TYPE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"RELATIONSHIP_COLUMNS_SAME_DATA_TYPE\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Both sides have to resolve to a column the model declares. A relationship naming a table or a column that does not exist is skipped, so a typo in `fromColumn` or `toColumn` hides the relationship from this rule.\n- The comparison is on the declared `dataType`, ignoring letter case. A column with no `dataType` line compares as having none, and so differs from any column that has one.\n- Only the declared type is compared, never the values. Two text keys that will never match, one padded and one not, pass the rule.\n\nRead more: https://pbiplint.com/rules/relationship-columns-same-data-type",
  },
  RELATIONSHIP_COLUMNS_SHOULD_BE_OF_INTEGER_DATA_TYPE: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Customer Code'\n\t\tdataType: string\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer Code\n\ntable Customer\n\tcolumn 'Customer Code'\n\t\tdataType: string\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer Code\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer Code'\n\ttoColumn: Customer.'Customer Code'\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Customer Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer Key\n\ntable Customer\n\tcolumn 'Customer Key'\n\t\tdataType: int64\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer Key\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer Key'\n\ttoColumn: Customer.'Customer Key'\n\nWhy it matters\n\nA relationship is evaluated by matching values, and whole numbers match fastest and compress smallest. Text keys carry their dictionary into every join, and DateTime keys work but store more than an integer date key would. On the largest fact tables the key columns are often the biggest, so the choice shows up in memory as much as in query time.\n\nHow to fix it\n\nThe type has to change on both ends, so the fix belongs upstream of the model. Where the source already has an integer surrogate key, load it instead of the natural key: in Power BI Desktop, choose Transform data, add the key column to the query, and drop the text one. Where there is no integer key, add one in the source view or build it with a merge in Power Query against the dimension. The Data type box under Column tools changes a column's type in place on an import model, which is worth using only when the values are already digits held as text. Change both ends in the same edit, because a relationship whose two columns end up with different types is a finding of its own.\n\nWhen to ignore it\n\nA date relationship on a DateTime column is the common one to leave: it is what Power BI Desktop builds when you connect a fact table to a date table, it works, and moving the model to an integer date key such as 20260904 is a project rather than a fix. A small dimension is the second: a few thousand rows keyed on a short text code cost almost nothing, and a surrogate key adds a column to build and maintain for a saving nobody will measure. The finding earns its keep on the fact tables, where the key column is one of the widest things in the model.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = RELATIONSHIP_COLUMNS_SHOULD_BE_OF_INTEGER_DATA_TYPE under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"RELATIONSHIP_COLUMNS_SHOULD_BE_OF_INTEGER_DATA_TYPE\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Every date relationship on a DateTime column is reported. That is what the source rule does, and it is why a model whose date table is keyed on a DateTime column collects a finding for each end of every date relationship.\n- Decimal and double columns are reported too. The test is for the whole number type alone, not for numeric types in general.\n- Both ends of a relationship are read, so converting one end and leaving the other clears half the findings.\n- Inactive relationships count, and so do relationships whose cross-filter direction is both.\n\nRead more: https://pbiplint.com/rules/relationship-columns-should-be-of-integer-data-type",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Customer Code'\n\t\tdataType: string\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer Code\n\ntable Customer\n\tcolumn 'Customer Code'\n\t\tdataType: string\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer Code\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer Code'\n\ttoColumn: Customer.'Customer Code'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Customer Key'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer Key\n\ntable Customer\n\tcolumn 'Customer Key'\n\t\tdataType: int64\n\t\tisKey\n\t\tsummarizeBy: none\n\t\tsourceColumn: Customer Key\n\nrelationship Sales_Customer\n\tfromColumn: Sales.'Customer Key'\n\ttoColumn: Customer.'Customer Key'\n```\n\n### Why it matters\n\nA relationship is evaluated by matching values, and whole numbers match fastest and compress smallest. Text keys carry their dictionary into every join, and DateTime keys work but store more than an integer date key would. On the largest fact tables the key columns are often the biggest, so the choice shows up in memory as much as in query time.\n\n### How to fix it\n\nThe type has to change on both ends, so the fix belongs upstream of the model. Where the source already has an integer surrogate key, load it instead of the natural key: in Power BI Desktop, choose Transform data, add the key column to the query, and drop the text one. Where there is no integer key, add one in the source view or build it with a merge in Power Query against the dimension. The Data type box under Column tools changes a column's type in place on an import model, which is worth using only when the values are already digits held as text. Change both ends in the same edit, because a relationship whose two columns end up with different types is a finding of its own.\n\n### When to ignore it\n\nA date relationship on a DateTime column is the common one to leave: it is what Power BI Desktop builds when you connect a fact table to a date table, it works, and moving the model to an integer date key such as 20260904 is a project rather than a fix. A small dimension is the second: a few thousand rows keyed on a short text code cost almost nothing, and a surrogate key adds a column to build and maintain for a saving nobody will measure. The finding earns its keep on the fact tables, where the key column is one of the widest things in the model.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = RELATIONSHIP_COLUMNS_SHOULD_BE_OF_INTEGER_DATA_TYPE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"RELATIONSHIP_COLUMNS_SHOULD_BE_OF_INTEGER_DATA_TYPE\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Every date relationship on a DateTime column is reported. That is what the source rule does, and it is why a model whose date table is keyed on a DateTime column collects a finding for each end of every date relationship.\n- Decimal and double columns are reported too. The test is for the whole number type alone, not for numeric types in general.\n- Both ends of a relationship are read, so converting one end and leaving the other clears half the findings.\n- Inactive relationships count, and so do relationships whose cross-filter direction is both.\n\nRead more: https://pbiplint.com/rules/relationship-columns-should-be-of-integer-data-type",
  },
  "REMOVE_AUTO-DATE_TABLE": {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable LocalDateTable_8f2c1b4e\n\tisHidden\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: [Date]\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: [Year]\n\n\tpartition LocalDateTable_8f2c1b4e = calculated\n\t\tmode: import\n\t\tsource = Calendar(Date(Year(MIN('Sales'[Order Date])), 1, 1), Date(Year(MAX('Sales'[Order Date])), 12, 31))\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Date\n\tdataCategory: Time\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n\nWhy it matters\n\nWith Auto date/time on, Power BI Desktop creates a hidden calculated date table for every date column in the model, each with its own year, quarter, month, and day hierarchy. A model with a dozen date columns carries a dozen hidden tables, all rebuilt on every refresh, and none of them can be extended with fiscal periods or holidays or shared between fact tables. One real date table does everything they do, once.\n\nHow to fix it\n\nIn Power BI Desktop, open File, Options and settings, Options, then Current file, Data Load, and clear Auto date/time. Desktop deletes the hidden tables and the variations that point at them when the file is saved, so the table LocalDateTable_... blocks leave the project's TMDL files on the next save. The option itself is recorded on the model as annotation __PBI_TimeIntelligenceEnabled, which Desktop writes and clears for you rather than a property to edit by hand, and deleting the table blocks yourself without clearing the option only invites Desktop to write them again. Then give the model a calendar of its own: add a date table, relate each fact table's date column to it, and mark it with Mark as date table under Table tools, which writes dataCategory: Time on the table and isKey on its date column. Report authors lose the automatic date hierarchy under each date column when the option goes off, so expect to rebuild the visuals that used one against the new table's Year, Quarter, and Month columns.\n\nWhen to ignore it\n\nThere is no lasting exception. These tables are not something a modeler chose, they are what Power BI Desktop falls back to, and every one of them is replaced by the single calendar the model should have anyway. The one honest reason to leave a finding for now is sequencing: in a report with many visuals built on the automatic date hierarchies, clearing the option breaks all of them at once, so the calendar goes in first, the visuals move across, and the option goes off last. That is a plan with a date on it rather than a decision to ignore the rule.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = REMOVE_AUTO-DATE_TABLE under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"REMOVE_AUTO-DATE_TABLE\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The table has to be a calculated table as well as carry the name. A loaded table someone called DateTableTemplate_Old is not reported.\n- The name test is case-sensitive and is a prefix, not a substring, so localdatetable_1 is not reported and neither is a table whose name merely contains the prefix further in.\n- Only these two names are known. A hidden calendar built by hand, or by another tool under another name, is invisible to this rule.\n- DateTableTemplate_ is the template table Desktop keeps; LocalDateTable_ is one table per date column. Both prefixes are reported, so a model with many date columns collects a finding for each of its hidden calendars.\n\nRead more: https://pbiplint.com/rules/remove-auto-date-table",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable LocalDateTable_8f2c1b4e\n\tisHidden\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: [Date]\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: [Year]\n\n\tpartition LocalDateTable_8f2c1b4e = calculated\n\t\tmode: import\n\t\tsource = Calendar(Date(Year(MIN('Sales'[Order Date])), 1, 1), Date(Year(MAX('Sales'[Order Date])), 12, 31))\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order Date'\n\t\tdataType: dateTime\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: OrderDate\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Date\n\tdataCategory: Time\n\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tformatString: mm/dd/yyyy\n\t\tsourceColumn: Date\n\n\tcolumn Year\n\t\tdataType: int64\n\t\tsummarizeBy: none\n\t\tsourceColumn: Year\n```\n\n### Why it matters\n\nWith Auto date/time on, Power BI Desktop creates a hidden calculated date table for every date column in the model, each with its own year, quarter, month, and day hierarchy. A model with a dozen date columns carries a dozen hidden tables, all rebuilt on every refresh, and none of them can be extended with fiscal periods or holidays or shared between fact tables. One real date table does everything they do, once.\n\n### How to fix it\n\nIn Power BI Desktop, open File, Options and settings, Options, then Current file, Data Load, and clear Auto date/time. Desktop deletes the hidden tables and the variations that point at them when the file is saved, so the `table LocalDateTable_...` blocks leave the project's TMDL files on the next save. The option itself is recorded on the model as `annotation __PBI_TimeIntelligenceEnabled`, which Desktop writes and clears for you rather than a property to edit by hand, and deleting the table blocks yourself without clearing the option only invites Desktop to write them again. Then give the model a calendar of its own: add a date table, relate each fact table's date column to it, and mark it with Mark as date table under Table tools, which writes `dataCategory: Time` on the table and `isKey` on its date column. Report authors lose the automatic date hierarchy under each date column when the option goes off, so expect to rebuild the visuals that used one against the new table's Year, Quarter, and Month columns.\n\n### When to ignore it\n\nThere is no lasting exception. These tables are not something a modeler chose, they are what Power BI Desktop falls back to, and every one of them is replaced by the single calendar the model should have anyway. The one honest reason to leave a finding for now is sequencing: in a report with many visuals built on the automatic date hierarchies, clearing the option breaks all of them at once, so the calendar goes in first, the visuals move across, and the option goes off last. That is a plan with a date on it rather than a decision to ignore the rule.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REMOVE_AUTO-DATE_TABLE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"REMOVE_AUTO-DATE_TABLE\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The table has to be a calculated table as well as carry the name. A loaded table someone called DateTableTemplate_Old is not reported.\n- The name test is case-sensitive and is a prefix, not a substring, so `localdatetable_1` is not reported and neither is a table whose name merely contains the prefix further in.\n- Only these two names are known. A hidden calendar built by hand, or by another tool under another name, is invisible to this rule.\n- DateTableTemplate_ is the template table Desktop keeps; LocalDateTable_ is one table per date column. Both prefixes are reported, so a model with many date columns collects a finding for each of its hidden calendars.\n\nRead more: https://pbiplint.com/rules/remove-auto-date-table",
  },
  REMOVE_DATA_SOURCES_NOT_REFERENCED_BY_ANY_PARTITIONS: {
    text: 'Example\n\nFires the rule\n\ndataSource \'Legacy SQL\' = provider\n\tconnectionString: Data Source=contoso;Initial Catalog=Warehouse\n\timpersonationMode: impersonateServiceAccount\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database("contoso", "Sales") in Source\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database("contoso", "Sales") in Source\n\nWhy it matters\n\nAn unused data source is a connection string, and usually a credential, that the model still asks to have configured on every deployment, so the service keeps prompting for credentials to a source nothing reads. It is a leftover from a migration or a source that was replaced.\n\nHow to fix it\n\nDelete the data source. In the project it is a dataSource block, usually in a file of its own under the dataSources folder: remove the file and the matching ref line in model.tmdl, or delete the block where it sits. Power BI Desktop does not show data sources, and Transform data, Data source settings lists the sources the queries name rather than these declarations, so the file is the place to do it. If the source is still wanted, point a partition at it instead, with dataSource: under the partition\'s source block.\n\nWhen to ignore it\n\nA model whose partitions are created after it is deployed, by a pipeline or a script that binds them to a source the files do not yet name, keeps the declaration on purpose, and the finding on it is noise. So is a source you have just added and are about to wire up. Outside those, a data source nothing reads is a leftover, and the credential prompt it produces on every deployment is the cost of keeping it.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = REMOVE_DATA_SOURCES_NOT_REFERENCED_BY_ANY_PARTITIONS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set "REMOVE_DATA_SOURCES_NOT_REFERENCED_BY_ANY_PARTITIONS": "off" under rules in pbiplint.config.json.\n\nQuirks\n\n- Tabular Editor 3 CLI 0.5.2 did not report this rule when loading from TMDL, although it did from .bim; pbiplint follows the rule text.\n- Power BI Desktop never writes data sources, so this rule matters only for hand-built or migrated models.\n- The text test is a plain substring match on each partition\'s query or M text, and letter case has to agree. A data source whose name happens to appear in that text, even inside a comment or inside a longer name, counts as referenced, and a name the partition spells with different capitalization does not match at all.\n- The source rule searches each table\'s source expression as well as every partition\'s query. pbiplint reads the partitions for both, since that is where a TMDL file keeps the text.\n\nRead more: https://pbiplint.com/rules/remove-data-sources-not-referenced-by-any-partitions',
    markdown:
      '### Example\n\n**Fires the rule**\n\n```tmdl\ndataSource \'Legacy SQL\' = provider\n\tconnectionString: Data Source=contoso;Initial Catalog=Warehouse\n\timpersonationMode: impersonateServiceAccount\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database("contoso", "Sales") in Source\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tpartition Sales = m\n\t\tmode: import\n\t\tsource = let Source = Sql.Database("contoso", "Sales") in Source\n```\n\n### Why it matters\n\nAn unused data source is a connection string, and usually a credential, that the model still asks to have configured on every deployment, so the service keeps prompting for credentials to a source nothing reads. It is a leftover from a migration or a source that was replaced.\n\n### How to fix it\n\nDelete the data source. In the project it is a `dataSource` block, usually in a file of its own under the `dataSources` folder: remove the file and the matching `ref` line in `model.tmdl`, or delete the block where it sits. Power BI Desktop does not show data sources, and Transform data, Data source settings lists the sources the queries name rather than these declarations, so the file is the place to do it. If the source is still wanted, point a partition at it instead, with `dataSource:` under the partition\'s `source` block.\n\n### When to ignore it\n\nA model whose partitions are created after it is deployed, by a pipeline or a script that binds them to a source the files do not yet name, keeps the declaration on purpose, and the finding on it is noise. So is a source you have just added and are about to wire up. Outside those, a data source nothing reads is a leftover, and the credential prompt it produces on every deployment is the cost of keeping it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REMOVE_DATA_SOURCES_NOT_REFERENCED_BY_ANY_PARTITIONS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REMOVE_DATA_SOURCES_NOT_REFERENCED_BY_ANY_PARTITIONS": "off"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Tabular Editor 3 CLI 0.5.2 did not report this rule when loading from TMDL, although it did from .bim; pbiplint follows the rule text.\n- Power BI Desktop never writes data sources, so this rule matters only for hand-built or migrated models.\n- The text test is a plain substring match on each partition\'s query or M text, and letter case has to agree. A data source whose name happens to appear in that text, even inside a comment or inside a longer name, counts as referenced, and a name the partition spells with different capitalization does not match at all.\n- The source rule searches each table\'s source expression as well as every partition\'s query. pbiplint reads the partitions for both, since that is where a TMDL file keeps the text.\n\nRead more: https://pbiplint.com/rules/remove-data-sources-not-referenced-by-any-partitions',
  },
  REMOVE_REDUNDANT_COLUMNS_IN_RELATED_TABLES: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nWhy it matters\n\nA fact table row that carries the product name as well as the product key stores the name once per sale instead of once per product, and offers the report author two Product Name fields that behave differently: the fact table's version cannot filter other fact tables and shows only the names that have sales. The dimension's copy is the one that should exist.\n\nHow to fix it\n\nStop loading the column on the fact table. In Power BI Desktop choose Transform data, select the fact table's query, and use Choose Columns or Remove Columns so the column never reaches the model; where the query reads a view or a stored procedure, drop it from the select list there instead and the refresh gets shorter too. A duplicate that is a DAX calculated column goes instead by right-clicking it in the Data pane and choosing Delete from model, or by removing its column Name = expression block from the table's TMDL file. Then point the visuals that used it at the dimension's column, which filters the way a report author expects, and where a measure needs the value at row grain, reach it with RELATED inside the measure rather than storing it again. Hiding the column is not a fix here: the rule never reads a column's visibility, so a hidden copy is reported exactly as a visible one is, and it still costs the same memory.\n\nWhen to ignore it\n\nCoincidence is the common false alarm. The test is the column's name and nothing else, so 'Sales'[Description] and 'Product'[Description] are reported as duplicates when one is a line note and the other a catalogue blurb. Read both columns before removing either. A copy kept on purpose is the other legitimate case: a fact table that carries a snapshot of the attribute as it was on the order date is not the dimension's current value and must not be replaced by it, and a column the source system denormalized for a composite key can be cheaper to keep than to rebuild. Check whether the two columns hold the same values for the same key, which a quick visual of both will answer, and ignore the finding where they do not. A plain copy of a slowly changing dimension's current name on a large fact table is what the rule is for.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = REMOVE_REDUNDANT_COLUMNS_IN_RELATED_TABLES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"REMOVE_REDUNDANT_COLUMNS_IN_RELATED_TABLES\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Matching is by column name only, exactly and with letter case respected, so two unrelated columns that happen to share a name fire too, and renaming the copy clears the finding without removing anything.\n- The direction matters. Only a column on the from side's table is reported, so the dimension's own copy is never named, and a column on the to side that duplicates a fact table column is not reported either.\n- A column that takes part in any relationship, on either side, is never reported. A foreign key whose name matches the dimension's key is therefore out of scope.\n- Any column on the related table counts as the duplicate, the relationship key and hidden columns included.\n- Cardinality is not tested, only the from and to sides of the relationship, so a one-to-one relationship counts the same as a many-to-one.\n- All three column kinds are in scope, so a loaded column, a DAX calculated column, and a calculated table's column are read alike.\n\nRead more: https://pbiplint.com/rules/remove-redundant-columns-in-related-tables",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n### Why it matters\n\nA fact table row that carries the product name as well as the product key stores the name once per sale instead of once per product, and offers the report author two Product Name fields that behave differently: the fact table's version cannot filter other fact tables and shows only the names that have sales. The dimension's copy is the one that should exist.\n\n### How to fix it\n\nStop loading the column on the fact table. In Power BI Desktop choose Transform data, select the fact table's query, and use Choose Columns or Remove Columns so the column never reaches the model; where the query reads a view or a stored procedure, drop it from the select list there instead and the refresh gets shorter too. A duplicate that is a DAX calculated column goes instead by right-clicking it in the Data pane and choosing Delete from model, or by removing its `column Name = expression` block from the table's TMDL file. Then point the visuals that used it at the dimension's column, which filters the way a report author expects, and where a measure needs the value at row grain, reach it with RELATED inside the measure rather than storing it again. Hiding the column is not a fix here: the rule never reads a column's visibility, so a hidden copy is reported exactly as a visible one is, and it still costs the same memory.\n\n### When to ignore it\n\nCoincidence is the common false alarm. The test is the column's name and nothing else, so `'Sales'[Description]` and `'Product'[Description]` are reported as duplicates when one is a line note and the other a catalogue blurb. Read both columns before removing either. A copy kept on purpose is the other legitimate case: a fact table that carries a snapshot of the attribute as it was on the order date is not the dimension's current value and must not be replaced by it, and a column the source system denormalized for a composite key can be cheaper to keep than to rebuild. Check whether the two columns hold the same values for the same key, which a quick visual of both will answer, and ignore the finding where they do not. A plain copy of a slowly changing dimension's current name on a large fact table is what the rule is for.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REMOVE_REDUNDANT_COLUMNS_IN_RELATED_TABLES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"REMOVE_REDUNDANT_COLUMNS_IN_RELATED_TABLES\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Matching is by column name only, exactly and with letter case respected, so two unrelated columns that happen to share a name fire too, and renaming the copy clears the finding without removing anything.\n- The direction matters. Only a column on the from side's table is reported, so the dimension's own copy is never named, and a column on the to side that duplicates a fact table column is not reported either.\n- A column that takes part in any relationship, on either side, is never reported. A foreign key whose name matches the dimension's key is therefore out of scope.\n- Any column on the related table counts as the duplicate, the relationship key and hidden columns included.\n- Cardinality is not tested, only the from and to sides of the relationship, so a one-to-one relationship counts the same as a many-to-one.\n- All three column kinds are in scope, so a loaded column, a DAX calculated column, and a calculated table's column are read alike.\n\nRead more: https://pbiplint.com/rules/remove-redundant-columns-in-related-tables",
  },
  REMOVE_ROLES_WITH_NO_MEMBERS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\nrole 'West Region'\n\tmodelPermission: read\n\n\ttablePermission Sales = 'Sales'[Region] = \"West\"\n\nAfter the fix\n\ntable Sales\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\nrole 'West Region'\n\tmodelPermission: read\n\n\tmember 'west.sales@contoso.com'\n\t\tmemberType: user\n\t\tidentityProvider: AzureAD\n\n\ttablePermission Sales = 'Sales'[Region] = \"West\"\n\nWhy it matters\n\nWhere a model carries its own membership, a role with no members filters nobody. An empty role leaves the next reviewer guessing whether it was never assigned, was removed on purpose, or was dropped by a failed deployment, which is exactly the question a security review has to answer. In the meantime the role still has to be read and understood by everyone who reviews the model, and it appears in every list of roles as though somebody were behind it.\n\nHow to fix it\n\nAssign the members where the model keeps them. For a semantic model published to the Power BI service, the roles are written in Power BI Desktop under Modeling, Manage roles, and the people are added after publishing: open the workspace, choose Security on the semantic model, pick the role, and add the users or the security groups. For a model whose membership lives in the files, add a member block under the role in its TMDL file, with the member's name on the declaration line and memberType and identityProvider beneath it. If the role is not used at all, delete it, in Desktop under Manage roles or by removing its file from the roles folder and its ref role line from model.tmdl.\n\nWhen to ignore it\n\nOn a Power BI semantic model, role membership is held in the service and is never written into the project files, so every role in the project is reported and every one of those findings is noise. The rule earns its place on a model whose roles carry their own members: an Analysis Services model, or one a deployment pipeline writes membership into.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = REMOVE_ROLES_WITH_NO_MEMBERS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"REMOVE_ROLES_WITH_NO_MEMBERS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Power BI Desktop never writes role members, so every role in a Desktop-authored project is flagged.\n- Only the member declarations under the role are counted. modelPermission and the role's table permissions make no difference, so a role that filters every table in the model reads exactly like one that does nothing.\n\nRead more: https://pbiplint.com/rules/remove-roles-with-no-members",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\nrole 'West Region'\n\tmodelPermission: read\n\n\ttablePermission Sales = 'Sales'[Region] = \"West\"\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Region\n\t\tdataType: string\n\t\tsourceColumn: Region\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\nrole 'West Region'\n\tmodelPermission: read\n\n\tmember 'west.sales@contoso.com'\n\t\tmemberType: user\n\t\tidentityProvider: AzureAD\n\n\ttablePermission Sales = 'Sales'[Region] = \"West\"\n```\n\n### Why it matters\n\nWhere a model carries its own membership, a role with no members filters nobody. An empty role leaves the next reviewer guessing whether it was never assigned, was removed on purpose, or was dropped by a failed deployment, which is exactly the question a security review has to answer. In the meantime the role still has to be read and understood by everyone who reviews the model, and it appears in every list of roles as though somebody were behind it.\n\n### How to fix it\n\nAssign the members where the model keeps them. For a semantic model published to the Power BI service, the roles are written in Power BI Desktop under Modeling, Manage roles, and the people are added after publishing: open the workspace, choose Security on the semantic model, pick the role, and add the users or the security groups. For a model whose membership lives in the files, add a `member` block under the role in its TMDL file, with the member's name on the declaration line and `memberType` and `identityProvider` beneath it. If the role is not used at all, delete it, in Desktop under Manage roles or by removing its file from the `roles` folder and its `ref role` line from `model.tmdl`.\n\n### When to ignore it\n\nOn a Power BI semantic model, role membership is held in the service and is never written into the project files, so every role in the project is reported and every one of those findings is noise. The rule earns its place on a model whose roles carry their own members: an Analysis Services model, or one a deployment pipeline writes membership into.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REMOVE_ROLES_WITH_NO_MEMBERS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"REMOVE_ROLES_WITH_NO_MEMBERS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Power BI Desktop never writes role members, so every role in a Desktop-authored project is flagged.\n- Only the member declarations under the role are counted. `modelPermission` and the role's table permissions make no difference, so a role that filters every table in the model reads exactly like one that does nothing.\n\nRead more: https://pbiplint.com/rules/remove-roles-with-no-members",
  },
  SET_ISAVAILABLEINMDX_TO_TRUE_ON_NECESSARY_COLUMNS: {
    text: "Example\n\nFires the rule\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tsourceColumn: Date\n\n\tcolumn 'Month Name'\n\t\tdataType: string\n\t\tsortByColumn: 'Month Number'\n\t\tsourceColumn: MonthName\n\n\tcolumn 'Month Number'\n\t\tdataType: int64\n\t\tisHidden\n\t\tisAvailableInMdx: false\n\t\tsourceColumn: MonthNumber\n\nAfter the fix\n\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tsourceColumn: Date\n\n\tcolumn 'Month Name'\n\t\tdataType: string\n\t\tsortByColumn: 'Month Number'\n\t\tsourceColumn: MonthName\n\n\tcolumn 'Month Number'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: MonthNumber\n\nWhy it matters\n\nA column that sorts another column, or sits in a hierarchy, is used through its attribute hierarchy, and that is exactly what setting IsAvailableInMdx to false removes. The result is a processing error, or a hierarchy that fails in Excel and other MDX clients, usually after someone set the property to false in bulk to save memory.\n\nHow to fix it\n\nPower BI Desktop has no setting for this property and never writes it, so the repair is in the TMDL file: delete the isAvailableInMdx: false line from under the column and the property goes back to its default of true. The other way to clear the same finding is to remove the need for the attribute hierarchy: take the column out of the hierarchy in Desktop's model view, or clear Sort by column under Column tools on the column that names it, and the rule stops reporting it. Tabular Editor shows the property in its property grid, which is a quicker way to clear it across the batch of columns a single bulk edit set.\n\nWhen to ignore it\n\nThere is no case for leaving it. A column reported here is one the engine needs an attribute hierarchy for, and the memory the property saves on it is small next to a model that fails to process. What is worth working out is why the property is there at all: it is almost always one bulk edit made across every hidden column, and the columns that needed the attribute hierarchy are the ones this rule lists. Clear those and leave the rest alone, so the saving stays where it does no harm.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = SET_ISAVAILABLEINMDX_TO_TRUE_ON_NECESSARY_COLUMNS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"SET_ISAVAILABLEINMDX_TO_TRUE_ON_NECESSARY_COLUMNS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- A column with no isAvailableInMdx line is true, because pbiplint applies that default wherever the property is absent. The line appears only where a tool wrote it, and the only value ever written is false, so this rule fires only where something set the property deliberately.\n- Variations are matched on the default column alone. pbiplint reads a variation's defaultColumn, so a column a variation reaches only through its default hierarchy is not protected here.\n- Both ends of a sort-by pair are covered. The column that does the sorting is reported, and so is the column that names it in sortByColumn, whenever the property is false on either.\n\nRead more: https://pbiplint.com/rules/set-isavailableinmdx-to-true-on-necessary-columns",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tsourceColumn: Date\n\n\tcolumn 'Month Name'\n\t\tdataType: string\n\t\tsortByColumn: 'Month Number'\n\t\tsourceColumn: MonthName\n\n\tcolumn 'Month Number'\n\t\tdataType: int64\n\t\tisHidden\n\t\tisAvailableInMdx: false\n\t\tsourceColumn: MonthNumber\n```\n\n**After the fix**\n\n```tmdl\ntable Date\n\tcolumn Date\n\t\tdataType: dateTime\n\t\tisKey\n\t\tsourceColumn: Date\n\n\tcolumn 'Month Name'\n\t\tdataType: string\n\t\tsortByColumn: 'Month Number'\n\t\tsourceColumn: MonthName\n\n\tcolumn 'Month Number'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: MonthNumber\n```\n\n### Why it matters\n\nA column that sorts another column, or sits in a hierarchy, is used through its attribute hierarchy, and that is exactly what setting IsAvailableInMdx to false removes. The result is a processing error, or a hierarchy that fails in Excel and other MDX clients, usually after someone set the property to false in bulk to save memory.\n\n### How to fix it\n\nPower BI Desktop has no setting for this property and never writes it, so the repair is in the TMDL file: delete the `isAvailableInMdx: false` line from under the column and the property goes back to its default of true. The other way to clear the same finding is to remove the need for the attribute hierarchy: take the column out of the hierarchy in Desktop's model view, or clear Sort by column under Column tools on the column that names it, and the rule stops reporting it. Tabular Editor shows the property in its property grid, which is a quicker way to clear it across the batch of columns a single bulk edit set.\n\n### When to ignore it\n\nThere is no case for leaving it. A column reported here is one the engine needs an attribute hierarchy for, and the memory the property saves on it is small next to a model that fails to process. What is worth working out is why the property is there at all: it is almost always one bulk edit made across every hidden column, and the columns that needed the attribute hierarchy are the ones this rule lists. Clear those and leave the rest alone, so the saving stays where it does no harm.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = SET_ISAVAILABLEINMDX_TO_TRUE_ON_NECESSARY_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"SET_ISAVAILABLEINMDX_TO_TRUE_ON_NECESSARY_COLUMNS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- A column with no `isAvailableInMdx` line is true, because pbiplint applies that default wherever the property is absent. The line appears only where a tool wrote it, and the only value ever written is `false`, so this rule fires only where something set the property deliberately.\n- Variations are matched on the default column alone. pbiplint reads a variation's `defaultColumn`, so a column a variation reaches only through its default hierarchy is not protected here.\n- Both ends of a sort-by pair are covered. The column that does the sorting is reported, and so is the column that names it in `sortByColumn`, whenever the property is false on either.\n\nRead more: https://pbiplint.com/rules/set-isavailableinmdx-to-true-on-necessary-columns",
  },
  SNOWFLAKE_SCHEMA_ARCHITECTURE: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\n\tcolumn 'Category ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: CategoryID\n\ntable Category\n\tcolumn 'Category ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CategoryID\n\n\tcolumn 'Category Name'\n\t\tdataType: string\n\t\tsourceColumn: CategoryName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nrelationship Product_Category\n\tfromColumn: Product.'Category ID'\n\ttoColumn: Category.'Category ID'\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\n\tcolumn 'Category Name'\n\t\tdataType: string\n\t\tsourceColumn: CategoryName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nWhy it matters\n\nIn a star schema every dimension relates directly to the fact table, so a filter on Category reaches Sales in one hop. When Category hangs off Product, which hangs off Sales, the filter travels two hops, the model view is harder to read, and any bi-directional relationship along the chain doubles the chance of ambiguity. The engine handles a snowflake, but it handles a star faster, and a report author understands a star at a glance.\n\nHow to fix it\n\nFold the sub-dimension into its parent so the parent carries the attributes directly. The best place is the source: have the view the Product query reads join Category and return Category Name as a column, and the refresh does the join once with indexes. Failing that, do it in Power BI Desktop: choose Transform data, select the Product query, use Merge Queries against the Category query on the key, expand the columns you want, then right-click the Category query and choose Delete, which removes the table and the relationship with it. Where the sub-dimension's query has to stay for another reason, delete only the relationship, which is the right-click menu on its line in the model view; in the TMDL file the same change is the sub-dimension's table block and its relationship block both going, and the parent gaining a plain column. Keep the sub-dimension where the chain has a reason to exist, which the next section describes, and where you do, prefer a single-direction relationship along it.\n\nWhen to ignore it\n\nSeveral shapes are reported that are not snowflakes at all. A bridge table sits between two dimensions by design, so it is the from side of one relationship and the to side of another and always will be. A sub-dimension shared by several parents, such as one Geography table that both Customer and Store point at, costs less as its own table than as a copy inside each parent. A very large sub-dimension is the third case: folding a million-row attribute table into its parent widens every row of the parent, and the two hops are cheaper than that. A chain of fact tables, such as a line table related to an order header that is itself related to Customer, reports the header for the same structural reason and is a perfectly ordinary design. What is worth acting on is a small lookup table that exists only because the source normalized it and nobody merged it back, which is most of what this rule finds.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = SNOWFLAKE_SCHEMA_ARCHITECTURE under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"SNOWFLAKE_SCHEMA_ARCHITECTURE\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The test is the from side and the to side of a relationship, not the many side and the one side, so a table in a one-to-one relationship can count.\n- Inactive relationships count. A table whose second relationship never comes alive outside USERELATIONSHIP is reported the same as one whose relationships are all active.\n- The two relationships need not form a chain through the same key or the same neighbour, so any table that is a parent of something and a child of something else is reported, whatever the shape around it.\n- Calculated tables are in scope and calculation groups are not, so a sub-dimension built with DISTINCT is checked and a calculation group is left alone.\n\nRead more: https://pbiplint.com/rules/snowflake-schema-architecture",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\n\tcolumn 'Category ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: CategoryID\n\ntable Category\n\tcolumn 'Category ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: CategoryID\n\n\tcolumn 'Category Name'\n\t\tdataType: string\n\t\tsourceColumn: CategoryName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n\nrelationship Product_Category\n\tfromColumn: Product.'Category ID'\n\ttoColumn: Category.'Category ID'\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsourceColumn: ProductID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\ntable Product\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tisKey\n\t\tsourceColumn: ProductID\n\n\tcolumn 'Product Name'\n\t\tdataType: string\n\t\tsourceColumn: ProductName\n\n\tcolumn 'Category Name'\n\t\tdataType: string\n\t\tsourceColumn: CategoryName\n\nrelationship Sales_Product\n\tfromColumn: Sales.'Product ID'\n\ttoColumn: Product.'Product ID'\n```\n\n### Why it matters\n\nIn a star schema every dimension relates directly to the fact table, so a filter on Category reaches Sales in one hop. When Category hangs off Product, which hangs off Sales, the filter travels two hops, the model view is harder to read, and any bi-directional relationship along the chain doubles the chance of ambiguity. The engine handles a snowflake, but it handles a star faster, and a report author understands a star at a glance.\n\n### How to fix it\n\nFold the sub-dimension into its parent so the parent carries the attributes directly. The best place is the source: have the view the Product query reads join Category and return Category Name as a column, and the refresh does the join once with indexes. Failing that, do it in Power BI Desktop: choose Transform data, select the Product query, use Merge Queries against the Category query on the key, expand the columns you want, then right-click the Category query and choose Delete, which removes the table and the relationship with it. Where the sub-dimension's query has to stay for another reason, delete only the relationship, which is the right-click menu on its line in the model view; in the TMDL file the same change is the sub-dimension's `table` block and its `relationship` block both going, and the parent gaining a plain column. Keep the sub-dimension where the chain has a reason to exist, which the next section describes, and where you do, prefer a single-direction relationship along it.\n\n### When to ignore it\n\nSeveral shapes are reported that are not snowflakes at all. A bridge table sits between two dimensions by design, so it is the from side of one relationship and the to side of another and always will be. A sub-dimension shared by several parents, such as one Geography table that both Customer and Store point at, costs less as its own table than as a copy inside each parent. A very large sub-dimension is the third case: folding a million-row attribute table into its parent widens every row of the parent, and the two hops are cheaper than that. A chain of fact tables, such as a line table related to an order header that is itself related to Customer, reports the header for the same structural reason and is a perfectly ordinary design. What is worth acting on is a small lookup table that exists only because the source normalized it and nobody merged it back, which is most of what this rule finds.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = SNOWFLAKE_SCHEMA_ARCHITECTURE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"SNOWFLAKE_SCHEMA_ARCHITECTURE\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The test is the from side and the to side of a relationship, not the many side and the one side, so a table in a one-to-one relationship can count.\n- Inactive relationships count. A table whose second relationship never comes alive outside USERELATIONSHIP is reported the same as one whose relationships are all active.\n- The two relationships need not form a chain through the same key or the same neighbour, so any table that is a parent of something and a child of something else is reported, whatever the shape around it.\n- Calculated tables are in scope and calculation groups are not, so a sub-dimension built with DISTINCT is checked and a calculation group is left alone.\n\nRead more: https://pbiplint.com/rules/snowflake-schema-architecture",
  },
  SPECIAL_CHARS_IN_OBJECT_NAMES: {
    text: "Example\n\nThe column in the first snippet has a tab between Order and ID where the second has a space, which is why the two look almost the same.\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order\tID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\nWhy it matters\n\nTabs and line breaks inside a name are invisible in most of the interface, so the object looks correct in the field list while every DAX reference, report binding, and deployment script has to reproduce the hidden character exactly. When one of them does not, you get a broken reference between two names that look identical on screen, which is one of the slowest kinds of model bug to track down. The same characters break CSV and Excel exports, where a line feed inside a column header splits the header across rows. Names should contain printable characters and ordinary spaces only.\n\nHow to fix it\n\nIn Power BI Desktop, double-click the field in the Data pane and retype the whole name, a space where the tab is, rather than trying to select the character. In the TMDL file the name is on the declaration line between single quotes: replace the tab with a space so the line reads column 'Order ID', and turn on your editor's whitespace display to see where the tab was. Renaming in Desktop updates the visuals bound to the field; a hand edit in the TMDL file does not, so open the report and check its visuals after one. Where the character arrives with a source column name, rename the column in Power Query as well, so the next column you add from that query comes in clean.\n\nWhen to ignore it\n\nThere is no case for it. A tab or a line break in a name buys nothing an ordinary space does not, and it costs every reference to the object an exact match on a character nobody can see.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = SPECIAL_CHARS_IN_OBJECT_NAMES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"SPECIAL_CHARS_IN_OBJECT_NAMES\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Only the tab reaches a name through a TMDL file. pbiplint splits a file into lines before it reads any declaration, so a line feed or a carriage return can never land inside a name it parses. The rule still tests for all three, so that a model built by other means is covered the way the source rule covers it.\n- The scope leaves out hierarchy levels, roles, named expressions, and data sources, so a tab in one of those names is not reported here.\n\nRead more: https://pbiplint.com/rules/special-chars-in-object-names",
    markdown:
      "### Example\n\nThe column in the first snippet has a tab between `Order` and `ID` where the second has a space, which is why the two look almost the same.\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order\tID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n```\n\n### Why it matters\n\nTabs and line breaks inside a name are invisible in most of the interface, so the object looks correct in the field list while every DAX reference, report binding, and deployment script has to reproduce the hidden character exactly. When one of them does not, you get a broken reference between two names that look identical on screen, which is one of the slowest kinds of model bug to track down. The same characters break CSV and Excel exports, where a line feed inside a column header splits the header across rows. Names should contain printable characters and ordinary spaces only.\n\n### How to fix it\n\nIn Power BI Desktop, double-click the field in the Data pane and retype the whole name, a space where the tab is, rather than trying to select the character. In the TMDL file the name is on the declaration line between single quotes: replace the tab with a space so the line reads `column 'Order ID'`, and turn on your editor's whitespace display to see where the tab was. Renaming in Desktop updates the visuals bound to the field; a hand edit in the TMDL file does not, so open the report and check its visuals after one. Where the character arrives with a source column name, rename the column in Power Query as well, so the next column you add from that query comes in clean.\n\n### When to ignore it\n\nThere is no case for it. A tab or a line break in a name buys nothing an ordinary space does not, and it costs every reference to the object an exact match on a character nobody can see.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = SPECIAL_CHARS_IN_OBJECT_NAMES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"SPECIAL_CHARS_IN_OBJECT_NAMES\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Only the tab reaches a name through a TMDL file. pbiplint splits a file into lines before it reads any declaration, so a line feed or a carriage return can never land inside a name it parses. The rule still tests for all three, so that a model built by other means is covered the way the source rule covers it.\n- The scope leaves out hierarchy levels, roles, named expressions, and data sources, so a tab in one of those names is not reported here.\n\nRead more: https://pbiplint.com/rules/special-chars-in-object-names",
  },
  SPLIT_DATE_AND_TIME: {
    text: "Why it matters\n\nA timestamp column has nearly as many distinct values as rows, so it does not compress and it cannot relate to a date table. Split into a date and a time, each column has a few thousand distinct values, compresses well, relates to a date table and a time table, and supports the questions people actually ask, which are by day and by hour rather than by second.\n\nHow to fix it\n\nFind the columns first. In Power BI Desktop's DAX query view, run a query such as EVALUATE ROW(\"with a time\", COUNTROWS(FILTER('Sales', HOUR('Sales'[Order Timestamp]) + MINUTE('Sales'[Order Timestamp]) + SECOND('Sales'[Order Timestamp]) > 0))) against each DateTime column you suspect. Then split the ones that come back. The fix lives where the column is loaded, not in a model property: in Transform data, select the column, use Add Column, Date, Date Only and Add Column, Time, Time Only, then remove the original column, or return the two columns from the view the query reads so the split folds into the refresh. Where nobody asks a question by hour, there is no need for a second column at all: select the column and use Transform, Date, Date Only, which drops the time part in place and collapses the cardinality in one step. Finish by relating the date column to the date table, and the time column to a time table of one row per minute or per hour if the reports need it.\n\nQuirks\n\n- The source rule reads a DateTimeWithHourMinSec annotation that a Tabular Editor script writes onto the model after loading VertiPaq statistics. A project's files never carry that annotation, which is why pbiplint lists the rule rather than running it.\n- The threshold is a count above zero, so a single row whose value is not at midnight reports a column of a million dates that are.\n- All three column kinds are in scope, so a calculated column that builds a timestamp is read the same way as a loaded one.\n\nRead more: https://pbiplint.com/rules/split-date-and-time",
    markdown:
      "### Why it matters\n\nA timestamp column has nearly as many distinct values as rows, so it does not compress and it cannot relate to a date table. Split into a date and a time, each column has a few thousand distinct values, compresses well, relates to a date table and a time table, and supports the questions people actually ask, which are by day and by hour rather than by second.\n\n### How to fix it\n\nFind the columns first. In Power BI Desktop's DAX query view, run a query such as `EVALUATE ROW(\"with a time\", COUNTROWS(FILTER('Sales', HOUR('Sales'[Order Timestamp]) + MINUTE('Sales'[Order Timestamp]) + SECOND('Sales'[Order Timestamp]) > 0)))` against each DateTime column you suspect. Then split the ones that come back. The fix lives where the column is loaded, not in a model property: in Transform data, select the column, use Add Column, Date, Date Only and Add Column, Time, Time Only, then remove the original column, or return the two columns from the view the query reads so the split folds into the refresh. Where nobody asks a question by hour, there is no need for a second column at all: select the column and use Transform, Date, Date Only, which drops the time part in place and collapses the cardinality in one step. Finish by relating the date column to the date table, and the time column to a time table of one row per minute or per hour if the reports need it.\n\n### Quirks\n\n- The source rule reads a `DateTimeWithHourMinSec` annotation that a Tabular Editor script writes onto the model after loading VertiPaq statistics. A project's files never carry that annotation, which is why pbiplint lists the rule rather than running it.\n- The threshold is a count above zero, so a single row whose value is not at midnight reports a column of a million dates that are.\n- All three column kinds are in scope, so a calculated column that builds a timestamp is read the same way as a loaded one.\n\nRead more: https://pbiplint.com/rules/split-date-and-time",
  },
  TRIM_OBJECT_NAMES: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order ID '\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\nWhy it matters\n\nA leading or trailing space is invisible in the field list but part of the name, so \"Sales \" and \"Sales\" are two objects to the engine, and a DAX reference, a visual binding, or a deployment script that uses the trimmed name fails against something that looks correct. The space usually arrives with a source column name or a paste. OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE reports the same names at error severity for a narrower set of object types.\n\nHow to fix it\n\nIn Power BI Desktop, double-click the field in the Data pane and retype the name without the space, or select the object and clear the space from Name in the Properties pane. In the TMDL file the name is on the declaration line, so column 'Order ID ' becomes column 'Order ID'. A data column carries its own sourceColumn, so the model name and the source column name are independent and trimming the model name does not change what the refresh loads. Renaming in Desktop updates the visuals bound to the field; a hand edit in the TMDL file does not, so open the report and check its visuals after one. Where the space arrives with a source column name, trim it in Power Query as well, so the next column you add from that query comes in clean.\n\nWhen to ignore it\n\nNo name should start or end with a space. A leading space is sometimes used to push a measure to the top of the field list; a display folder gathers the measure with the ones it belongs beside, and it does that without hiding a character in the name.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = TRIM_OBJECT_NAMES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"TRIM_OBJECT_NAMES\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The test is for a space character at the start or the end of the name. A name padded with a tab is not reported here; SPECIAL_CHARS_IN_OBJECT_NAMES covers that one.\n- The model object is in scope, and a finding on the model is always named Model whatever the model is called, so a stray space in the model's own name gives a finding with nothing in the line to show it. The model's name is on the model line in the TMDL file.\n\nRead more: https://pbiplint.com/rules/trim-object-names",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID '\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n```\n\n### Why it matters\n\nA leading or trailing space is invisible in the field list but part of the name, so \"Sales \" and \"Sales\" are two objects to the engine, and a DAX reference, a visual binding, or a deployment script that uses the trimmed name fails against something that looks correct. The space usually arrives with a source column name or a paste. `OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE` reports the same names at error severity for a narrower set of object types.\n\n### How to fix it\n\nIn Power BI Desktop, double-click the field in the Data pane and retype the name without the space, or select the object and clear the space from Name in the Properties pane. In the TMDL file the name is on the declaration line, so `column 'Order ID '` becomes `column 'Order ID'`. A data column carries its own `sourceColumn`, so the model name and the source column name are independent and trimming the model name does not change what the refresh loads. Renaming in Desktop updates the visuals bound to the field; a hand edit in the TMDL file does not, so open the report and check its visuals after one. Where the space arrives with a source column name, trim it in Power Query as well, so the next column you add from that query comes in clean.\n\n### When to ignore it\n\nNo name should start or end with a space. A leading space is sometimes used to push a measure to the top of the field list; a display folder gathers the measure with the ones it belongs beside, and it does that without hiding a character in the name.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = TRIM_OBJECT_NAMES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"TRIM_OBJECT_NAMES\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The test is for a space character at the start or the end of the name. A name padded with a tab is not reported here; `SPECIAL_CHARS_IN_OBJECT_NAMES` covers that one.\n- The model object is in scope, and a finding on the model is always named `Model` whatever the model is called, so a stray space in the model's own name gives a finding with nothing in the line to show it. The model's name is on the `model` line in the TMDL file.\n\nRead more: https://pbiplint.com/rules/trim-object-names",
  },
  UNNECESSARY_COLUMNS: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tcolumn 'Legacy Region Code'\n\t\tdataType: string\n\t\tisHidden\n\t\tsourceColumn: LegacyRegionCode\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nA hidden column that nothing uses is loaded, compressed, and refreshed for no reader. Key columns and helper columns pile up this way as a model evolves, and each one costs memory and refresh time in proportion to its cardinality. Removing them is the cheapest model diet there is.\n\nHow to fix it\n\nFor a data column, stop loading it: in Power BI Desktop, Transform data, select the query, and use Choose Columns or Remove Columns, so the column never reaches the model. Where the query reads a view or a stored procedure, drop it from the select list there instead and the refresh gets shorter too. For a calculated column, right-click it in the Data pane and choose Delete from model, or remove its column block from the table's TMDL file. If the column turns out to be needed after all, clear Is hidden in the Properties pane, or remove isHidden from under the column in the file, and the finding goes with it.\n\nWhen to ignore it\n\nReport usage is the case to check first. A hidden column that a visual, a slicer, or a report-level filter binds to is in use, and pbiplint reads the model, not the report, so open the reports before you delete anything. A column named as the default column of a variation is in the same position: the rule does not read variations, so it reports one that Power BI Desktop is quietly relying on. A staging column you are about to reference is a fair thing to leave for a week. A hidden key that no relationship uses is not: that one is what the rule is for.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = UNNECESSARY_COLUMNS under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"UNNECESSARY_COLUMNS\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- DAX references are approximated by pattern matching: references inside strings or comments count, and a bare [Column] reference resolves measure-first, then the expression's own table, then the first table with that column.\n- Report usage is not visible to this rule. A hidden column used only by a visual, a slicer, or a report-level filter is still flagged.\n- Variations are not tested, here or in the source rule, so a hidden column that a variation names as its default column is reported. SET_ISAVAILABLEINMDX_TO_TRUE_ON_NECESSARY_COLUMNS does read variations.\n- Row-level security is matched as text, ignoring letter case, the way the source rule matches it. A bare [Column] in any role's filter already counts as a DAX reference (see above), so the text test only adds the qualified forms Table[Column] and 'Table'[Column].\n\nRead more: https://pbiplint.com/rules/unnecessary-columns",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tcolumn 'Legacy Region Code'\n\t\tdataType: string\n\t\tisHidden\n\t\tsourceColumn: LegacyRegionCode\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Order ID'\n\t\tdataType: int64\n\t\tsourceColumn: OrderID\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nA hidden column that nothing uses is loaded, compressed, and refreshed for no reader. Key columns and helper columns pile up this way as a model evolves, and each one costs memory and refresh time in proportion to its cardinality. Removing them is the cheapest model diet there is.\n\n### How to fix it\n\nFor a data column, stop loading it: in Power BI Desktop, Transform data, select the query, and use Choose Columns or Remove Columns, so the column never reaches the model. Where the query reads a view or a stored procedure, drop it from the select list there instead and the refresh gets shorter too. For a calculated column, right-click it in the Data pane and choose Delete from model, or remove its `column` block from the table's TMDL file. If the column turns out to be needed after all, clear Is hidden in the Properties pane, or remove `isHidden` from under the column in the file, and the finding goes with it.\n\n### When to ignore it\n\nReport usage is the case to check first. A hidden column that a visual, a slicer, or a report-level filter binds to is in use, and pbiplint reads the model, not the report, so open the reports before you delete anything. A column named as the default column of a variation is in the same position: the rule does not read variations, so it reports one that Power BI Desktop is quietly relying on. A staging column you are about to reference is a fair thing to leave for a week. A hidden key that no relationship uses is not: that one is what the rule is for.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = UNNECESSARY_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"UNNECESSARY_COLUMNS\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- DAX references are approximated by pattern matching: references inside strings or comments count, and a bare `[Column]` reference resolves measure-first, then the expression's own table, then the first table with that column.\n- Report usage is not visible to this rule. A hidden column used only by a visual, a slicer, or a report-level filter is still flagged.\n- Variations are not tested, here or in the source rule, so a hidden column that a variation names as its default column is reported. `SET_ISAVAILABLEINMDX_TO_TRUE_ON_NECESSARY_COLUMNS` does read variations.\n- Row-level security is matched as text, ignoring letter case, the way the source rule matches it. A bare `[Column]` in any role's filter already counts as a DAX reference (see above), so the text test only adds the qualified forms `Table[Column]` and `'Table'[Column]`.\n\nRead more: https://pbiplint.com/rules/unnecessary-columns",
  },
  UNNECESSARY_MEASURES: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\n\tmeasure 'Total Sales Legacy' = SUMX('Sales', 'Sales'[Amount])\n\t\tisHidden\n\t\tformatString: #,0\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\nWhy it matters\n\nA hidden measure that no other measure uses can only be reached by a report that already had it, so it is either dead or a hidden dependency that breaks the day someone deletes it as dead. Either way it belongs in the open or in the bin.\n\nHow to fix it\n\nIn Power BI Desktop, right-click the measure in the Data pane and choose Delete from model, or, if reports still use it, clear Is hidden in the Properties pane so the dependency is visible to the next person. In the TMDL file, remove the measure block from its table, or remove isHidden from under it. Search the project for the measure's name before you delete it: pbiplint has already read every expression in the model, so what a search adds is the report files, which it does not read.\n\nWhen to ignore it\n\nReport usage is the case to check first. A hidden measure that a visual or a report-level filter binds to directly is in use, and pbiplint reads the model, not the report, so open the reports before you delete one. A measure you have written for a calculation item or a measure you have not finished is a fair thing to leave for as long as that lasts. A hidden measure nobody can name a caller for is what the rule is for.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = UNNECESSARY_MEASURES under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"UNNECESSARY_MEASURES\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- References from calculation items and from other hidden measures count as usage.\n- Report usage is not visible to this rule. A hidden measure used only by a visual is still flagged.\n- A row-level security filter counts as a DAX expression, so a measure named in one is used.\n- A bare [Measure] reference resolves by name across the whole model, ignoring letter case, so it counts wherever the measure lives. References are found by pattern, not by parsing, so a measure named inside a string or a comment counts as used too.\n\nRead more: https://pbiplint.com/rules/unnecessary-measures",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n\n\tmeasure 'Total Sales Legacy' = SUMX('Sales', 'Sales'[Amount])\n\t\tisHidden\n\t\tformatString: #,0\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\n\tmeasure 'Total Sales' = SUM('Sales'[Amount])\n\t\tformatString: #,0\n```\n\n### Why it matters\n\nA hidden measure that no other measure uses can only be reached by a report that already had it, so it is either dead or a hidden dependency that breaks the day someone deletes it as dead. Either way it belongs in the open or in the bin.\n\n### How to fix it\n\nIn Power BI Desktop, right-click the measure in the Data pane and choose Delete from model, or, if reports still use it, clear Is hidden in the Properties pane so the dependency is visible to the next person. In the TMDL file, remove the `measure` block from its table, or remove `isHidden` from under it. Search the project for the measure's name before you delete it: pbiplint has already read every expression in the model, so what a search adds is the report files, which it does not read.\n\n### When to ignore it\n\nReport usage is the case to check first. A hidden measure that a visual or a report-level filter binds to directly is in use, and pbiplint reads the model, not the report, so open the reports before you delete one. A measure you have written for a calculation item or a measure you have not finished is a fair thing to leave for as long as that lasts. A hidden measure nobody can name a caller for is what the rule is for.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = UNNECESSARY_MEASURES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"UNNECESSARY_MEASURES\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- References from calculation items and from other hidden measures count as usage.\n- Report usage is not visible to this rule. A hidden measure used only by a visual is still flagged.\n- A row-level security filter counts as a DAX expression, so a measure named in one is used.\n- A bare `[Measure]` reference resolves by name across the whole model, ignoring letter case, so it counts wherever the measure lives. References are found by pattern, not by parsing, so a measure named inside a string or a comment counts as used too.\n\nRead more: https://pbiplint.com/rules/unnecessary-measures",
  },
  "UNPIVOT_PIVOTED_(MONTH)_DATA": {
    text: "Example\n\nFires the rule\n\ntable Budget\n\tcolumn Department\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Department\n\n\tcolumn Jan\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Jan\n\n\tcolumn Feb\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Feb\n\n\tcolumn Mar\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Mar\n\n\tcolumn Apr\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Apr\n\n\tcolumn May\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: May\n\n\tcolumn Jun\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Jun\n\nAfter the fix\n\ntable Budget\n\tcolumn Department\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Department\n\n\tcolumn 'Month Name'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: MonthName\n\t\tsortByColumn: 'Month Number'\n\n\tcolumn 'Month Number'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: MonthNumber\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n\nWhy it matters\n\nA column per month is a spreadsheet layout. In a model it means a measure per month, no way to filter by date, no relationship to the date table, and a schema change every year. Unpivoted into one Month column and one Value column, with the month's start date beside them, the same data relates to the date table through that date and every measure and time intelligence function works over it.\n\nHow to fix it\n\nReshape the table where it is loaded. In Power BI Desktop choose Transform data, select the query, select the month columns, and use Unpivot Columns on the Transform tab, or select the columns that are not months and use Unpivot Other Columns so next year's column is picked up without an edit; then rename the Attribute and Value columns to something a report author will recognize, such as Month Name and Amount. Where the source is a warehouse, the same reshape belongs in a view there, and the refresh gets the finished shape for nothing. Back in the model, give the month column a Month Number column to sort by, which is Sort by column on the Column tools tab and sortByColumn in the TMDL file. A month name is text and cannot carry a relationship to a day-grain date table, so load the month's start date alongside it, as a Month Start column of the first of each month, and relate that column to the date table; time intelligence then works over the reshaped table. The rule reads the model's columns, so the finding clears as soon as the reshaped query is applied.\n\nWhen to ignore it\n\nA coincidence is the case to check for first, though it takes six of them at once. The month names are matched as substrings of the column names, so Janitorial Cost satisfies Jan, Margin satisfies Mar, Apron Sales satisfies Apr, and Junior Rate satisfies Jun; a table of numeric metrics carrying one such name for each of the six months is reported with no month in it anywhere. Read the column names before reshaping anything. A genuinely pivoted table can also be deliberate: a small budget entry table that a person maintains by hand in a spreadsheet is easier to fill in wide, and where it is a handful of rows, unpivoting it on the way in costs nothing and unpivoting it at the source costs an argument. What is not a legitimate exception is a wide fact table of months feeding visuals through twelve near-identical measures, which is the pattern the rule exists to catch.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = UNPIVOT_PIVOTED_(MONTH)_DATA under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"UNPIVOT_PIVOTED_(MONTH)_DATA\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- Only the first six months are tested, so a table with July through December and nothing else is never reported, and one with January through June is reported whether or not the rest of the year is there.\n- The names are matched as substrings of the upper-cased column name, so full names count and so do unrelated words: Margin matches MAR, January Budget matches JAN, and a table needs one match for each of the six months before it is reported.\n- The column that matches has to be numeric, meaning int64, decimal, or double. A month column loaded as text does not count, so a table of twelve text columns passes.\n- Tables and calculated tables are in scope; calculation groups are not.\n\nRead more: https://pbiplint.com/rules/unpivot-pivoted-month-data",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Budget\n\tcolumn Department\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Department\n\n\tcolumn Jan\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Jan\n\n\tcolumn Feb\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Feb\n\n\tcolumn Mar\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Mar\n\n\tcolumn Apr\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Apr\n\n\tcolumn May\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: May\n\n\tcolumn Jun\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Jun\n```\n\n**After the fix**\n\n```tmdl\ntable Budget\n\tcolumn Department\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: Department\n\n\tcolumn 'Month Name'\n\t\tdataType: string\n\t\tsummarizeBy: none\n\t\tsourceColumn: MonthName\n\t\tsortByColumn: 'Month Number'\n\n\tcolumn 'Month Number'\n\t\tdataType: int64\n\t\tisHidden\n\t\tsummarizeBy: none\n\t\tsourceColumn: MonthNumber\n\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsummarizeBy: sum\n\t\tsourceColumn: Amount\n```\n\n### Why it matters\n\nA column per month is a spreadsheet layout. In a model it means a measure per month, no way to filter by date, no relationship to the date table, and a schema change every year. Unpivoted into one Month column and one Value column, with the month's start date beside them, the same data relates to the date table through that date and every measure and time intelligence function works over it.\n\n### How to fix it\n\nReshape the table where it is loaded. In Power BI Desktop choose Transform data, select the query, select the month columns, and use Unpivot Columns on the Transform tab, or select the columns that are not months and use Unpivot Other Columns so next year's column is picked up without an edit; then rename the Attribute and Value columns to something a report author will recognize, such as Month Name and Amount. Where the source is a warehouse, the same reshape belongs in a view there, and the refresh gets the finished shape for nothing. Back in the model, give the month column a Month Number column to sort by, which is Sort by column on the Column tools tab and `sortByColumn` in the TMDL file. A month name is text and cannot carry a relationship to a day-grain date table, so load the month's start date alongside it, as a Month Start column of the first of each month, and relate that column to the date table; time intelligence then works over the reshaped table. The rule reads the model's columns, so the finding clears as soon as the reshaped query is applied.\n\n### When to ignore it\n\nA coincidence is the case to check for first, though it takes six of them at once. The month names are matched as substrings of the column names, so Janitorial Cost satisfies Jan, Margin satisfies Mar, Apron Sales satisfies Apr, and Junior Rate satisfies Jun; a table of numeric metrics carrying one such name for each of the six months is reported with no month in it anywhere. Read the column names before reshaping anything. A genuinely pivoted table can also be deliberate: a small budget entry table that a person maintains by hand in a spreadsheet is easier to fill in wide, and where it is a handful of rows, unpivoting it on the way in costs nothing and unpivoting it at the source costs an argument. What is not a legitimate exception is a wide fact table of months feeding visuals through twelve near-identical measures, which is the pattern the rule exists to catch.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = UNPIVOT_PIVOTED_(MONTH)_DATA` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"UNPIVOT_PIVOTED_(MONTH)_DATA\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- Only the first six months are tested, so a table with July through December and nothing else is never reported, and one with January through June is reported whether or not the rest of the year is there.\n- The names are matched as substrings of the upper-cased column name, so full names count and so do unrelated words: Margin matches MAR, January Budget matches JAN, and a table needs one match for each of the six months before it is reported.\n- The column that matches has to be numeric, meaning int64, decimal, or double. A month column loaded as text does not count, so a table of twelve text columns passes.\n- Tables and calculated tables are in scope; calculation groups are not.\n\nRead more: https://pbiplint.com/rules/unpivot-pivoted-month-data",
  },
  USE_THE_DIVIDE_FUNCTION_FOR_DIVISION: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = SUM(Sales[Amount]) / SUM(Sales[Quantity])\n\t\tformatString: #,0.00\n\nAfter the fix\n\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = DIVIDE(SUM(Sales[Amount]), SUM(Sales[Quantity]))\n\t\tformatString: #,0.00\n\nWhy it matters\n\nDividing by a zero or blank denominator with / produces an error, and an error in one cell takes down the whole visual with a generic message. DIVIDE returns blank in that case, or an alternate result you choose, so the visual shows a gap where the data has one instead of failing.\n\nHow to fix it\n\nPass the numerator and the denominator as the first two arguments, and add a third where blank is the wrong answer for an empty denominator:\n\nAverage Price = DIVIDE ( SUM ( Sales[Amount] ), SUM ( Sales[Quantity] ) )\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column and a calculation item are edited the same way. In the TMDL file, edit the expression after measure 'Average Price' =, after column Name = for a calculated column, or after calculationItem Name = in the calculation group.\n\nWhen to ignore it\n\nA denominator that cannot be zero makes the guard dead weight. Dividing by a literal, [Total Sales] / 12 for a monthly average, is the clearest case: there is no blank to protect against, and the operator says what it means. The same goes for a denominator the source constrains to be positive, as long as you can point at the constraint rather than at the data you happen to have today. Everywhere else, check what the visual should show when the denominator is empty and put that in DIVIDE's third argument.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = USE_THE_DIVIDE_FUNCTION_FOR_DIVISION under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"USE_THE_DIVIDE_FUNCTION_FOR_DIVISION\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- A slash after a number or a variable name is not matched: 1 / [Sales] and total / count pass. The pattern needs a closing bracket or parenthesis in front of the slash.\n- Division by a constant, [Sales] / 100, is flagged even though it cannot fail.\n- A slash that opens a comment is excluded, so SUM(Sales[Amount]) // note and SUM(Sales[Amount]) /* note */ + 1 pass.\n- The expression is read as raw text, so a bracket or a parenthesis before a slash inside a string literal counts.\n\nRead more: https://pbiplint.com/rules/use-the-divide-function-for-division",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = SUM(Sales[Amount]) / SUM(Sales[Quantity])\n\t\tformatString: #,0.00\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tcolumn Quantity\n\t\tdataType: int64\n\t\tsourceColumn: Quantity\n\tmeasure 'Average Price' = DIVIDE(SUM(Sales[Amount]), SUM(Sales[Quantity]))\n\t\tformatString: #,0.00\n```\n\n### Why it matters\n\nDividing by a zero or blank denominator with `/` produces an error, and an error in one cell takes down the whole visual with a generic message. DIVIDE returns blank in that case, or an alternate result you choose, so the visual shows a gap where the data has one instead of failing.\n\n### How to fix it\n\nPass the numerator and the denominator as the first two arguments, and add a third where blank is the wrong answer for an empty denominator:\n\n```\nAverage Price = DIVIDE ( SUM ( Sales[Amount] ), SUM ( Sales[Quantity] ) )\n```\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column and a calculation item are edited the same way. In the TMDL file, edit the expression after `measure 'Average Price' =`, after `column Name =` for a calculated column, or after `calculationItem Name =` in the calculation group.\n\n### When to ignore it\n\nA denominator that cannot be zero makes the guard dead weight. Dividing by a literal, `[Total Sales] / 12` for a monthly average, is the clearest case: there is no blank to protect against, and the operator says what it means. The same goes for a denominator the source constrains to be positive, as long as you can point at the constraint rather than at the data you happen to have today. Everywhere else, check what the visual should show when the denominator is empty and put that in DIVIDE's third argument.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = USE_THE_DIVIDE_FUNCTION_FOR_DIVISION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"USE_THE_DIVIDE_FUNCTION_FOR_DIVISION\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- A slash after a number or a variable name is not matched: `1 / [Sales]` and `total / count` pass. The pattern needs a closing bracket or parenthesis in front of the slash.\n- Division by a constant, `[Sales] / 100`, is flagged even though it cannot fail.\n- A slash that opens a comment is excluded, so `SUM(Sales[Amount]) // note` and `SUM(Sales[Amount]) /* note */ + 1` pass.\n- The expression is read as raw text, so a bracket or a parenthesis before a slash inside a string literal counts.\n\nRead more: https://pbiplint.com/rules/use-the-divide-function-for-division",
  },
  USE_THE_TREATAS_FUNCTION_INSTEAD_OF_INTERSECT: {
    text: "Example\n\nFires the rule\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Budgeted Product Sales' = CALCULATE([Total Sales], INTERSECT(VALUES(Sales[Product ID]), VALUES(Budget[Product ID])))\n\t\tformatString: #,0\n\ntable Budget\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Target\n\t\tdataType: decimal\n\t\tsourceColumn: Target\n\nAfter the fix\n\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Budgeted Product Sales' = CALCULATE([Total Sales], TREATAS(VALUES(Budget[Product ID]), Sales[Product ID]))\n\t\tformatString: #,0\n\ntable Budget\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Target\n\t\tdataType: decimal\n\t\tsourceColumn: Target\n\nWhy it matters\n\nINTERSECT is used to push a filter from one table to another when no relationship exists: take the values on one side and intersect them with the other. TREATAS does the same job by treating the first table's values as a filter on the second table's columns, and the engine applies it as a filter, which is much cheaper than materializing both sets and intersecting them.\n\nHow to fix it\n\nPass the values you are filtering by first and the column you are filtering second, and drop the VALUES call on the target side:\n\nBudgeted Product Sales = CALCULATE ( [Total Sales], TREATAS ( VALUES ( Budget[Product ID] ), Sales[Product ID] ) )\n\nThe argument order is the reverse of what INTERSECT reads most naturally, so check which side is the filter before you swap the call. In Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculation item is edited the same way from the model view. In the TMDL file, edit the expression after measure 'Budgeted Product Sales' =, or after calculationItem Name = in the calculation group.\n\nWhen to ignore it\n\nINTERSECT used as set logic rather than as a virtual relationship has no TREATAS equivalent. Counting the products that appear in both Sales and Budget, COUNTROWS(INTERSECT(VALUES(Sales[Product ID]), VALUES(Budget[Product ID]))), is asking for the overlap itself, not for a filter, and rewriting it with TREATAS would change what it answers. What to check is whether the result of the call is being counted or read, in which case leave it, or handed to CALCULATE as a filter, in which case the rule is right.\n\nTo ignore this rule on one object, add annotation pbiplint.ignore = USE_THE_TREATAS_FUNCTION_INSTEAD_OF_INTERSECT under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set \"USE_THE_TREATAS_FUNCTION_INSTEAD_OF_INTERSECT\": \"off\" under rules in pbiplint.config.json.\n\nQuirks\n\n- The test is for the text INTERSECT(, in any letter case and with any spacing before the parenthesis, anywhere in the expression. A mention inside a string literal or a comment counts.\n- Calculated columns are out of scope, so an INTERSECT inside a calculated column is not reported.\n- Only the object's own expression is read. A call inside a measure's dynamic format string is not reported.\n\nRead more: https://pbiplint.com/rules/use-the-treatas-function-instead-of-intersect",
    markdown:
      "### Example\n\n**Fires the rule**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Budgeted Product Sales' = CALCULATE([Total Sales], INTERSECT(VALUES(Sales[Product ID]), VALUES(Budget[Product ID])))\n\t\tformatString: #,0\n\ntable Budget\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Target\n\t\tdataType: decimal\n\t\tsourceColumn: Target\n```\n\n**After the fix**\n\n```tmdl\ntable Sales\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Amount\n\t\tdataType: decimal\n\t\tsourceColumn: Amount\n\tmeasure 'Total Sales' = SUM(Sales[Amount])\n\t\tformatString: #,0\n\tmeasure 'Budgeted Product Sales' = CALCULATE([Total Sales], TREATAS(VALUES(Budget[Product ID]), Sales[Product ID]))\n\t\tformatString: #,0\n\ntable Budget\n\tcolumn 'Product ID'\n\t\tdataType: int64\n\t\tsourceColumn: ProductID\n\tcolumn Target\n\t\tdataType: decimal\n\t\tsourceColumn: Target\n```\n\n### Why it matters\n\nINTERSECT is used to push a filter from one table to another when no relationship exists: take the values on one side and intersect them with the other. TREATAS does the same job by treating the first table's values as a filter on the second table's columns, and the engine applies it as a filter, which is much cheaper than materializing both sets and intersecting them.\n\n### How to fix it\n\nPass the values you are filtering by first and the column you are filtering second, and drop the VALUES call on the target side:\n\n```\nBudgeted Product Sales = CALCULATE ( [Total Sales], TREATAS ( VALUES ( Budget[Product ID] ), Sales[Product ID] ) )\n```\n\nThe argument order is the reverse of what INTERSECT reads most naturally, so check which side is the filter before you swap the call. In Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculation item is edited the same way from the model view. In the TMDL file, edit the expression after `measure 'Budgeted Product Sales' =`, or after `calculationItem Name =` in the calculation group.\n\n### When to ignore it\n\nINTERSECT used as set logic rather than as a virtual relationship has no TREATAS equivalent. Counting the products that appear in both Sales and Budget, `COUNTROWS(INTERSECT(VALUES(Sales[Product ID]), VALUES(Budget[Product ID])))`, is asking for the overlap itself, not for a filter, and rewriting it with TREATAS would change what it answers. What to check is whether the result of the call is being counted or read, in which case leave it, or handed to CALCULATE as a filter, in which case the rule is right.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = USE_THE_TREATAS_FUNCTION_INSTEAD_OF_INTERSECT` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"USE_THE_TREATAS_FUNCTION_INSTEAD_OF_INTERSECT\": \"off\"` under `rules` in `pbiplint.config.json`.\n\n### Quirks\n\n- The test is for the text `INTERSECT(`, in any letter case and with any spacing before the parenthesis, anywhere in the expression. A mention inside a string literal or a comment counts.\n- Calculated columns are out of scope, so an INTERSECT inside a calculated column is not reported.\n- Only the object's own expression is read. A call inside a measure's dynamic format string is not reported.\n\nRead more: https://pbiplint.com/rules/use-the-treatas-function-instead-of-intersect",
  },
};
